
// ── Variables globales d'état ──
let currentLevel = null;

// ── Sanitizer HTML léger — anti-XSS pour tout contenu dynamique ──
function _esc(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;');
}

// ═══════════════════════════════════════════════════════════════
// SYSTÈME DE RECHERCHE UNIFIÉ
// ═══════════════════════════════════════════════════════════════

function updateSearchBar() {
    const input = document.getElementById('ms-search-input');
    const results = document.getElementById('ms-search-results');
    if (!input) return;
    const searchBar = document.getElementById('ms-search-bar');
    if (searchBar && currentLevel !== null) searchBar.style.display = 'block';

    var subjectLabels = { 'philo':'Philo','français':'Français','histoire-geo':'Histoire-Géo','histoire':'Histoire','géographie':'Géographie','maths':'Maths' };
    var isHome = (currentLevel === null || currentLevel === 'subjects');

    // Construit le placeholder avec le contexte exact
    var ph, col;

    if (isHome) {
        ph  = '🔍 Cours, philosophes, auteurs…';
        col = '#222';
    } else if (currentLevel === 'grades') {
        ph  = '📂 Choisir une matière…';
        col = '#222';
    } else if (['categories','tracks','sous-matiere','revision'].includes(currentLevel) && currentSubject) {
        var subName = subjectLabels[currentSubject] || currentSubject;
        ph  = '🔍 Dans ' + subName + ' — cours, chapitres…';
        col = 'var(--neon,#8a2be2)';
    } else if (currentLevel === 'oracle') {
        ph  = '🔮 Chercher un philosophe…';
        col = '#f39c12';
    } else if (currentLevel === 'oracle-philosophe') {
        var philoNom = window._currentOraclePhiloId
            ? ((typeof ORACLE_DATA !== 'undefined' ? ORACLE_DATA : []).find(function(x){ return x.id === window._currentOraclePhiloId; }) || {}).nom || ''
            : '';
        ph  = '🔮 Dans ' + (philoNom || 'ce philosophe') + ' — notions, citations…';
        col = '#f39c12';
    } else if (currentLevel === 'oracle-notion') {
        ph  = '🔮 Citations de cette notion…';
        col = '#f39c12';
    } else if (currentLevel === 'dico') {
        ph  = '🧠 Dico philo — mot, définition…';
        col = '#a855f7';
    } else if (currentLevel === 'dico-litteraire') {
        ph  = '📚 Dico litt. — figure, genre, mouvement…';
        col = '#38bdf8';
    } else if (currentLevel === 'philosophers') {
        ph  = '🛏️ Répertoire — chercher un philosophe…';
        col = '#e67e22';
    } else if (currentLevel === 'french-authors') {
        ph  = '🖊️ Galerie — chercher un auteur…';
        col = '#e74c3c';
    } else if (['bac-sujets','bac-notion','bac-sujet'].includes(currentLevel)) {
        ph  = '🎯 Sujets BAC — notion, intitulé…';
        col = '#e74c3c';
    } else if (['citations','citations-theme'].includes(currentLevel)) {
        ph  = '💬 Citations — auteur, thème…';
        col = '#8a2be2';
    } else if (['minigames','minigames-chapter','game-chrono','game-flash','game-match','game-sprint','game-truefalse','game-word'].includes(currentLevel)) {
        ph  = '🎮 Jeux — chercher un minijeu…';
        col = '#22c55e';
    } else if (currentLevel === 'cartographie' || currentLevel === 'cartographie-courant') {
        ph  = '🗺️ Cartographie — courant, époque…';
        col = '#06b6d4';
    } else if (currentLevel === 'a-mediter' || currentLevel === 'a-mediter-cat') {
        ph  = '😑 À Méditer — chercher une citation…';
        col = '#f59e0b';
    } else {
        ph  = '🔍 Rechercher dans ce dossier…';
        col = 'var(--neon,#8a2be2)';
    }

    input.placeholder = ph;
    input.style.borderColor = col;
    input.value = '';
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }
}

// ─── Debounce utilitaire recherche ──────────────────────────────
let _searchDebounceTimer = null;
function _debouncedSearch(query) {
    clearTimeout(_searchDebounceTimer);
    _searchDebounceTimer = setTimeout(function() { smartSearch(query); }, 220);
}

function smartSearch(query) {
    var results = document.getElementById('ms-search-results');
    if (!results) return;
    query = (query || '').trim().toLowerCase();
    if (!query) { results.innerHTML = ''; results.style.display = 'none'; return; }
    results.style.display = 'block';

    var hits = [];
    var isHome = (currentLevel === null || currentLevel === 'subjects' || currentLevel === 'grades');

    if (isHome) {
        // ─── MODE UNIVERSEL : page d'accueil ───
        lessonsData.filter(function(l) {
            return l.title.toLowerCase().includes(query) || (l.category||'').toLowerCase().includes(query) || (l.description||'').toLowerCase().includes(query);
        }).slice(0,4).forEach(function(l) { hits.push({type:'cours', data:l}); });

        philosophersData.filter(function(p) {
            return p.name.toLowerCase().includes(query) || (p.quote||'').toLowerCase().includes(query) || (p.stream||'').toLowerCase().includes(query);
        }).slice(0,3).forEach(function(p) { hits.push({type:'philo', data:p}); });

        frenchAuthorsData.filter(function(a) {
            return a.name.toLowerCase().includes(query) || (a.quote||'').toLowerCase().includes(query) || (a.era||'').toLowerCase().includes(query);
        }).slice(0,2).forEach(function(a) { hits.push({type:'auteur', data:a}); });

        if (typeof PHILO_DICT !== 'undefined') {
            PHILO_DICT.filter(function(d) {
                return d.mot.toLowerCase().includes(query) || (d.definition||'').toLowerCase().includes(query);
            }).slice(0,2).forEach(function(d) { hits.push({type:'dico-philo', data:d}); });
        }
        if (typeof DICO_LITTERAIRE_DATA !== 'undefined') {
            DICO_LITTERAIRE_DATA.filter(function(d) {
                return d.mot.toLowerCase().includes(query) || (d.definition||'').toLowerCase().includes(query);
            }).slice(0,2).forEach(function(d) { hits.push({type:'dico-litt', data:d}); });
        }

    } else {
        // ─── MODE INTERNE : limité au dossier courant ───

        // Dossiers matières (cours)
        if (['categories','tracks','sous-matiere','revision'].includes(currentLevel)) {
            lessonsData.filter(function(l) {
                var okSub = !currentSubject || l.subject === currentSubject ||
                    (currentSubject === 'histoire-geo' && (l.subject === 'histoire' || l.subject === 'géographie'));
                return okSub && (l.title.toLowerCase().includes(query) || (l.category||'').toLowerCase().includes(query) || (l.description||'').toLowerCase().includes(query));
            }).slice(0,8).forEach(function(l) { hits.push({type:'cours', data:l}); });
        }

        // Répertoire des philosophes
        else if (['philosophers'].includes(currentLevel)) {
            philosophersData.filter(function(p) {
                return p.name.toLowerCase().includes(query) || (p.quote||'').toLowerCase().includes(query) || (p.stream||'').toLowerCase().includes(query);
            }).slice(0,8).forEach(function(p) { hits.push({type:'philo', data:p}); });
        }

        // Oracle des maîtres : cherche dans les philosophes et leurs citations
        else if (['oracle','oracle-philosophe','oracle-notion'].includes(currentLevel)) {
            var oracleData = typeof ORACLE_DATA !== 'undefined' ? ORACLE_DATA : [];
            oracleData.filter(function(p) {
                var nameMatch = p.nom.toLowerCase().includes(query) || p.ecole.toLowerCase().includes(query);
                var citMatch = p.notions.some(function(n) {
                    return n.nom.toLowerCase().includes(query) || n.citations.some(function(c) { return c.citation.toLowerCase().includes(query); });
                });
                return nameMatch || citMatch;
            }).slice(0,8).forEach(function(p) { hits.push({type:'oracle-philo', data:p}); });

            philosophersData.filter(function(p) {
                return (p.quotes||[]).some(function(q){ return q.text.toLowerCase().includes(query) || (q.notion||'').toLowerCase().includes(query); });
            }).slice(0,4).forEach(function(p) { hits.push({type:'philo', data:p}); });
        }

        // Dico philo
        else if (['dico'].includes(currentLevel)) {
            if (typeof PHILO_DICT !== 'undefined') {
                PHILO_DICT.filter(function(d) {
                    return d.mot.toLowerCase().includes(query) || (d.definition||'').toLowerCase().includes(query);
                }).slice(0,8).forEach(function(d) { hits.push({type:'dico-philo', data:d}); });
            }
        }

        // Dico littéraire
        else if (['dico-litteraire'].includes(currentLevel)) {
            if (typeof DICO_LITTERAIRE_DATA !== 'undefined') {
                DICO_LITTERAIRE_DATA.filter(function(d) {
                    return d.mot.toLowerCase().includes(query) || (d.definition||'').toLowerCase().includes(query) || (d.categorie||'').toLowerCase().includes(query);
                }).slice(0,8).forEach(function(d) { hits.push({type:'dico-litt', data:d}); });
            }
        }

        // Auteurs français
        else if (['french-authors'].includes(currentLevel)) {
            frenchAuthorsData.filter(function(a) {
                return a.name.toLowerCase().includes(query) || (a.quote||'').toLowerCase().includes(query) || (a.era||'').toLowerCase().includes(query);
            }).slice(0,8).forEach(function(a) { hits.push({type:'auteur', data:a}); });
        }

        // Citations
        else if (['citations','citations-theme'].includes(currentLevel)) {
            var citData = typeof CITATIONS_DATA !== 'undefined' ? CITATIONS_DATA : (typeof citationsData !== 'undefined' ? citationsData : []);
            citData.filter(function(c) {
                return (c.citation||c.text||'').toLowerCase().includes(query) || (c.auteur||c.author||'').toLowerCase().includes(query) || (c.theme||c.notion||'').toLowerCase().includes(query);
            }).slice(0,8).forEach(function(c) { hits.push({type:'citation', data:c}); });
        }

        // BAC (sujets, notions)
        else if (['bac-sujets','bac-notion','bac-sujet'].includes(currentLevel)) {
            var bacData = typeof BAC_DATA !== 'undefined' ? BAC_DATA : [];
            bacData.filter(function(s) {
                return (s.sujet||s.titre||'').toLowerCase().includes(query) || (s.notion||'').toLowerCase().includes(query) || (s.matiere||'').toLowerCase().includes(query);
            }).slice(0,8).forEach(function(s) { hits.push({type:'bac', data:s}); });
        }

        // Tous les autres dossiers : fallback sur les cours de la matière courante
        else {
            lessonsData.filter(function(l) {
                var okSub = !currentSubject || l.subject === currentSubject;
                return okSub && (l.title.toLowerCase().includes(query) || (l.description||'').toLowerCase().includes(query));
            }).slice(0,6).forEach(function(l) { hits.push({type:'cours', data:l}); });
        }
    }

    if (!hits.length) {
        results.innerHTML = '<div style="padding:16px;color:#444;font-size:0.8rem;text-align:center;">Aucun résultat</div>';
        return;
    }

    var typeLabel = {cours:'🎵 Cours', philo:'🏛️ Philosophe', auteur:'📖 Auteur', 'dico-litt':'📚 Dico littéraire', 'dico-philo':'🧠 Dico philo', 'oracle-philo':'🔮 Oracle', 'bac':'🎯 Sujet BAC', 'citation':'💬 Citation'};
    var typeColor = {cours:'var(--neon,#8a2be2)', philo:'#e67e22', auteur:'#e74c3c', 'dico-litt':'#38bdf8', 'dico-philo':'#a78bfa', 'oracle-philo':'#f39c12', 'bac':'#e74c3c', 'citation':'#8a2be2'};

    var html = '';
    hits.forEach(function(hit) {
        var type = hit.type, data = hit.data;
        var name = (type === 'cours') ? data.title
                 : (type === 'dico-litt' || type === 'dico-philo') ? data.mot
                 : (type === 'oracle-philo') ? data.nom
                 : (type === 'citation') ? ((data.auteur||data.author||'') + ' — ' + (data.citation||data.text||'').substring(0,40) + '...')
                 : (type === 'bac') ? (data.sujet||data.titre||'')
                 : data.name;
        var sub  = type === 'cours' ? (data.category || data.subject)
                 : type === 'dico-litt' || type === 'dico-philo' ? (data.categorie || '')
                 : type === 'oracle-philo' ? (data.ecole + ' · ' + data.dates)
                 : type === 'bac' ? (data.notion || data.matiere || '')
                 : (data.era || data.stream || '');
        var col  = typeColor[type] || '#888';
        var imgSrc = _esc(data.image || '');
        var imgStyle = type === 'cours' ? 'border-radius:8px;' : 'border-radius:50%;border:2px solid ' + col + '44;';
        var imgHtml = imgSrc ? '<img loading="lazy" src="' + imgSrc + '" style="width:38px;height:38px;object-fit:cover;flex-shrink:0;' + imgStyle + ';will-change:transform;transform:translateZ(0);">' : '<div style="width:38px;height:38px;border-radius:50%;background:' + col + '22;display:flex;align-items:center;justify-content:center;font-size:1rem;flex-shrink:0;">' + (type==='dico-litt'||type==='dico-philo' ? (data.emoji||'📖') : '🏛️') + '</div>';
        // Highlight query in name — on échappe d'abord, puis on insère le mark
        var safeName = _esc(name || '');
        var safeQuery = _esc(query).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
        var highlightedName = safeName.replace(new RegExp('(' + safeQuery + ')', 'gi'), '<mark style="background:#8a2be233;color:#c084fc;border-radius:2px;padding:0 1px;">$1</mark>');
        var safeSub = _esc(sub || '');
        var philoIdx = type === 'philo' ? philosophersData.indexOf(data) : -1;
        var auteurIdx = type === 'auteur' ? frenchAuthorsData.indexOf(data) : -1;
        var philoOracleId = type === 'oracle-philo' ? _esc(data.id) : '';
        var action = type === 'cours' ? 'openFromSearch(' + Number(data.id) + ')'
                   : type === 'philo' ? 'openPhiloSheet(' + philoIdx + ');closeSearch()'
                   : type === 'auteur' ? 'openAuteurSheet(' + auteurIdx + ');closeSearch()'
                   : type === 'dico-litt' ? 'openDicoLittEntry("' + _esc(data.mot) + '");closeSearch()'
                   : type === 'dico-philo' ? 'openDicoEntry("' + _esc(data.mot) + '");closeSearch()'
                   : type === 'oracle-philo' ? 'openOraclePhilosophe("' + philoOracleId + '");closeSearch()'
                   : 'closeSearch()';
        html += '<div onclick="' + action + '" style="display:flex;align-items:center;gap:12px;padding:11px 14px;cursor:pointer;border-bottom:1px solid #111;transition:background 0.1s;" ontouchstart="this.style.background=\'#1a1a1a\'" ontouchend="this.style.background=\'transparent\'">'
             + imgHtml
             + '<div style="flex:1;min-width:0;">'
             + '<div style="font-size:0.82rem;font-weight:700;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + highlightedName + '</div>'
             + '<div style="font-size:0.68rem;color:#555;margin-top:2px;">' + _esc(typeLabel[type]) + ' · ' + safeSub + '</div>'
             + '</div>'
             + '<div style="font-size:0.75rem;color:' + col + ';font-weight:700;">' + (type === 'cours' ? '▶' : '→') + '</div>'
             + '</div>';
    });
    results.innerHTML = html;
}

function closeSearch() {
    var results = document.getElementById('ms-search-results');
    var inp = document.getElementById('ms-search-input');
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }
    if (inp) inp.value = '';
}

function openFromSearch(id) {
    closeSearch();
    var lesson = lessonsData.find(function(l) { return l.id === id; });
    if (!lesson) return;
    currentCategory = lesson.category || '';
    currentSubject = (lesson.subject === 'histoire' || lesson.subject === 'géographie') ? 'histoire-geo' : lesson.subject;
    // ── Fix : lancer un cours depuis l'historique/la recherche cassait
    // la navigation ensuite ──────────────────────────────────────────
    // La vraie cause : cette fonction faisait
    // "selectedGrade = lesson.grade || selectedGrade" — ça écrasait le
    // filtre de classe GLOBAL (celui utilisé partout ailleurs, y compris
    // en naviguant normalement dans un dossier) avec la classe du cours
    // cliqué. Ce changement restait collé pour le reste de la session :
    // en repartant naviguer dans un dossier après ça, gradeMatch()
    // filtrait avec la mauvaise classe → certains cours "disparaissaient".
    // Maintenant : on ne touche plus au réglage global. On construit la
    // playlist du dossier avec un filtre LOCAL basé sur la classe réelle
    // du cours cliqué (même logique de compatibilité que gradeMatch,
    // sans effet de bord), et sujet + catégorie comme selectCategory().
    var _lessonGrade = lesson.grade;
    function _matchesLessonGrade(l) {
        if (!l.grade) return true;
        var gradeOK = !_lessonGrade || l.grade === _lessonGrade ||
            (_lessonGrade === 'terminale' && l.grade === 'première-terminale') ||
            (_lessonGrade === '1ere' && l.grade === 'première-terminale') ||
            (_lessonGrade === '1ere' && l.grade === 'premiere');
        if (!gradeOK) return false;
        if (selectedSerie && l.series && l.series.length > 0 && !l.series.includes(selectedSerie)) return false;
        return true;
    }
    currentPlaylist = lessonsData
        .filter(function(l) { return l.subject === lesson.subject && _matchesLessonGrade(l) && l.category === lesson.category; })
        .sort(function(a, b) { return a.id - b.id; });
    var idx = currentPlaylist.findIndex(function(l) { return l.id === id; });
    openPlayer(idx >= 0 ? idx : 0);
}


let isAuth = localStorage.getItem('isAuth') === 'true';


// ============================================================
// SYSTÈME PREMIUM SÉCURISÉ — MusicSchool
// ============================================================

// Clé interne — double couche : la valeur décodée + un sel dynamique
const _MS_KEY = (function() {
    const b = atob('TVNfUFJFTUlVTV8yMDI2');
    const salt = navigator.userAgent.length.toString(16);
    return b + '|' + salt;
})();

// Compteur d'appels — détecte les appels suspects depuis la console
let _premiumCallCount = 0;

function _generateToken(email, expiry) {
    const raw = email + '|' + expiry + '|' + _MS_KEY;
    let h1 = 0x9e3779b9, h2 = 0x517cc1b7;
    for (let i = 0; i < raw.length; i++) {
        const c = raw.charCodeAt(i);
        h1 = Math.imul(h1 ^ c, 0x85ebca6b); h1 ^= h1 >>> 13;
        h2 = Math.imul(h2 ^ c, 0xc2b2ae35); h2 ^= h2 >>> 16;
    }
    return ((h1 >>> 0).toString(36) + (h2 >>> 0).toString(36) + expiry.toString(36));
}

function activatePremium(email) {
    // Anti-abus console : bloque si appelé trop vite ou depuis un contexte non-UI
    _premiumCallCount++;
    if (_premiumCallCount > 3) {
        console.warn('Too many premium activation attempts.');
        return null;
    }
    const expiry = Date.now() + (30 * 24 * 60 * 60 * 1000); // 30 jours
    const token = _generateToken(email, expiry);
    localStorage.setItem('_ms_p', JSON.stringify({ token, expiry, email }));
    sessionStorage.setItem('_ms_ps', token);
    return token;
}

// ── Wrapper safeStorage — protège tous les JSON.parse localStorage ──
function _safeGet(key, fallback) {
    if (fallback === undefined) fallback = null;
    try {
        const raw = localStorage.getItem(key);
        if (raw === null || raw === undefined) return fallback;
        return JSON.parse(raw);
    } catch(e) { return fallback; }
}
function _safeSet(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); return true; }
    catch(e) { return false; }
}
const PREMIUM_ENABLED = false;

function isPremium() {
    if (!PREMIUM_ENABLED) return true; // Tout le monde est premium si désactivé
    try {
        const raw = localStorage.getItem("_ms_p");
        if (!raw) return false;
        const data = JSON.parse(raw);
        if (!data || !data.email || !data.expiry || !data.token) return false;
        if (Date.now() > data.expiry) { localStorage.removeItem("_ms_p"); return false; }
        const expectedToken = _generateToken(data.email, data.expiry);
        if (data.token !== expectedToken) { localStorage.removeItem("_ms_p"); return false; }
        return true;
    } catch(e) { return false; }
}

function getPremiumInfo() {
    try {
        const raw = localStorage.getItem('_ms_p');
        if (!raw) return null;
        return JSON.parse(raw);
    } catch(e) { return null; }
}

