// SUJETS BAC — Fonctions d'affichage
// ═══════════════════════════════════════════════════════════════

function selectProblematique(el) {
    // Désélectionner les autres dans le même groupe
    var parent = el.parentNode;
    var siblings = parent.querySelectorAll('div[id^="pb-"]');
    siblings.forEach(function(s) {
        s.style.background = '#111';
        s.style.borderColor = '#222';
        var num = s.querySelector('div');
        if (num) num.style.borderColor = '#333';
    });
    // Sélectionner celui-ci
    el.style.background = 'rgba(138,43,226,0.15)';
    el.style.borderColor = '#8a2be2';
    var num = el.querySelector('div');
    if (num) num.style.borderColor = '#8a2be2';
}

function openBacSujets() {
    window.scrollTo({ top: 0, behavior: 'instant' });
    currentLevel = 'bac-sujets';
    updateSearchBar();
    updateHeaderBtns();
    sectionTitle.innerText = 'SUJETS BAC';
    mainGrid.style.gridTemplateColumns = '1fr';
    mainGrid.innerHTML = '';

    // Header
    var header = document.createElement('div');
    header.style.cssText = 'grid-column:1/-1;text-align:center;padding:8px 0 20px;';
    header.innerHTML = '<div style="font-size:0.65rem;color:#555;letter-spacing:2px;font-weight:700;margin-bottom:6px;">PHILOSOPHIE · ' + BAC_SUJETS_DATA.length + ' NOTIONS · ' + BAC_SUJETS_DATA.reduce(function(t,n){return t+n.sujets.length;},0) + ' SUJETS</div>'
        + '<div style="font-size:0.75rem;color:#444;max-width:280px;margin:0 auto;line-height:1.5;">Clique sur une notion pour voir tous les sujets type bac avec arguments pour et contre.</div>';
    mainGrid.appendChild(header);

    BAC_SUJETS_DATA.forEach(function(notion, idx) {
        var card = document.createElement('div');
        card.style.cssText = 'background:linear-gradient(135deg,#141020 60%,' + notion.color + '15);border:1px solid ' + notion.color + '33;border-radius:18px;padding:16px 18px;cursor:pointer;transition:all 0.2s;position:relative;overflow:hidden;';
        card.innerHTML = '<div style="position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,' + notion.color + ',' + notion.color + '88);border-radius:18px 18px 0 0;"></div>'
            + '<div style="display:flex;align-items:center;gap:14px;">'
            + '<div style="font-size:2rem;flex-shrink:0;">' + notion.emoji + '</div>'
            + '<div style="flex:1;">'
            + '<div style="font-size:1rem;font-weight:900;color:#fff;margin-bottom:4px;">' + notion.notion + '</div>'
            + '<div style="font-size:0.72rem;color:#555;line-height:1.4;">' + notion.description + '</div>'
            + '</div>'
            + '<div style="text-align:right;flex-shrink:0;">'
            + '<div style="font-size:1.1rem;font-weight:900;color:' + notion.color + ';">' + notion.sujets.length + '</div>'
            + '<div style="font-size:0.6rem;color:#444;margin-top:1px;">sujets</div>'
            + '</div></div>';
        card.onclick = function() { openBacNotion(idx); };
        mainGrid.appendChild(card);
    });
    _restoreScrollAfterRender(_scrollKey('bac-sujets', ''));
}

function openBacNotion(idx) {
    window.scrollTo({ top: 0, behavior: 'instant' });
    var notion = BAC_SUJETS_DATA[idx];
    currentLevel = 'bac-notion';
    window._currentBacNotionIdx = idx;
    updateHeaderBtns();
    sectionTitle.innerText = notion.notion.toUpperCase();
    mainGrid.style.gridTemplateColumns = '1fr';
    mainGrid.innerHTML = '';

    var header = document.createElement('div');
    header.style.cssText = 'grid-column:1/-1;text-align:center;padding:0 0 16px;';
    header.innerHTML = '<div style="font-size:2rem;margin-bottom:8px;">' + notion.emoji + '</div>'
        + '<div style="font-size:0.7rem;color:' + notion.color + ';letter-spacing:2px;font-weight:700;margin-bottom:6px;">' + notion.sujets.length + ' SUJETS DISPONIBLES</div>'
        + '<div style="font-size:0.78rem;color:#555;max-width:300px;margin:0 auto;line-height:1.5;">' + notion.description + '</div>';
    mainGrid.appendChild(header);

    notion.sujets.forEach(function(sujet, sIdx) {
        var card = document.createElement('div');
        card.style.cssText = 'background:#111;border:1px solid #1e1e1e;border-radius:16px;padding:16px 18px;cursor:pointer;transition:all 0.2s;';
        card.innerHTML = '<div style="display:flex;align-items:flex-start;gap:12px;">'
            + '<div style="font-size:1.1rem;flex-shrink:0;margin-top:2px;">📋</div>'
            + '<div style="flex:1;">'
            + '<div style="font-size:0.88rem;font-weight:800;color:#fff;line-height:1.4;margin-bottom:6px;">' + sujet.titre + '</div>'
            + '<div style="font-size:0.7rem;color:#444;line-height:1.4;">' + sujet.enjeu.substring(0,80) + '…</div>'
            + '</div>'
            + '<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0;">'
            + '<div style="font-size:0.62rem;color:#27ae60;font-weight:700;">✅ ' + sujet.pour.length + ' pour</div>'
            + '<div style="font-size:0.62rem;color:#e74c3c;font-weight:700;">❌ ' + sujet.contre.length + ' contre</div>'
            + '</div></div>';
        card.onclick = function() { openBacSujet(idx, sIdx); };
        mainGrid.appendChild(card);
    });
    _restoreScrollAfterRender(_scrollKey('bac-notion', ''));
}

function openBacSujet(notionIdx, sujetIdx) {
    var notion = BAC_SUJETS_DATA[notionIdx];
    var sujet = notion.sujets[sujetIdx];
    currentLevel = 'bac-sujet';
    window._currentBacNotionIdx = notionIdx;
    window._currentBacSujetIdx = sujetIdx;
    updateHeaderBtns();
    sectionTitle.innerText = 'SUJET BAC';
    mainGrid.style.gridTemplateColumns = '1fr';

    var html = '<div style="grid-column:1/-1;">';

    // Titre
    html += '<div style="background:linear-gradient(135deg,#141020,' + notion.color + '18);border:1px solid ' + notion.color + '33;border-radius:16px;padding:18px;margin-bottom:14px;text-align:center;">'
        + '<div style="font-size:0.62rem;color:' + notion.color + ';letter-spacing:2px;font-weight:700;margin-bottom:8px;">' + notion.emoji + ' ' + notion.notion.toUpperCase() + '</div>'
        + '<div style="font-size:1rem;font-weight:900;color:#fff;line-height:1.4;">' + sujet.titre + '</div>'
        + '</div>';

    // Enjeu
    html += '<div style="background:#0e0e16;border:1px solid #1a1a2e;border-radius:14px;padding:16px;margin-bottom:14px;">'
        + '<div style="font-size:0.62rem;color:#888;letter-spacing:2px;font-weight:700;margin-bottom:8px;">📌 DE QUOI ÇA PARLE</div>'
        + '<div style="font-size:0.82rem;color:#aaa;line-height:1.6;">' + sujet.enjeu + '</div>'
        + '</div>';

    // Problématiques à choisir
    if (sujet.problematiques && sujet.problematiques.length) {
        html += '<div style="background:rgba(138,43,226,0.06);border:1px solid #8a2be233;border-radius:14px;padding:16px;margin-bottom:14px;">'
            + '<div style="font-size:0.62rem;color:#8a2be2;letter-spacing:2px;font-weight:700;margin-bottom:10px;">❓ PROBLÉMATIQUES POSSIBLES</div>'
            + '<div style="font-size:0.7rem;color:#555;margin-bottom:12px;">Clique sur celle qui te parle avant de lire les arguments</div>';
        sujet.problematiques.forEach(function(p, pi) {
            html += '<div id="pb-' + notionIdx + '-' + sujetIdx + '-' + pi + '" onclick="selectProblematique(this)" '
                + 'style="background:#111;border:1px solid #222;border-radius:10px;padding:12px 14px;margin-bottom:8px;cursor:pointer;transition:all 0.2s;display:flex;align-items:flex-start;gap:10px;">'
                + '<div style="flex-shrink:0;width:22px;height:22px;border-radius:50%;border:2px solid #333;display:flex;align-items:center;justify-content:center;font-size:0.65rem;color:#8a2be2;font-weight:900;margin-top:1px;">' + (pi+1) + '</div>'
                + '<div style="flex:1;font-size:0.8rem;color:#aaa;line-height:1.5;">' + p + '</div>'
                + '</div>';
        });
        html += '</div>';
    }

    // Pour
    html += '<div style="background:rgba(39,174,96,0.05);border:1px solid #27ae6033;border-radius:14px;padding:16px;margin-bottom:14px;">'
        + '<div style="font-size:0.62rem;color:#27ae60;letter-spacing:2px;font-weight:700;margin-bottom:12px;">✅ AUTEURS POUR</div>';
    sujet.pour.forEach(function(a) {
        html += '<div style="margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid #27ae6011;">'
            + '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:4px;">'
            + '<div style="font-size:0.82rem;font-weight:900;color:#27ae60;">' + a.auteur + '</div>'
            + '<div style="font-size:0.62rem;color:#27ae6088;font-style:italic;">' + a.oeuvre + ', ' + a.date + '</div>'
            + '</div>'
            + '<div style="font-size:0.8rem;color:#ccc;line-height:1.6;font-style:italic;">' + a.citation + '</div>'
            + '</div>';
    });
    html += '</div>';

    // Contre
    html += '<div style="background:rgba(231,76,60,0.05);border:1px solid #e74c3c33;border-radius:14px;padding:16px;margin-bottom:14px;">'
        + '<div style="font-size:0.62rem;color:#e74c3c;letter-spacing:2px;font-weight:700;margin-bottom:12px;">❌ AUTEURS CONTRE</div>';
    sujet.contre.forEach(function(a) {
        html += '<div style="margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid #e74c3c11;">'
            + '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:4px;">'
            + '<div style="font-size:0.82rem;font-weight:900;color:#e74c3c;">' + a.auteur + '</div>'
            + '<div style="font-size:0.62rem;color:#e74c3c88;font-style:italic;">' + a.oeuvre + ', ' + a.date + '</div>'
            + '</div>'
            + '<div style="font-size:0.8rem;color:#ccc;line-height:1.6;font-style:italic;">' + a.citation + '</div>'
            + '</div>';
    });
    html += '</div>';

    // Piste de dépassement
    html += '<div style="background:rgba(241,196,15,0.06);border:1px solid #f1c40f33;border-radius:14px;padding:16px;margin-bottom:14px;">'
        + '<div style="font-size:0.62rem;color:#f1c40f;letter-spacing:2px;font-weight:700;margin-bottom:8px;">💡 PISTE DE DÉPASSEMENT</div>'
        + '<div style="font-size:0.82rem;color:#aaa;line-height:1.6;">' + sujet.piste + '</div>'
        + '</div>';

    // Navigation entre sujets
    var prevSujet = sujetIdx > 0 ? sujetIdx - 1 : -1;
    var nextSujet = sujetIdx < notion.sujets.length - 1 ? sujetIdx + 1 : -1;
    html += '<div style="display:flex;gap:10px;">'
        + (prevSujet >= 0 ? '<div onclick="openBacSujet(' + notionIdx + ',' + prevSujet + ')" style="flex:1;padding:12px;background:#111;border:1px solid #222;border-radius:12px;text-align:center;cursor:pointer;font-size:0.78rem;color:#888;">← Sujet précédent</div>' : '<div style="flex:1;"></div>')
        + (nextSujet >= 0 ? '<div onclick="openBacSujet(' + notionIdx + ',' + nextSujet + ')" style="flex:1;padding:12px;background:' + notion.color + '22;border:1px solid ' + notion.color + '44;border-radius:12px;text-align:center;cursor:pointer;font-size:0.78rem;color:' + notion.color + ';font-weight:700;">Sujet suivant →</div>' : '<div style="flex:1;"></div>')
        + '</div>';

    html += '</div>';
    mainGrid.innerHTML = html;
}



