        html += '<div style="font-size:0.65rem;color:' + c.couleur + ';font-weight:700;">' + c.auteur + '</div>';
        html += '<div style="font-size:0.68rem;color:#666;line-height:1.4;">' + c.definition.substring(0,80) + '...</div>';
        html += '</div>';
