async function saveAIKey() {
    const input = document.getElementById('ai-key-input');
    const errEl = document.getElementById('ai-key-error');
    const key = (input.value || '').trim();
    if (!key) { errEl.textContent = 'Entre ta clé API.'; errEl.style.display = 'block'; return; }
    const btn = input.nextElementSibling.nextElementSibling;
    if (btn) { btn.textContent = 'Vérification...'; btn.disabled = true; }
    try {
        setAIKey(key);
        await callClaude('Tu es un assistant. Réponds juste "OK".', 'Test');
        document.getElementById('ai-overlay').remove();
        showAIHub();
    } catch(e) {
        if (btn) { btn.textContent = 'Activer l\'IA ✨'; btn.disabled = false; }
        setAIKey('');
        if (e.message === 'BAD_KEY') errEl.textContent = 'Clé invalide. Vérifie sur console.anthropic.com';
        else errEl.textContent = 'Erreur de connexion. Réessaie.';
        errEl.style.display = 'block';
    }
}

