function selectGenLeconGenre(genre) {
    document.querySelectorAll('#genlecon-genres > div').forEach(function(el) {
        el.style.borderColor = '#222';
        el.style.color = '#888';
    });
    const el = document.getElementById('genre-' + genre.replace(/\s/g,'_'));
    if (el) { el.style.borderColor = '#f59e0b'; el.style.color = '#f59e0b'; }
    const screen = document.getElementById('ai-overlay');
    if (screen) screen._selectedGenre = genre;
}

async function generateLeconIA() {
    const titleEl = document.getElementById('genlecon-title');
    const subjectEl = document.getElementById('genlecon-subject');
    const btn = document.getElementById('genlecon-btn');
    const result = document.getElementById('genlecon-result');
    const screen = document.getElementById('ai-overlay');

    const title = titleEl ? titleEl.value.trim() : '';
    const subject = subjectEl ? subjectEl.value : 'philo';
    const genre = screen ? (screen._selectedGenre || 'Trap') : 'Trap';

    if (!title) { titleEl && (titleEl.style.borderColor = '#e74c3c'); showToast('❌ Entre un titre !'); return; }

    btn.disabled = true;
    btn.innerHTML = '⏳ Génération en cours...';
    result.innerHTML = '<div style="text-align:center;padding:20px;color:#f59e0b;font-size:0.82rem;">L\'IA compose ta leçon... 🎵</div>';

    const systemPrompt = `Tu es Chicky on the Beat, créateur de leçons éducatives en format rap/musique pour l'app MusicSchool, destinée aux lycéens du Bac africain.

Tu génères une leçon complète en deux parties séparées par "===MEMO===".

PARTIE 1 — LYRICS (avant ===MEMO===) :
Structure Suno avec ces tags exacts : [Intro], [Verse 1], [Pre-Chorus], [Chorus], [Verse 2], [Bridge], [Verse 3], [Outro]
- [Intro] : bruit ambiance thématique entre parenthèses + "Chicky on the Beat. MusicSchool." + accroche
- Genre musical : ${genre}
- Niveau zéro : analogies de la vraie vie, exemples concrets chiffrés, zéro notation formelle incompréhensible à l'oral
- [Outro] : bruit de clôture + résumé en 2 phrases + "Chicky on the Beat. MusicSchool."
- Longueur : 40-60 lignes de lyrics

PARTIE 2 — MÉMO (après ===MEMO===) :
HTML direct (pas de markdown), structure :
- Titre h3 avec couleur appropriée
- Paragraphe d'introduction
- 3-4 blocs de leçon avec div style border-left
- Citation/message final dans un bloc centré
- Utilise uniquement des styles inline simples`;

    try {
        var raw = await callClaude(systemPrompt, 'Génère une leçon sur : "' + title + '" (matière : ' + subject + ', genre : ' + genre + ')', { maxTokens: 2500, temperature: 0.82 });
        const parts = raw.split('===MEMO===');
        const lyrics = parts[0].trim();
        const memo = parts[1] ? parts[1].trim() : '<p>Mémo non généré. Relance la génération.</p>';

        result.innerHTML = `
            <div style="background:#1a1000;border:1px solid #f59e0b33;border-radius:14px;padding:16px;margin-bottom:12px;">
                <div style="font-size:0.68rem;color:#f59e0b;font-weight:900;letter-spacing:1px;margin-bottom:10px;">🎵 LYRICS GÉNÉRÉS</div>
                <pre style="font-size:0.72rem;color:#ccc;line-height:1.7;white-space:pre-wrap;font-family:inherit;max-height:200px;overflow-y:auto;">${lyrics.substring(0,800)}${lyrics.length>800?'...(tronqué)':''}</pre>
            </div>
            <div style="background:#1a1000;border:1px solid #f59e0b33;border-radius:14px;padding:16px;margin-bottom:12px;">
                <div style="font-size:0.68rem;color:#f59e0b;font-weight:900;letter-spacing:1px;margin-bottom:10px;">📖 MÉMO GÉNÉRÉ</div>
                <div style="font-size:0.78rem;color:#ccc;max-height:150px;overflow-y:auto;">${memo.substring(0,600)}${memo.length>600?'...':''}</div>
            </div>
            <div style="background:#111;border:1px solid #22c55e33;border-radius:12px;padding:14px;text-align:center;">
                <div style="font-size:0.78rem;color:#22c55e;font-weight:700;margin-bottom:4px;">✅ Leçon générée !</div>
                <div style="font-size:0.68rem;color:#555;line-height:1.5;">Copie les lyrics → colle dans Suno pour générer le son.<br>Le mémo est prêt à être intégré dans l'app.</div>
            </div>
        `;
        // Store for copy
        window._lastGenLecon = { title, subject, genre, lyrics, memo };
        awardXP(15, 'Leçon générée 🎵');
        awardCoins(5, 'Génération IA');
    } catch(e) {
        result.innerHTML = '<div style="color:#e74c3c;font-size:0.8rem;padding:12px;background:#1a0a0a;border-radius:10px;">⚠️ Erreur : ' + (e.message || 'Connexion impossible') + '</div>';
    }
    btn.disabled = false;
    btn.innerHTML = '🎵 Générer une nouvelle leçon';
}

