function openShareLyricPicker(lessonId, lessonTitle) {
    const lesson = lessonsData.find(function(l) { return l.id === lessonId; });
    if (!lesson || !lesson.lyrics) { showToast('Pas de lyrics disponibles'); return; }
    const lines = lesson.lyrics.split('\n').filter(function(l) {
        return l.trim() && !l.startsWith('[') && !l.startsWith('(') && l.length > 15;
    });
    const overlay = document.createElement('div');
    overlay.id = 'lyric-picker-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#0a0a0a;overflow-y:auto;animation:fadeInUp 0.25s ease;';
    // Build DOM safely — no innerHTML with dynamic strings
    const wrap = document.createElement('div');
    wrap.style.cssText = 'max-width:480px;margin:0 auto;padding:20px 16px 40px;';
    const header = document.createElement('div');
    header.style.cssText = 'display:flex;align-items:center;gap:12px;margin-bottom:20px;';
    const backBtn = document.createElement('button');
    backBtn.style.cssText = 'width:36px;height:36px;border-radius:50%;background:#1a1a1a;border:none;color:#fff;cursor:pointer;font-size:1rem;';
    backBtn.textContent = '←';
    backBtn.onclick = function() { overlay.remove(); };
    const hTitle = document.createElement('div');
    hTitle.style.cssText = 'font-weight:900;color:#fff;font-size:0.9rem;';
    hTitle.textContent = 'Choisis un lyric à partager';
    header.appendChild(backBtn); header.appendChild(hTitle); wrap.appendChild(header);
    const hint = document.createElement('div');
    hint.style.cssText = 'font-size:0.72rem;color:#555;margin-bottom:14px;';
    hint.textContent = "Tape sur une ligne pour créer l'image";
    wrap.appendChild(hint);
    lines.forEach(function(line) {
        const card = document.createElement('div');
        card.style.cssText = 'padding:14px 16px;background:#111;border:1px solid #1e1e1e;border-radius:12px;margin-bottom:8px;cursor:pointer;font-size:0.82rem;color:#ccc;line-height:1.5;';
        card.textContent = line.trim();
        card.onclick = function() { overlay.remove(); shareLyricAsImage(line.trim(), lessonTitle); };
        wrap.appendChild(card);
    });
    overlay.appendChild(wrap);
    document.body.appendChild(overlay);
}

