// 📱 HISTORIQUE D'ÉCOUTE
// ═══════════════════════════════════════════════════════════════
function addToHistory(lessonId) {
    try {
        var account = _safeGet('userAccount', {});
        var classe = (account.classe || 'terminale').toLowerCase();
        var history = JSON.parse(localStorage.getItem('ms_listen_history') || '[]');
        // Stocker objet {id, classe, date} au lieu de juste l'id
        history = history.filter(function(e) { return (e.id || e) !== lessonId; });
        history.unshift({ id: lessonId, classe: classe, date: new Date().toISOString() });
        if (history.length > 50) history = history.slice(0, 50);
        localStorage.setItem('ms_listen_history', JSON.stringify(history));
        // 🔔 Notif intelligente : mémoriser la date du dernier cours écouté
        if (typeof _trackListenDate === 'function') _trackListenDate();
    } catch(e) {}
}

function getHistory(classeFilter) {
    try {
        var raw = JSON.parse(localStorage.getItem('ms_listen_history') || '[]');
        // Compatibilite anciens IDs stockes comme nombres
        var normalized = raw.map(function(e) {
            if (typeof e === 'number' || typeof e === 'string') return { id: e, classe: 'terminale', date: null };
            return e;
        });
        if (classeFilter) return normalized.filter(function(e) { return e.classe === classeFilter; });
        return normalized;
    } catch(e) { return []; }
}

// ═══════════════════════════════════════════════════════════════
// 🖼️ PARTAGE LYRIC EN IMAGE
// ═══════════════════════════════════════════════════════════════
function shareLyricAsImage(text, lessonTitle) {
    const canvas = document.createElement('canvas');
    const W = 1080, H = 1080;
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext('2d');

    // Fond dégradé
    const grad = ctx.createLinearGradient(0, 0, W, H);
    grad.addColorStop(0, '#0a0a0f');
    grad.addColorStop(0.5, '#1a0a2e');
    grad.addColorStop(1, '#0d0d0d');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Motif de points décoratifs
    ctx.fillStyle = 'rgba(138,43,226,0.08)';
    for (let i = 0; i < 80; i++) {
        const x = Math.random() * W, y = Math.random() * H;
        ctx.beginPath();
        ctx.arc(x, y, Math.random() * 3 + 1, 0, Math.PI * 2);
        ctx.fill();
    }

    // Ligne déco top
    const lineGrad = ctx.createLinearGradient(60, 0, W-60, 0);
    lineGrad.addColorStop(0, 'transparent');
    lineGrad.addColorStop(0.3, '#8a2be2');
    lineGrad.addColorStop(0.7, '#a855f7');
    lineGrad.addColorStop(1, 'transparent');
    ctx.strokeStyle = lineGrad;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(60, 120); ctx.lineTo(W-60, 120); ctx.stroke();

    // Logo MusicSchool
    ctx.font = 'bold 36px system-ui, sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.fillText('MusicSchool', W/2, 90);
    ctx.fillStyle = '#8a2be2';
    ctx.fillText('.', W/2 + ctx.measureText('MusicSchool').width/2 - 5, 90);

    // Titre leçon
    ctx.font = 'bold 28px system-ui, sans-serif';
    ctx.fillStyle = '#8a2be2';
    ctx.textAlign = 'center';
    ctx.fillText(lessonTitle, W/2, 170);

    // Guillemets décoratifs
    ctx.font = 'bold 120px serif';
    ctx.fillStyle = 'rgba(138,43,226,0.15)';
    ctx.textAlign = 'left';
    ctx.fillText('"', 60, 340);
    ctx.textAlign = 'right';
    ctx.fillText('"', W-60, H-140);

    // Texte lyric (wrap auto)
    ctx.font = '32px system-ui, sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    const maxW = W - 160;
    const lines = [];
    const words = text.split(' ');
    let cur = '';
    words.forEach(function(w) {
        const test = cur ? cur + ' ' + w : w;
        if (ctx.measureText(test).width > maxW) { if (cur) lines.push(cur); cur = w; }
        else cur = test;
    });
    if (cur) lines.push(cur);
    const lineH = 52;
    const totalH = lines.length * lineH;
    const startY = (H - totalH) / 2 + 20;
    lines.slice(0, 10).forEach(function(line, i) {
        ctx.fillText(line, W/2, startY + i * lineH);
    });

    // Ligne bas
    ctx.strokeStyle = lineGrad;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(60, H-120); ctx.lineTo(W-60, H-120); ctx.stroke();

    // Footer
    ctx.font = '24px system-ui, sans-serif';
    ctx.fillStyle = '#444';
    ctx.textAlign = 'center';
    ctx.fillText('Chicky on the Beat · MusicSchool', W/2, H-80);

    // Partager
    canvas.toBlob(function(blob) {
        if (navigator.share && navigator.canShare && navigator.canShare({ files: [new File([blob], 'lyrics.png', { type: 'image/png' })] })) {
            navigator.share({
                title: lessonTitle + ' — MusicSchool',
                files: [new File([blob], 'lyrics.png', { type: 'image/png' })]
            }).catch(function() {});
        } else {
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url; a.download = 'musicschool-lyrics.png';
            a.click();
            URL.revokeObjectURL(url);
            showToast('📸 Image sauvegardée !');
        }
    }, 'image/png');
}

