// 🔔 NOTIFICATIONS INTELLIGENTES — MusicSchool
// Rappels personnalisés basés sur la progression réelle
// ═══════════════════════════════════════════════════════════════

// Messages variés selon le contexte
const _NOTIF_MESSAGES = {
    streak_risk: [
        { title: '🔥 Alerte streak !', body: 'Ta série de {n}j est en danger. 5 min suffisent pour la garder !' },
        { title: '⚠️ {n} jours de suite !', body: 'Ne laisse pas ta flamme s\'éteindre ce soir 🔥' },
    ],
    daily_reminder: [
        { title: '📚 MusicSchool t\'attend', body: 'Tu n\'as pas encore révisé aujourd\'hui. Ton BAC approche !' },
        { title: '🎧 5 minutes de révision', body: 'Un cours en mode son = une notion maîtrisée. C\'est parti ?' },
        { title: '💡 Rappel du jour', body: 'Chaque jour compte avant le BAC. Lance un cours maintenant !' },
    ],
    weak_subject: [
        { title: '⚠️ {matiere} à bosser', body: 'Tu n\'as pas révisé {matiere} depuis longtemps. C\'est le moment !' },
        { title: '📖 Point faible détecté', body: '{matiere} : seulement {n} cours écoutés. Lance-toi !' },
    ],
    bac_countdown: [
        { title: '🎓 BAC dans {n} jours !', body: 'Chaque révision compte. Lance un cours ce soir !' },
        { title: '⏳ Plus que {n} jours', body: 'Le BAC approche — MusicSchool est là pour toi 💪' },
    ],
    motivation: [
        { title: '🌟 Tu peux le faire !', body: 'Les meilleurs élèves révisent même quand ils n\'en ont pas envie.' },
        { title: '🏆 Objectif BAC 2026', body: 'Un cours par jour = une matière maîtrisée. Fais-le maintenant !' },
    ]
};

// Date approximative du BAC en Côte d'Ivoire (fin mai/début juin)
const BAC_DATE_CI = new Date('2026-06-01');

function _getDaysUntilBac() {
    const now = new Date();
    const diff = BAC_DATE_CI - now;
    return Math.max(0, Math.floor(diff / (1000 * 60 * 60 * 24)));
}

function _getWeakSubject() {
    try {
        const history = JSON.parse(localStorage.getItem('ms_listen_history') || '[]');
        const completed = JSON.parse(localStorage.getItem('completedLessons') || '[]');
        const subjects = ['Philosophie', 'Histoire-Géo', 'Français', 'Mathématiques'];
        // Compter les cours écoutés par matière dans les 7 derniers jours
        const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
        const recentBySubject = {};
        subjects.forEach(s => recentBySubject[s] = 0);
        history.forEach(h => {
            if (h.ts && h.ts > sevenDaysAgo && h.subject && recentBySubject[h.subject] !== undefined) {
                recentBySubject[h.subject]++;
            }
        });
        // Trouver la matière la moins révisée récemment
        let minSubject = subjects[0], minCount = Infinity;
        subjects.forEach(s => {
            if (recentBySubject[s] < minCount) { minCount = recentBySubject[s]; minSubject = s; }
        });
        return { subject: minSubject, count: minCount };
    } catch(e) { return null; }
}

function _pickNotifMessage(type, vars = {}) {
    const pool = _NOTIF_MESSAGES[type] || _NOTIF_MESSAGES.daily_reminder;
    const tpl = pool[Math.floor(Math.random() * pool.length)];
    let title = tpl.title, body = tpl.body;
    Object.keys(vars).forEach(k => {
        title = title.replace('{' + k + '}', vars[k]);
        body = body.replace('{' + k + '}', vars[k]);
    });
    return { title, body };
}

function _sendSmartNotif() {
    if (Notification.permission !== 'granted') return;

    // Priorité 1 : streak en danger (pas encore révisé aujourd'hui)
    const streak = parseInt(localStorage.getItem('ms_streak') || '0');
    const lastDate = localStorage.getItem('ms_last_listen_date');
    const today = new Date().toDateString();
    const streakAtRisk = streak > 1 && lastDate && lastDate !== today;

    // Priorité 2 : matière faible
    const weak = _getWeakSubject();

    // Priorité 3 : compte à rebours BAC
    const daysLeft = _getDaysUntilBac();

    let msg;
    if (streakAtRisk) {
        msg = _pickNotifMessage('streak_risk', { n: streak });
    } else if (weak && weak.count === 0) {
        msg = _pickNotifMessage('weak_subject', { matiere: weak.subject, n: weak.count });
    } else if (daysLeft > 0 && daysLeft <= 30) {
        msg = _pickNotifMessage('bac_countdown', { n: daysLeft });
    } else {
        // Alterner entre daily_reminder et motivation aléatoirement
        const type = Math.random() > 0.5 ? 'daily_reminder' : 'motivation';
        msg = _pickNotifMessage(type);
    }

    // Utiliser le Service Worker si disponible (pour que ça marche même app fermée)
    if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage({
            type: 'SHOW_NOTIF',
            title: msg.title,
            body: msg.body,
            icon: '/icon-192.png',
            badge: '/icon-192.png',
            tag: 'ms-daily-reminder',
            url: window.location.origin
        });
    } else {
        new Notification(msg.title, {
            body: msg.body,
            icon: 'https://images.unsplash.com/photo-1519681393784-d120267933ba?w=64',
            tag: 'ms-daily-reminder'
        });
    }
}

async function requestNotifPermission() {
    if (!('Notification' in window)) {
        showToast('ℹ️ Active les notifications dans les paramètres');
        return;
    }
    if (Notification.permission === 'granted') {
        showToast('🔔 Notifications déjà activées !');
        scheduleNotifs();
        return;
    }
    if (Notification.permission === 'denied') {
        showToast('❌ Notifications bloquées — active-les dans les paramètres Chrome');
        return;
    }
    const perm = await Notification.requestPermission();
    if (perm === 'granted') {
        localStorage.setItem('ms_notifs', 'true');
        scheduleNotifs();
        // Notif de bienvenue immédiate
        const daysLeft = _getDaysUntilBac();
        new Notification('🎓 MusicSchool activé !', {
            body: daysLeft > 0
                ? `BAC dans ${daysLeft} jours — on va réviser ensemble chaque soir !`
                : 'Tu seras rappelé chaque soir pour réviser 💪',
            icon: 'https://images.unsplash.com/photo-1519681393784-d120267933ba?w=64'
        });
        showToast('🔔 Notifications activées ! Rappel chaque soir à 19h 🔥');
    } else {
        showToast('Notifications refusées.');
    }
}

function scheduleNotifs() {
    // Plusieurs rappels dans la journée selon le profil
    const slots = [
        { h: 7, m: 30 },  // Matin — rappel du jour
        { h: 13, m: 0 },  // Midi — rappel si pas encore révisé
        { h: 19, m: 0 },  // Soir — rappel principal
        { h: 21, m: 30 }, // Nuit — dernière chance
    ];

    slots.forEach(({ h, m }) => {
        const now = new Date();
        const target = new Date();
        target.setHours(h, m, 0, 0);
        if (target <= now) target.setDate(target.getDate() + 1);
        const delay = target - now;
        setTimeout(function fireSlot() {
            // Ne pas notifier si l'utilisateur a déjà révisé aujourd'hui
            // (sauf le rappel du soir à 19h qui passe toujours)
            const lastDate = localStorage.getItem('ms_last_listen_date');
            const today = new Date().toDateString();
            const alreadyStudied = lastDate === today;
            if (!alreadyStudied || h === 19) {
                _sendSmartNotif();
            }
            // Replanifier pour le lendemain
            setTimeout(fireSlot, 24 * 60 * 60 * 1000);
        }, delay);
    });
}

// Mémoriser la date du dernier cours écouté (pour les notifs intelligentes)
function _trackListenDate() {
    localStorage.setItem('ms_last_listen_date', new Date().toDateString());
}

// Vérifier au démarrage si notifs activées
(function initNotifs() {
    if (localStorage.getItem('ms_notifs') === 'true' && Notification.permission === 'granted') {
        scheduleNotifs();
    }
})();

