// showRevisionExpress() ancienne version supprimée — voir showRevisionExpress() ligne ~19262

function showRevisionExpressMaths() {
    const mathsLessons = lessonsData.filter(function(l) { return l.subject === 'maths' && l.quiz && l.quiz.length > 0; });
    const allQ = [];
    mathsLessons.forEach(function(l) {
        l.quiz.forEach(function(q) { allQ.push({ lesson: l.title, q: q.q, choices: q.choices, answer: q.answer }); });
    });

    // Shuffle
    for (let i = allQ.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [allQ[i], allQ[j]] = [allQ[j], allQ[i]];
    }
    const questions = allQ.slice(0, 5);
    let current = 0, score = 0;

    const overlay = document.createElement('div');
    overlay.id = 'rev-maths-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#0a0a0a;overflow-y:auto;animation:fadeInUp 0.25s ease;';

    function render() {
        if (current >= questions.length) {
            const pct = Math.round(score / questions.length * 100);
            overlay.innerHTML = `
                <div style="max-width:480px;margin:0 auto;padding:20px;">
                    <div style="text-align:center;padding:30px 0;">
                        <div style="font-size:3rem;margin-bottom:12px;">${pct===100?'🏆':pct>=60?'🔥':'📖'}</div>
                        <div style="font-size:2rem;font-weight:900;color:#22c55e;margin-bottom:6px;">${score}/${questions.length}</div>
                        <div style="font-size:0.85rem;color:#888;margin-bottom:24px;">${pct}% de bonnes réponses</div>
                        <div style="display:flex;gap:10px;justify-content:center;">
                            <button onclick="document.getElementById('rev-maths-overlay').remove();showRevisionExpressMaths();" style="padding:12px 20px;background:linear-gradient(135deg,#22c55e,#16a34a);border:none;border-radius:12px;color:#fff;font-weight:800;cursor:pointer;">🔄 Recommencer</button>
                            <button onclick="document.getElementById('rev-maths-overlay').remove();" style="padding:12px 20px;background:#1a1a1a;border:1px solid #333;border-radius:12px;color:#888;cursor:pointer;">Fermer</button>
                        </div>
                    </div>
                </div>`;
            awardXP(20, 'Révision Maths ✅');
            awardCoins(5, 'Révision Maths');
            return;
        }
        const q = questions[current];
        overlay.innerHTML = `
            <div style="max-width:480px;margin:0 auto;padding:20px 16px;">
                <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">
                    <button onclick="document.getElementById('rev-maths-overlay').remove()" style="width:36px;height:36px;border-radius:50%;background:#1a1a1a;border:none;color:#fff;cursor:pointer;font-size:0.9rem;">✕</button>
                    <div style="font-size:0.72rem;color:#22c55e;font-weight:700;">${current+1} / ${questions.length} · Score: ${score}</div>
                    <div style="font-size:0.72rem;color:#555;">🔢 Maths</div>
                </div>
                <div style="height:4px;background:#1a1a1a;border-radius:4px;margin-bottom:20px;overflow:hidden;">
                    <div style="height:100%;width:${(current/questions.length)*100}%;background:linear-gradient(90deg,#22c55e,#4ade80);border-radius:4px;"></div>
                </div>
                <div style="font-size:0.65rem;color:#22c55e;font-weight:700;letter-spacing:1px;margin-bottom:8px;">${q.lesson}</div>
                <div style="font-size:0.9rem;font-weight:700;color:#fff;line-height:1.5;margin-bottom:20px;">${q.q}</div>
                <div style="display:flex;flex-direction:column;gap:10px;" id="rev-maths-choices">
                    ${q.choices.map(function(c, i) {
                        return `<button onclick="answerRevMaths(${i},${q.answer})" style="padding:14px 16px;background:#1a1a1a;border:1.5px solid #2a2a2a;border-radius:12px;color:#ccc;font-size:0.82rem;text-align:left;cursor:pointer;transition:all 0.15s;">${c}</button>`;
                    }).join('')}
                </div>
            </div>`;
        window._revMathsCurrent = current;
        window._revMathsScore = score;
        window._revMathsQ = questions;
    }

    window.answerRevMaths = function(chosen, correct) {
        const btns = document.querySelectorAll('#rev-maths-choices button');
        btns.forEach(function(b, i) {
            b.disabled = true;
            if (i === correct) { b.style.borderColor = '#22c55e'; b.style.background = '#0a1a0a'; b.style.color = '#22c55e'; }
            else if (i === chosen && chosen !== correct) { b.style.borderColor = '#e74c3c'; b.style.background = '#1a0a0a'; b.style.color = '#e74c3c'; }
        });
        if (chosen === correct) score++;
        current++;
        setTimeout(render, 900);
    };

    document.body.appendChild(overlay);
    render();
}


