function appendChatMessage(role, text) {
    const messages = document.getElementById('ai-chat-messages');
    if (!messages) return;
    const isUser = role === 'user';
    const div = document.createElement('div');
    div.style.cssText = 'margin-bottom:10px;display:flex;flex-direction:column;align-items:' + (isUser ? 'flex-end' : 'flex-start') + ';';
    div.innerHTML = '<div style="max-width:88%;background:' + (isUser ? '#1a1a2e' : '#111') + ';border:1px solid ' + (isUser ? '#2a2a4e' : '#1e1e1e') + ';border-radius:' + (isUser ? '12px 12px 2px 12px' : '2px 12px 12px 12px') + ';padding:10px 14px;font-size:0.82rem;color:' + (isUser ? '#aaa' : '#ccc') + ';line-height:1.7;white-space:pre-wrap;">' + (isUser ? _escapeHtml(text) : text) + '</div>';
    messages.appendChild(div);
    messages.scrollTop = messages.scrollHeight;
}

async function sendChatMessage() {
    var input = document.getElementById('ai-chat-input');
    var msg = (input.value || '').trim();
    if (!msg) return;
    input.value = '';
    input.style.height = 'auto';
    appendChatMessage('user', msg);

    var messages = document.getElementById('ai-chat-messages');
    var typing = document.createElement('div');
    typing.id = 'chat-typing';
    typing.style.cssText = 'margin-bottom:10px;';
    typing.innerHTML = '<div style="display:inline-block;background:#111;border:1px solid #1e1e1e;border-radius:2px 12px 12px 12px;padding:10px 14px;font-size:0.78rem;color:#444;">● en train d&#39;écrire...</div>';
    messages.appendChild(typing);
    messages.scrollTop = messages.scrollHeight;
    input.disabled = true;

    var systemPrompt = 'Tu es un assistant éducatif brillant intégré dans MusicSchool, une app de révision pour le Bac africain (Terminale A et D — Côte d\'Ivoire, Sénégal, Cameroun etc.).'
        + ' Tu aides sur : philosophie, auteurs littéraires, histoire, géographie, mathématiques, notions du bac, méthodes dissertation/commentaire/explication de texte.'
        + ' Tu t\'adaptes au niveau lycéen : exemples concrets, langage clair, encourageant. Tu mémorises la conversation entière pour être cohérent dans tes réponses.'
        + ' Si une question est hors cadre scolaire strict, tu guides doucement.'
        + ' Tes réponses : 150-300 mots max, bien structurées, parfois avec des listes courtes si utile.';

    if (!window._chatConv) window._chatConv = createConversation();
    addToConversation(window._chatConv, 'user', msg);

    try {
        incrementAIUsage();
        var historyForAPI = window._chatConv.history.slice(0, -1);
        var resp = await callClaude(systemPrompt, msg, { history: historyForAPI, maxTokens: 800, temperature: 0.75 });
        addToConversation(window._chatConv, 'assistant', resp);
        var t = document.getElementById('chat-typing');
        if (t) t.remove();
        appendChatMessage('assistant', resp);
        awardXP(3, 'Chat IA 💬');
    } catch(e) {
        var t = document.getElementById('chat-typing');
        if (t) t.remove();
        appendChatMessage('assistant', '⚠️ Connexion interrompue. Réessaie dans quelques secondes.');
    }
    input.disabled = false;
    input.focus();
}
