async function generateQuizQuestion() {
    const notion = document.getElementById('ai-quiz-notion').value;
    const qDiv = document.getElementById('ai-quiz-question');
    const qText = document.getElementById('ai-quiz-q-text');
    const answerWrap = document.getElementById('ai-quiz-answer-wrap');
    qDiv.style.display = 'block';
    qText.textContent = '...génération en cours...';
    answerWrap.style.display = 'none';
    document.getElementById('ai-result').style.display = 'none';
    const systemPrompt = 'Tu es un professeur de philosophie qui génère des questions de dissertation ou d\'explication de texte niveau Terminale bac français. Génère UNE SEULE question courte et précise sur la notion demandée. La question doit être ouverte, philosophiquement riche, type bac. Donne uniquement la question, rien d\'autre.';
    try {
        incrementAIUsage();
        const q = await callClaude(systemPrompt, 'Génère une question sur la notion : ' + notion);
        qText.textContent = q.trim();
        window._currentQuizQuestion = q.trim();
        window._currentQuizNotion = notion;
        answerWrap.style.display = 'block';
    } catch(e) {
        qText.textContent = 'Erreur : ' + e.message;
    }
}

async function submitQuizAnswer() {
    const answer = (document.getElementById('ai-quiz-answer').value || '').trim();
    if (!answer) { showToast('✏️ Écris ta réponse d\'abord !'); return; }
    const result = document.getElementById('ai-result');
    result.style.display = 'block';
    result.innerHTML = '<div style="text-align:center;padding:16px;"><div style="font-size:1.3rem;animation:spin 1s linear infinite;display:inline-block;">⚙️</div></div>';
    const systemPrompt = 'Tu es un professeur de philosophie bac français. Tu évalues la réponse d\'un élève à une question philosophique. Donne : 1) NOTE SUR 20, 2) CE QUI EST BIEN (2 points), 3) CE QUI MANQUE (2 points), 4) UN ARGUMENT CLÉ que l\'élève aurait pu utiliser avec un auteur. Sois encourageant et précis.';
    const userMsg = 'Question : ' + (window._currentQuizQuestion || '') + '\n\nRéponse de l\'élève :\n' + answer;
    try {
        incrementAIUsage();
        var resp = await callClaude(systemPrompt, userMsg, { maxTokens: 1200, temperature: 0.6 });
        result.innerHTML = '<div style="background:#0e0e16;border:1px solid #e67e2233;border-radius:14px;padding:16px;">'
            + '<div style="font-size:0.65rem;color:#e67e22;letter-spacing:2px;font-weight:700;margin-bottom:12px;">📊 ÉVALUATION IA</div>'
            + '<div style="font-size:0.82rem;color:#ccc;line-height:1.8;white-space:pre-wrap;">' + resp + '</div>'
            + '</div>'
            + '<button onclick="openAIQuiz()" style="width:100%;margin-top:12px;padding:12px;background:#111;border:1px solid #222;border-radius:10px;color:#888;font-size:0.82rem;cursor:pointer;">Nouvelle question →</button>';
    } catch(e) {
        result.innerHTML = '<div style="color:#e74c3c;font-size:0.8rem;padding:10px;">Erreur : ' + e.message + '</div>';
    }
}

// MODE 4 — Débattre avec un philosophe
function openAIDebat() {
    const philos = [
        { name: 'Socrate', emoji: '🏛️', desc: 'Maïeutique · questionne tout', persona: 'Tu incarnes Socrate. Tu réponds uniquement par des questions pour amener l\'élève à trouver lui-même la vérité. Tu utilises la méthode maïeutique. Tu parles en grec ancien parfois. Tu es ironique et bienveillant.' },
        { name: 'Nietzsche', emoji: '⚡', desc: 'Volonté de puissance · provocateur', persona: 'Tu incarnes Nietzsche. Tu es provocateur, passionné, parfois violent dans tes formules. Tu parles de volonté de puissance, de surhomme, tu critiques la morale des esclaves. Tu utilises des aphorismes percutants.' },
        { name: 'Kant', emoji: '📐', desc: 'Impératif catégorique · rigueur', persona: 'Tu incarnes Kant. Tu es rigoureux, méthodique, tu structures toujours ta pensée. Tu parles de devoir, d\'impératif catégorique, de raison pure et pratique. Tu es formel mais pédagogue.' },
        { name: 'Simone de Beauvoir', emoji: '✊', desc: 'Féminisme · existentialisme', persona: 'Tu incarnes Simone de Beauvoir. Tu parles de liberté, d\'émancipation, de condition féminine. Tu es engagée, lucide, tu lies philosophie et vécu concret. Tu cites Sartre parfois mais avec ton regard propre.' },
        { name: 'Épicure', emoji: '🌿', desc: 'Ataraxie · plaisir sage', persona: 'Tu incarnes Épicure. Tu es calme, sage, bienveillant. Tu parles d\'ataraxie, de plaisirs simples, d\'amitié. Tu dédramatises tout. Tu rappelles que la mort n\'est rien pour nous.' },
    ];

    let philoCards = '';
    philos.forEach(function(p, i) {
        philoCards += '<div onclick="selectPhilo(' + i + ')" id="philo-card-' + i + '" style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:12px 14px;cursor:pointer;display:flex;align-items:center;gap:10px;margin-bottom:8px;">'
            + '<div style="font-size:1.5rem;">' + p.emoji + '</div>'
            + '<div><div style="font-size:0.88rem;font-weight:800;color:#fff;">' + p.name + '</div>'
            + '<div style="font-size:0.7rem;color:#555;">' + p.desc + '</div></div>'
            + '</div>';
    });

    const html = '<div style="font-size:0.72rem;color:#555;margin-bottom:16px;">Choisis un philosophe et débats avec lui. Il répond dans son style authentique.</div>'
        + philoCards
        + '<div id="ai-debat-chat" style="display:none;">'
        + '<div id="ai-debat-messages" style="min-height:150px;margin-bottom:12px;"></div>'
        + '<div style="display:flex;gap:8px;">'
        + '<input id="ai-debat-input" type="text" placeholder="Pose ta question..." style="flex:1;background:#111;border:1px solid #222;border-radius:10px;padding:11px 14px;color:#fff;font-size:0.82rem;outline:none;" onkeydown="if(event.key===\'Enter\')sendDebatMessage()">'
        + '<button onclick="sendDebatMessage()" style="padding:11px 16px;background:#8e44ad;border:none;border-radius:10px;color:#fff;font-size:0.9rem;cursor:pointer;">→</button>'
        + '</div></div>'
        + '<div id="ai-result" style="display:none;"></div>';
    createAIScreen('Débattre avec un philosophe', '🏛️', '#8e44ad', html);
    window._philos = philos;
    window._selectedPhilo = null;
    window._debatHistory = [];
}

function selectPhilo(idx) {
    window._selectedPhilo = window._philos[idx];
    window._debatHistory = [];
    window._debatConv = createConversation();
    // Highlight
    window._philos.forEach(function(_, i) {
        const card = document.getElementById('philo-card-' + i);
        if (card) card.style.borderColor = i === idx ? '#8e44ad' : '#1e1e1e';
    });
    document.getElementById('ai-debat-chat').style.display = 'block';
    const messages = document.getElementById('ai-debat-messages');
    const p = window._selectedPhilo;
    messages.innerHTML = '<div style="background:#8e44ad22;border:1px solid #8e44ad33;border-radius:2px 12px 12px 12px;padding:12px 14px;font-size:0.82rem;color:#ccc;line-height:1.6;margin-bottom:10px;">'
        + '<strong style="color:#8e44ad;">' + p.emoji + ' ' + p.name + '</strong> est prêt à débattre. Que veux-tu lui demander ?</div>';
}

async function sendDebatMessage() {
    const input = document.getElementById('ai-debat-input');
    const msg = (input.value || '').trim();
    if (!msg || !window._selectedPhilo) return;
    input.value = '';
    const messages = document.getElementById('ai-debat-messages');
    const p = window._selectedPhilo;

    // Afficher le message user
    messages.innerHTML += '<div style="background:#1a1a2e;border-radius:12px 12px 2px 12px;padding:10px 14px;font-size:0.8rem;color:#aaa;margin-bottom:8px;text-align:right;">' + _escapeHtml(msg) + '</div>';

    // Indicateur de frappe
    const typing = document.createElement('div');
    typing.id = 'ai-typing';
    typing.style.cssText = 'background:#111;border:1px solid #222;border-radius:2px 12px 12px 12px;padding:10px 14px;font-size:0.8rem;color:#555;margin-bottom:8px;';
    typing.textContent = p.name + ' réfléchit...';
    messages.appendChild(typing);
    messages.scrollTop = messages.scrollHeight;

    try {
        incrementAIUsage();
        if (!window._debatConv) window._debatConv = createConversation();
        addToConversation(window._debatConv, 'user', msg);
        var debatHistory = window._debatConv.history.slice(0, -1);
        var debatSystemPrompt = p.persona + ' Tu es dans une conversation philosophique avec un lycéen. Réponds en 3-5 phrases maximum dans ton style authentique. Garde la cohérence avec tes réponses précédentes.';
        var resp = await callClaude(debatSystemPrompt, msg, { history: debatHistory, maxTokens: 400, temperature: 0.85 });
        addToConversation(window._debatConv, 'assistant', resp);
        typing.remove();
        messages.innerHTML += '<div style="background:#8e44ad11;border:1px solid #8e44ad22;border-radius:2px 12px 12px 12px;padding:12px 14px;margin-bottom:10px;">'
            + '<div style="font-size:0.65rem;color:#8e44ad;font-weight:700;margin-bottom:4px;">' + p.emoji + ' ' + p.name.toUpperCase() + '</div>'
            + '<div style="font-size:0.82rem;color:#ccc;line-height:1.7;">' + resp + '</div></div>';
        messages.scrollTop = messages.scrollHeight;
    } catch(e) {
        typing.remove();
        messages.innerHTML += '<div style="color:#e74c3c;font-size:0.78rem;padding:8px;">Erreur : ' + e.message + '</div>';
    }
}

function initAuth() {
    // Vérifier si une session persistante existe
    const savedSession = localStorage.getItem('ms_session');
    if (savedSession) {
        const session = JSON.parse(savedSession);
        // Valider que le compte existe toujours
        const account = _safeGet('userAccount', {});
        if (account.email === session.email) {
            localStorage.setItem('isAuth', 'true');
            isAuth = true;
            // ✅ Restaurer session Boss si fondateur
            _activateBossSession(account.email);
            restoreUserProgress(account.email);
            currentLevel = null;
            showGrades();
            initFloatingBubble();
            return;
        }
    }

    if (!isAuth) {
        showLanding();
    } else {
        // Déjà connecté : restaurer la progression
        const _acc = JSON.parse(localStorage.getItem('userAccount') || '{}');
        if (_acc.email) restoreUserProgress(_acc.email);
        showGrades();
    }
    initFloatingBubble();
}

