function showStartupQuote() {
    // Une seule fois par jour — clé = date du jour
    const today = new Date().toISOString().split('T')[0];
    if (localStorage.getItem('ms_quote_date') === today) return;
    localStorage.setItem('ms_quote_date', today);

    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const todayKey = mm + '-' + dd;
    let pool = STARTUP_QUOTES.filter(q => q.specialDate === todayKey);
    if (!pool.length) pool = STARTUP_QUOTES.filter(q => q.birthDate === todayKey || q.deathDate === todayKey);
    if (!pool.length) {
        const allAuthors = [...new Set(STARTUP_QUOTES.map(q => q.author))];
        const dayOfYear = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
        pool = STARTUP_QUOTES.filter(q => q.author === allAuthors[dayOfYear % allAuthors.length]);
    }
    const q = pool[Math.floor(Math.random() * pool.length)];
    const philo = philosophersData.find(p => p.name && p.name.toUpperCase().includes(q.author.toUpperCase().split(' ')[0]));
    const auteur = !philo ? frenchAuthorsData.find(a => a.name && a.name.toUpperCase().includes(q.author.toUpperCase().split(' ')[0])) : null;
    const img = philo ? philo.image : (auteur ? auteur.image : null);
    const color = philo ? philo.color : (auteur ? auteur.color : '#8a2be2');
    const overlay = document.createElement('div');
    overlay.id = 'startup-quote-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(5,5,15,0.97);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:32px 24px;text-align:center;animation:fadeIn 0.5s ease;';
    overlay.innerHTML = `
        <div style="font-size:0.65rem;color:#555;letter-spacing:3px;font-weight:800;margin-bottom:28px;">✦ CITATION DU JOUR ✦</div>
        ${img ? `<div style="width:72px;height:72px;border-radius:50%;overflow:hidden;border:2px solid ${color}55;margin-bottom:20px;flex-shrink:0;"><img loading="lazy" src="${img}" style="width:100%;height:100%;object-fit:cover;object-position:top;;will-change:transform;transform:translateZ(0);" onerror="this.parentElement.style.display='none'"></div>` : '<div style="font-size:2.5rem;margin-bottom:20px;">💭</div>'}
        <div style="font-size:1.25rem;font-weight:900;color:#fff;line-height:1.5;margin-bottom:20px;max-width:320px;">"${q.text}"</div>
        <div style="font-size:0.82rem;color:${color};font-weight:800;letter-spacing:1px;margin-bottom:40px;">— ${q.author}</div>
        <div onclick="document.getElementById('startup-quote-overlay').remove()" style="background:linear-gradient(135deg,#8a2be2,#a855f7);color:#fff;font-weight:900;font-size:0.9rem;padding:14px 40px;border-radius:50px;cursor:pointer;box-shadow:0 8px 24px #8a2be244;">Commencer à réviser →</div>
    `;
    document.body.appendChild(overlay);
}

