// PHILOSOPHE MENTOR
// ═══════════════════════════════════════════════════════════════
function getMentorPhilo() {
    const account = _safeGet('userAccount', {});
    if (!account.mentor) return null;
    // 🔧 FIX : cherche avec trim() et insensible à la casse pour éviter les mismatches
    const mentor = account.mentor.trim().toUpperCase();
    const found = philosophersData.find(p => p.name && p.name.trim().toUpperCase() === mentor);
    return found || null;
}

function getMentorQuote() {
    const p = getMentorPhilo();
    if (!p) return null;
    const quotes = [p.quote, ...(p.armes ? p.armes.map(a => typeof a === 'string' ? a : (a.label||'')) : [])].filter(Boolean);
    const day = new Date().getDate();
    return quotes[day % quotes.length];
}

function showChangeMentor() {
    const account = _safeGet('userAccount', {});
    const modal = document.createElement('div');
    modal.id = 'mentor-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.85);display:flex;align-items:flex-end;animation:fadeIn 0.2s ease;';
    modal.innerHTML = `
        <div style="width:100%;background:#0d0018;border-radius:24px 24px 0 0;padding:24px 16px 40px;max-height:85vh;overflow-y:auto;">
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">
                <div>
                    <div style="font-size:1rem;font-weight:900;color:#fff;">🧠 Ton Philosophe Mentor</div>
                    <div style="font-size:0.72rem;color:#555;margin-top:2px;">Il guidera ton parcours MusicSchool</div>
                </div>
                <div onclick="document.getElementById('mentor-modal').remove()" style="width:32px;height:32px;border-radius:50%;background:#1a1a1a;display:flex;align-items:center;justify-content:center;cursor:pointer;color:#fff;font-size:0.9rem;">✕</div>
            </div>
            <div id="mentor-modal-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:8px;"></div>
        </div>
    `;
    document.body.appendChild(modal);
    const grid = document.getElementById('mentor-modal-grid');
    const top = ['Socrate','Platon','Aristote','Descartes','Kant','Nietzsche','Sartre','Camus','Spinoza','Hegel','Marx','Freud','Simone de Beauvoir','Pascal','Voltaire','Rousseau','Épicure','Heidegger','Bergson','Gandhi','Senghor','Paul Valéry','Schopenhauer'];
    top.forEach(name => {
        const p = philosophersData.find(x => x.name && x.name.toLowerCase().includes(name.toLowerCase()));
        if (!p) return;
        const isSelected = account.mentor === p.name;
        const btn = document.createElement('div');
        btn.style.cssText = `display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:14px;border:1.5px solid ${isSelected ? p.color : '#222'};background:${isSelected ? p.color+'22' : '#111'};cursor:pointer;transition:all 0.2s;`;
        btn.innerHTML = `
            <div style="width:36px;height:36px;border-radius:50%;overflow:hidden;flex-shrink:0;background:${p.color}33;">
                <img loading="lazy" src="${p.image||''}" style="width:100%;height:100%;object-fit:cover;object-position:top;;will-change:transform;transform:translateZ(0);" onerror="this.style.display='none';this.parentElement.innerHTML='<span style=\\'font-size:1rem;font-weight:900;color:${p.color};display:flex;align-items:center;justify-content:center;width:100%;height:100%\\'>${p.name[0]}</span>'">
            </div>
            <div>
                <div style="font-size:0.75rem;font-weight:800;color:#fff;">${p.name}</div>
                <div style="font-size:0.62rem;color:#555;">${(p.dates||'').split('–')[0].trim()}</div>
            </div>
            ${isSelected ? `<div style="margin-left:auto;color:${p.color};font-size:0.8rem;">✓</div>` : ''}
        `;
        btn.onclick = () => {
            account.mentor = p.name;
            localStorage.setItem('userAccount', JSON.stringify(account));
            document.getElementById('mentor-modal').remove();
            showToast('🧠 ' + p.name + ' est ton nouveau mentor !');
            currentLevel = null;
            showProfile();
        };
        grid.appendChild(btn);
    });
}


function buildMentorGrid() {
    const grid = document.getElementById('mentor-grid');
    if (!grid) return;
    grid.innerHTML = '';
    const top = ['Socrate','Platon','Aristote','Descartes','Kant','Nietzsche','Sartre','Camus','Spinoza','Hegel','Marx','Freud','Simone de Beauvoir','Pascal','Voltaire','Rousseau','Épicure','Heidegger','Bergson','Gandhi','Senghor'];
    top.forEach(name => {
        const p = philosophersData.find(x => x.name && x.name.toLowerCase().includes(name.toLowerCase()));
        if (!p) return;
        const btn = document.createElement('div');
        btn.onclick = () => {
            document.getElementById('auth-mentor').value = p.name;
            grid.querySelectorAll('.mentor-btn').forEach(b => { b.style.border = '1.5px solid #222'; b.style.background = '#111'; });
            btn.style.border = `1.5px solid ${p.color}`; btn.style.background = `${p.color}22`;
            // Auto-collapse après sélection avec confirmation visuelle
            setTimeout(() => {
                const block = document.getElementById('mentor-block');
                if (block) {
                    block.style.transition = 'all 0.3s ease';
                    block.style.overflow = 'hidden';
                    block.style.maxHeight = '0';
                    block.style.marginBottom = '0';
                    block.style.opacity = '0';
                    setTimeout(() => { block.style.display = 'none'; }, 300);
                }
                // Afficher confirmation
                const existing = document.getElementById('mentor-confirm');
                if (existing) existing.remove();
                const confirm = document.createElement('div');
                confirm.id = 'mentor-confirm';
                confirm.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 14px;background:' + p.color + '18;border:1.5px solid ' + p.color + '55;border-radius:12px;margin-bottom:14px;animation:fadeInUp 0.3s ease;';
                // Build confirm with DOM to avoid quote issues
                const imgEl = document.createElement('img');
                imgEl.src = p.image || '';
                imgEl.style.cssText = 'width:100%;height:100%;object-fit:cover;object-position:top;';
                imgEl.onerror = function() { this.style.display = 'none'; };
                const imgWrap = document.createElement('div');
                imgWrap.style.cssText = 'width:28px;height:28px;border-radius:50%;overflow:hidden;flex-shrink:0;background:' + p.color + '33;';
                imgWrap.appendChild(imgEl);
                const nameEl = document.createElement('div');
                nameEl.style.cssText = 'font-size:0.75rem;font-weight:900;color:#fff;';
                nameEl.textContent = p.name + ' ✓';
                const subEl = document.createElement('div');
                subEl.style.cssText = 'font-size:0.62rem;color:' + p.color + ';';
                subEl.textContent = 'Philosophe mentor sélectionné';
                const textWrap = document.createElement('div');
                textWrap.appendChild(nameEl); textWrap.appendChild(subEl);
                confirm.appendChild(imgWrap); confirm.appendChild(textWrap);
                const mentorBlock = document.getElementById('mentor-block');
                if (mentorBlock && mentorBlock.parentNode) {
                    mentorBlock.parentNode.insertBefore(confirm, mentorBlock);
                }
            }, 150);
        };
        btn.className = 'mentor-btn';
        btn.style.cssText = `display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:12px;border:1.5px solid #222;background:#111;cursor:pointer;transition:all 0.2s;`;
        btn.innerHTML = `<div style="width:32px;height:32px;border-radius:50%;overflow:hidden;flex-shrink:0;background:${p.color}33;"><img loading="lazy" src="${p.image||''}" style="width:100%;height:100%;object-fit:cover;object-position:top;;will-change:transform;transform:translateZ(0);" onerror="this.style.display='none';this.parentElement.innerHTML='<span style=\\'font-size:0.9rem;font-weight:900;color:${p.color}\\'>${p.name[0]}</span>'"></div><div><div style="font-size:0.72rem;font-weight:800;color:#fff;">${p.name}</div><div style="font-size:0.62rem;color:#555;">${(p.dates||'').split('–')[0].trim()}</div></div>`;
        grid.appendChild(btn);
    });
}
