function handleAuth(type) {
    const email = document.getElementById('auth-email').value.trim();
    const pass = document.getElementById('auth-pass').value;

    if (type === 'signup') {
        const user = document.getElementById('auth-user').value.trim();
        const role = document.getElementById('auth-role').value;
        const classe = document.getElementById('auth-classe').value;
        if (!user || !pass || !email) return showToast('⚠️ Remplis tous les champs !');
        if (!email.includes('@') || !email.includes('.')) return showToast('⚠️ Adresse email invalide !');
        if (pass.length < 6) return showToast('⚠️ Le mot de passe doit faire au moins 6 caractères !');
        if (!role) return showToast('⚠️ Choisis ton profil (Élève, Parent, Prof ou Autre) !');
        if (role === 'eleve' && !classe) return showToast('⚠️ Choisis ta classe !');
        const serie = (document.getElementById('auth-serie') || {}).value || 'A';

        // ❌ Bloquer si email déjà utilisé
        const existing = JSON.parse(localStorage.getItem('userAccount') || '{}');
        if (existing.email && existing.email.toLowerCase() === email.toLowerCase()) {
            showToast('⚠️ Un compte existe déjà avec cet email. Connecte-toi !');
            showAuthScreen('login');
            return;
        }

        localStorage.removeItem('_ms_p');
        sessionStorage.removeItem('_ms_ps');
        // 🔧 FIX : avant de vider la progression active, on la sauvegarde
        // d'abord pour le compte qui était précédemment connecté (s'il y en
        // avait un). Sans ça, créer un 2e compte sans se déconnecter avant
        // effaçait définitivement la progression du compte en cours, jamais
        // sauvegardée nulle part (cause probable de "données disparues").
        if (existing.email) saveUserProgress(existing.email);
        // ✅ Vider la progression de l'ancien compte pour partir à zéro
        ['xpData','ms_coins','completedLessons','likedLessons','ms_owned_items',
         'ms_active_theme','ms_active_title','ms_wrong_answers','ms_boosts',
         'ms_login_count','ms_streak','ms_last_day'].forEach(k => localStorage.removeItem(k));
        const mentor = (document.getElementById('auth-mentor') || {}).value || '';
        const pays = (document.getElementById('auth-pays') || {}).value || '';
        localStorage.setItem('userAccount', JSON.stringify({ user, email: email.toLowerCase(), pass, role, classe, serie, mentor, pays }));
        showToast('✅ Compte créé ! Connecte-toi maintenant.');
        showAuthScreen('login');

    } else {
        if (!email || !pass) return showToast('⚠️ Remplis ton email et ton mot de passe !');
        const saved = JSON.parse(localStorage.getItem('userAccount'));
        if (saved && saved.email.toLowerCase() === email.toLowerCase() && saved.pass === pass) {
            localStorage.setItem('isAuth', 'true');
            isAuth = true;
            // ✅ Activer session Boss si fondateur
            _activateBossSession(saved.email);
            // ✅ Restaurer la progression de cet utilisateur
            restoreUserProgress(saved.email);
            // ✅ Sauvegarder session persistante
            localStorage.setItem('ms_session', JSON.stringify({ email: saved.email }));
            const loginCount = parseInt(localStorage.getItem('ms_login_count') || '0');
            const _authCont2 = document.getElementById('auth-container');
            if (_authCont2) _authCont2.innerHTML = '';
            showGrades();
        } else {
            showToast('❌ Email ou mot de passe incorrect !');
        }
    }
}

