// ─── MODE NUIT ───────────────────────────────────────────────
function applyNightMode() {
    const nm = JSON.parse(localStorage.getItem('ms_night_mode') || '{"mode":"off","startHour":21,"endHour":6}');
    let active = false;
    if (nm.mode === 'on') {
        active = true;
    } else if (nm.mode === 'auto') {
        const h = new Date().getHours();
        const s = nm.startHour, e = nm.endHour;
        active = s < e ? (h >= s && h < e) : (h >= s || h < e);
    }
    let style = document.getElementById('ms-night-style');
    if (!style) {
        style = document.createElement('style');
        style.id = 'ms-night-style';
        document.head.appendChild(style);
    }
    style.textContent = active
        ? `#main-grid, header, #ms-search-bar { filter: brightness(0.75) saturate(0.7) !important; transition: filter 0.35s ease !important; }
           #full-player, #mini-player-container { filter: none !important; }`
        : `#main-grid, header, #ms-search-bar { filter: none !important; transition: filter 0.35s ease !important; }`;
}

function showNightModePanel() {
    const existing = document.getElementById('night-mode-modal');
    if (existing) { existing.remove(); return; }
    const nm = JSON.parse(localStorage.getItem('ms_night_mode') || '{"mode":"off","startHour":21,"endHour":6}');
    const modal = document.createElement('div');
    modal.id = 'night-mode-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.88);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;';
    modal.innerHTML = `
        <div style="background:#111;border:1.5px solid #6478ff55;border-radius:24px;padding:28px 22px;width:100%;max-width:340px;">
            <div style="text-align:center;margin-bottom:20px;">
                <div style="font-size:2rem;margin-bottom:6px;">🌙</div>
                <div style="font-size:1rem;font-weight:900;color:#fff;">Mode Nuit</div>
                <div style="font-size:0.72rem;color:#555;margin-top:4px;">Réduit la luminosité de l'interface</div>
            </div>
            <div style="display:flex;flex-direction:column;gap:10px;margin-bottom:20px;">
                <button onclick="setNightMode('off')" id="nm-off" style="display:flex;align-items:center;gap:12px;padding:14px 16px;border-radius:14px;border:1.5px solid ${nm.mode==='off'?'#6478ff':'#2a2a2a'};background:${nm.mode==='off'?'rgba(100,120,255,0.12)':'#0d0d0d'};cursor:pointer;text-align:left;width:100%;">
                    <span style="font-size:1.3rem;">☀️</span>
                    <div>
                        <div style="font-size:0.85rem;font-weight:800;color:#fff;">Désactivé</div>
                        <div style="font-size:0.68rem;color:#555;margin-top:2px;">Apparence normale</div>
                    </div>
                    ${nm.mode==='off'?'<span style="margin-left:auto;color:#6478ff;font-size:0.8rem;">✔</span>':''}
                </button>
                <button onclick="setNightMode('on')" id="nm-on" style="display:flex;align-items:center;gap:12px;padding:14px 16px;border-radius:14px;border:1.5px solid ${nm.mode==='on'?'#6478ff':'#2a2a2a'};background:${nm.mode==='on'?'rgba(100,120,255,0.12)':'#0d0d0d'};cursor:pointer;text-align:left;width:100%;">
                    <span style="font-size:1.3rem;">🌙</span>
                    <div>
                        <div style="font-size:0.85rem;font-weight:800;color:#fff;">Permanent</div>
                        <div style="font-size:0.68rem;color:#555;margin-top:2px;">Toujours activé</div>
                    </div>
                    ${nm.mode==='on'?'<span style="margin-left:auto;color:#6478ff;font-size:0.8rem;">✔</span>':''}
                </button>
                <button onclick="setNightMode('auto')" id="nm-auto" style="display:flex;align-items:center;gap:12px;padding:14px 16px;border-radius:14px;border:1.5px solid ${nm.mode==='auto'?'#6478ff':'#2a2a2a'};background:${nm.mode==='auto'?'rgba(100,120,255,0.12)':'#0d0d0d'};cursor:pointer;text-align:left;width:100%;">
                    <span style="font-size:1.3rem;">⏰</span>
                    <div>
                        <div style="font-size:0.85rem;font-weight:800;color:#fff;">Automatique</div>
                        <div style="font-size:0.68rem;color:#555;margin-top:2px;">Selon une plage horaire</div>
                    </div>
                    ${nm.mode==='auto'?'<span style="margin-left:auto;color:#6478ff;font-size:0.8rem;">✔</span>':''}
                </button>
            </div>
            <div id="nm-auto-panel" style="display:${nm.mode==='auto'?'block':'none'};background:#0a0a1a;border:1px solid #6478ff33;border-radius:14px;padding:16px;margin-bottom:16px;">
                <div style="font-size:0.68rem;color:#a78bfa;font-weight:800;letter-spacing:1px;margin-bottom:12px;">PLAGE HORAIRE</div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
                    <div>
                        <div style="font-size:0.65rem;color:#555;margin-bottom:6px;">Activation</div>
                        <input type="time" id="nm-start" value="${String(nm.startHour).padStart(2,'0')}:00" onchange="saveNightModeHours()"
                            style="width:100%;padding:10px;border-radius:10px;border:1px solid #333;background:#111;color:#fff;font-size:0.85rem;box-sizing:border-box;outline:none;">
                    </div>
                    <div>
                        <div style="font-size:0.65rem;color:#555;margin-bottom:6px;">Désactivation</div>
                        <input type="time" id="nm-end" value="${String(nm.endHour).padStart(2,'0')}:00" onchange="saveNightModeHours()"
                            style="width:100%;padding:10px;border-radius:10px;border:1px solid #333;background:#111;color:#fff;font-size:0.85rem;box-sizing:border-box;outline:none;">
                    </div>
                </div>
            </div>
            <button onclick="document.getElementById('night-mode-modal').remove()" style="width:100%;padding:12px;border-radius:14px;border:1px solid #333;background:#1a1a1a;color:#aaa;font-size:0.85rem;font-weight:700;cursor:pointer;">Fermer</button>
        </div>
    `;
    document.body.appendChild(modal);
    modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
}

function setNightMode(mode) {
    const nm = JSON.parse(localStorage.getItem('ms_night_mode') || '{"mode":"off","startHour":21,"endHour":6}');
    nm.mode = mode;
    localStorage.setItem('ms_night_mode', JSON.stringify(nm));
    applyNightMode();
    const panel = document.getElementById('nm-auto-panel');
    if (panel) panel.style.display = mode === 'auto' ? 'block' : 'none';
    ['off','on','auto'].forEach(function(m) {
        const btn = document.getElementById('nm-' + m);
        if (!btn) return;
        btn.style.borderColor = m === mode ? '#6478ff' : '#2a2a2a';
        btn.style.background = m === mode ? 'rgba(100,120,255,0.12)' : '#0d0d0d';
    });
    showToast(mode === 'off' ? '☀️ Mode nuit désactivé' : mode === 'on' ? '🌙 Mode nuit activé' : '⏰ Mode nuit automatique');
}

function saveNightModeHours() {
    const startInput = document.getElementById('nm-start');
    const endInput = document.getElementById('nm-end');
    if (!startInput || !endInput) return;
    const nm = JSON.parse(localStorage.getItem('ms_night_mode') || '{"mode":"off","startHour":21,"endHour":6}');
    nm.startHour = parseInt(startInput.value.split(':')[0]);
    nm.endHour = parseInt(endInput.value.split(':')[0]);
    localStorage.setItem('ms_night_mode', JSON.stringify(nm));
    applyNightMode();
}

function logout() {
    const account = _safeGet('userAccount', {});
    // Afficher modal confirmation
    const modal = document.createElement('div');
    modal.id = 'logout-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;';
    const isGoogleNoPin = account.isGoogle && !account.pass;
    modal.innerHTML = `
        <div style="background:#111;border:1.5px solid #333;border-radius:24px;padding:28px 24px;width:100%;max-width:340px;text-align:center;">
            <div style="font-size:2rem;margin-bottom:12px;">🔐</div>
            <div style="font-size:1rem;font-weight:900;color:#fff;margin-bottom:6px;">Confirmer la déconnexion</div>
            ${isGoogleNoPin 
                ? '<div style="font-size:0.75rem;color:#888;margin-bottom:20px;">Compte Google · Clique sur Déconnecter pour continuer</div>'
                : '<div style="font-size:0.75rem;color:#666;margin-bottom:20px;">Saisis ton ' + (account.isGoogle ? 'code PIN' : 'mot de passe') + ' pour te déconnecter</div>'
            }
            ${isGoogleNoPin ? '' : '<input id="logout-pass" type="password" placeholder="' + (account.isGoogle ? 'Code PIN' : 'Mot de passe') + '" style="width:100%;padding:12px 16px;border-radius:12px;border:1.5px solid #333;background:#0a0a0a;color:#fff;font-size:0.9rem;margin-bottom:8px;box-sizing:border-box;outline:none;">'}
            <div id="logout-err" style="font-size:0.72rem;color:#e74c3c;margin-bottom:14px;min-height:16px;"></div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
                <div onclick="document.getElementById('logout-modal').remove()" style="padding:12px;border-radius:12px;border:1.5px solid #333;color:#888;font-weight:700;font-size:0.82rem;cursor:pointer;text-align:center;">Annuler</div>
                <div onclick="confirmLogout('${account.pass}')" style="padding:12px;border-radius:12px;background:rgba(231,76,60,0.15);border:1.5px solid #e74c3c44;color:#e74c3c;font-weight:700;font-size:0.82rem;cursor:pointer;text-align:center;">Déconnecter</div>
            </div>
        </div>`;
    document.body.appendChild(modal);
    setTimeout(() => document.getElementById('logout-pass')?.focus(), 100);
}

function confirmLogout(correctPass) {
    const input = document.getElementById('logout-pass');
    const err = document.getElementById('logout-err');
    if (!input) return;
    // Si pas de mot de passe enregistré (vieux compte Google sans PIN) → déconnecter directement
    if (!correctPass || correctPass === 'undefined') {
        document.getElementById('logout-modal')?.remove();
        autoSaveProgress(); // ✅ Sauvegarder avant de partir
        localStorage.setItem('isAuth', 'false');
        localStorage.removeItem('ms_session');
        location.reload();
        return;
    }
    if (input.value !== correctPass) {
        err.textContent = '❌ Code incorrect';
        input.style.borderColor = '#e74c3c';
        return;
    }
    document.getElementById('logout-modal')?.remove();
    autoSaveProgress(); // ✅ Sauvegarder avant de partir
    localStorage.setItem('isAuth', 'false');
    localStorage.removeItem('ms_session');
    location.reload();
}

// ─── Sauvegarde progression par utilisateur ───
function saveUserProgress(email) {
    if (!email) return;
    const key = 'ms_progress_' + email.replace(/[^a-zA-Z0-9]/g, '_');
    const progress = {
        xpData: localStorage.getItem('xpData'),
        ms_coins: localStorage.getItem('ms_coins'),
        completedLessons: localStorage.getItem('completedLessons'),
        likedLessons: localStorage.getItem('likedLessons'),
        ms_owned_items: localStorage.getItem('ms_owned_items'),
        ms_active_theme: localStorage.getItem('ms_active_theme'),
        ms_active_title: localStorage.getItem('ms_active_title'),
        ms_wrong_answers: localStorage.getItem('ms_wrong_answers'),
        ms_boosts: localStorage.getItem('ms_boosts'),
        ms_listen_history: localStorage.getItem('ms_listen_history'),
        savedAt: Date.now()
    };
    localStorage.setItem(key, JSON.stringify(progress));
}

function restoreUserProgress(email) {
    if (!email) return;
    const key = 'ms_progress_' + email.replace(/[^a-zA-Z0-9]/g, '_');
    const raw = localStorage.getItem(key);
    if (!raw) return;
    const progress = JSON.parse(raw);
    if (progress.xpData) localStorage.setItem('xpData', progress.xpData);
    if (progress.ms_coins) localStorage.setItem('ms_coins', progress.ms_coins);
    if (progress.completedLessons) localStorage.setItem('completedLessons', progress.completedLessons);
    if (progress.likedLessons) localStorage.setItem('likedLessons', progress.likedLessons);
    if (progress.ms_owned_items) localStorage.setItem('ms_owned_items', progress.ms_owned_items);
    if (progress.ms_active_theme) localStorage.setItem('ms_active_theme', progress.ms_active_theme);
    if (progress.ms_active_title) localStorage.setItem('ms_active_title', progress.ms_active_title);
    if (progress.ms_wrong_answers) localStorage.setItem('ms_wrong_answers', progress.ms_wrong_answers);
    if (progress.ms_boosts) localStorage.setItem('ms_boosts', progress.ms_boosts);
    if (progress.ms_listen_history) localStorage.setItem('ms_listen_history', progress.ms_listen_history);
}

function autoSaveProgress() {
    const account = _safeGet('userAccount', {});
    if (account.email) saveUserProgress(account.email);
}

// Auto-save toutes les 30 secondes
setInterval(autoSaveProgress, 30000); // Sauvegarde toutes les 30 secondes

function changeClasse(classe) {
    const account = _safeGet('userAccount', {});
    account.classe = classe;
    localStorage.setItem('userAccount', JSON.stringify(account));
    selectedGrade = (classe === 'terminale' || classe === '1ere') ? classe : 'terminale';
    showToast('✅ Classe changée : ' + classe.charAt(0).toUpperCase() + classe.slice(1));
    showProfile();
}

// ─── CHANGEMENT DE CLASSE SÉCURISÉ ───────────────────────────────────────────────
// Anti-triche : max 2 changements par an, cooldown 30 jours entre deux changements
var _CLASSE_CHANGE_MAX_PER_YEAR = 2;
var _CLASSE_CHANGE_COOLDOWN_DAYS = 30;

function _getClasseChangeData() {
    try { return JSON.parse(localStorage.getItem('ms_classe_changes') || '{"count":0,"year":0,"lastChange":0}'); }
    catch(e) { return { count: 0, year: 0, lastChange: 0 }; }
}

function showChangeClasseModal() {
    const account = _safeGet('userAccount', {});
    if (!account || account.role !== 'eleve') { showToast('⚠️ Option réservée aux élèves'); return; }
    const now = Date.now();
    const year = new Date().getFullYear();
    const data = _getClasseChangeData();
    if (data.year < year) { data.count = 0; data.year = year; }
    const daysLeft = data.lastChange ? Math.ceil((_CLASSE_CHANGE_COOLDOWN_DAYS * 86400000 - (now - data.lastChange)) / 86400000) : 0;
    const canChange = data.count < _CLASSE_CHANGE_MAX_PER_YEAR && daysLeft <= 0;
    const classeActuelle = (account.classe || 'terminale').toLowerCase();
    const labels = { '3eme': '3ème', '2nde': '2nde', '1ere': '1ère', 'terminale': 'Terminale' };
    const toutes = ['3eme','2nde','1ere','terminale'];
    const overlay = document.createElement('div');
    overlay.id = 'change-classe-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:#000d;z-index:10000;display:flex;align-items:flex-end;justify-content:center;';
    const btns = toutes.map(c => `<button onclick="confirmChangeClasse('${c}')" ${!canChange || c === classeActuelle ? 'disabled' : ''} style="flex:1;padding:12px 6px;border-radius:12px;border:1.5px solid ${c === classeActuelle ? '#8a2be2' : canChange ? '#333' : '#222'};background:${c === classeActuelle ? '#8a2be222' : '#111'};color:${c === classeActuelle ? '#a855f7' : canChange ? '#ccc' : '#444'};font-size:0.75rem;font-weight:800;cursor:${!canChange || c === classeActuelle ? 'not-allowed' : 'pointer'};">${labels[c]}${c === classeActuelle ? ' ✓' : ''}</button>`).join('');
    const infoMsg = !canChange ? (daysLeft > 0 ? `⏳ Prochain changement dans <b>${daysLeft} jours</b>` : `🔒 Limite atteinte (${_CLASSE_CHANGE_MAX_PER_YEAR}/an) — contacte le support`) : `<span style="color:#555;">${_CLASSE_CHANGE_MAX_PER_YEAR - data.count} changement(s) restant(s) cette année</span>`;
    overlay.innerHTML = `<div style="width:92%;max-width:400px;background:#0d0d0d;border:1.5px solid #8a2be244;border-radius:22px 22px 0 0;padding:20px 18px 32px;"><div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#8a2be2;margin-bottom:6px;">🎓 CHANGER DE CLASSE</div><div style="font-size:0.82rem;color:#888;margin-bottom:16px;">${infoMsg}</div><div style="display:flex;gap:8px;margin-bottom:16px;">${btns}</div><button onclick="document.getElementById('change-classe-overlay').remove()" style="width:100%;padding:12px;background:#1a1a1a;border:1px solid #333;border-radius:12px;color:#666;font-size:0.8rem;cursor:pointer;">Annuler</button></div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
}

function confirmChangeClasse(classe) {
    const data = _getClasseChangeData();
    const now = Date.now();
    const year = new Date().getFullYear();
    if (data.year < year) { data.count = 0; data.year = year; }
    const daysLeft = data.lastChange ? Math.ceil((_CLASSE_CHANGE_COOLDOWN_DAYS * 86400000 - (now - data.lastChange)) / 86400000) : 0;
    if (data.count >= _CLASSE_CHANGE_MAX_PER_YEAR || daysLeft > 0) { showToast('🔒 Changement non autorisé'); return; }
    const account = _safeGet('userAccount', {});
    account.classe = classe;
    localStorage.setItem('userAccount', JSON.stringify(account));
    selectedGrade = (classe === 'terminale' || classe === '1ere') ? classe : 'terminale';
    data.count++; data.year = year; data.lastChange = now;
    localStorage.setItem('ms_classe_changes', JSON.stringify(data));
    const el = document.getElementById('change-classe-overlay');
    if (el) el.remove();
    const labels = { '3eme': '3ème', '2nde': '2nde', '1ere': '1ère', 'terminale': 'Terminale' };
    showToast('✅ Classe mise à jour : ' + (labels[classe] || classe));
    showProfile();
}

