            { q: "Que se passe-t-il le 13 août 1961 ?", choices: ["Crise des missiles de Cuba", "Création du Pacte de Varsovie", "Construction du Mur de Berlin", "Dissolution de l'URSS"], answer: 2 },
            { q: "Le Pacte de Varsovie (1955) est :", choices: ["L'alliance militaire occidentale", "La réponse soviétique à l'OTAN", "Le traité de réunification allemande", "L'accord de paix entre Kennedy et Krouchtchev"], answer: 1 },
            { q: "Quelle crise de 1962 faillit déclencher une guerre nucléaire ?", choices: ["Le blocus de Berlin", "La crise des missiles de Cuba", "La construction du Mur", "La guerre de Corée"], answer: 1 },
            { q: "Quand tombe le Mur de Berlin ?", choices: ["25 décembre 1991", "9 novembre 1989", "13 août 1961", "1er mai 1947"], answer: 1 },
            { q: "Que se passe-t-il le 25 décembre 1991 ?", choices: ["Chute du Mur de Berlin", "Crise de Cuba", "Dissolution officielle de l'URSS", "Création de l'OTAN"], answer: 2 },
            { q: "Combien d'Allemagnes naissent en 1949 ?", choices: ["1", "2", "3", "4"], answer: 1 }
