let mainGrid, sectionTitle, backBtn;
// Sauvegarde des positions de scroll par niveau
// ─── Système scroll persistant (localStorage) ───────────────
// Menu principal (grades) : reset à 0 à chaque clic matière
// Tous les dossiers : position sauvegardée et restaurée

const _SCROLL_LS_KEY = 'ms_scroll_positions';

function _getScrollPositions() {
    try { return JSON.parse(localStorage.getItem(_SCROLL_LS_KEY)) || {}; }
    catch(e) { return {}; }
}
function _setScrollPositions(obj) {
    try { localStorage.setItem(_SCROLL_LS_KEY, JSON.stringify(obj)); } catch(e) {}
}

function _saveScroll(key) {
    if (!key) return;
    var pos = window.scrollY || document.documentElement.scrollTop || 0;
    var all = _getScrollPositions();
    all[key] = pos;
    _setScrollPositions(all);
}

// ── Sauvegarde scroll en temps réel (debounce 150ms) ─────────────────────
(function() {
    var _scrollDebounce = null;
    window.addEventListener('scroll', function() {
        if (_scrollDebounce) clearTimeout(_scrollDebounce);
        _scrollDebounce = setTimeout(function() {
            _scrollDebounce = null;
            // Ne pas sauvegarder sur les pages menu principal
            if (!currentLevel || currentLevel === 'grades' || currentLevel === 'subjects') return;
            var key = _scrollKey(currentLevel, currentSubject || currentCategory || '');
            if (!key) return;
            var pos = window.scrollY || document.documentElement.scrollTop || 0;
            var all = _getScrollPositions();
            all[key] = pos;
            _setScrollPositions(all);
        }, 150);
    }, { passive: true });
})();

function _restoreScroll(key, delay) {
    var pos = (_getScrollPositions()[key]) || 0;
    setTimeout(function() {
        window.scrollTo({ top: pos, behavior: 'instant' });
    }, delay || 60);
}

function _scrollKey(level, sub) {
    return (level || '') + '__' + (sub || '');
}

function _clearScrollKey(key) {
    var all = _getScrollPositions();
    delete all[key];
    _setScrollPositions(all);
}

// ─── Historique de navigation ─────────────────────────────────
var _navHistory = [];
function _pushNav(level) {
    if (_navHistory[_navHistory.length - 1] !== level) {
        _navHistory.push(level);
        if (_navHistory.length > 20) _navHistory.shift();
    }
}
function _popNav() {
    _navHistory.pop();
    return _navHistory[_navHistory.length - 1] || 'grades';
}

// ─── Restauration scroll après render ────────────────────────
function _restoreScrollAfterRender(key) {
    if (window._scrollRestoreTimer) { clearTimeout(window._scrollRestoreTimer); window._scrollRestoreTimer = null; }
    window.scrollTo({ top: 0, behavior: 'instant' });
    var pos = (_getScrollPositions()[key]) || 0;
    if (pos < 5) return;
    window._scrollRestoreTimer = setTimeout(function() {
        window._scrollRestoreTimer = null;
        window.scrollTo({ top: pos, behavior: 'instant' });
    }, 80);
}

const audio = new Audio();
audio.crossOrigin = 'anonymous';
// ─── Fix son en arrière-plan Android/iOS ─────────────────────
function _resumeAudioAfterHide() {
    try {
        // 1) Réveiller l'AudioContext s'il est suspendu (cause du son silencieux)
        if (_audioCtxMain && _audioCtxMain.state === 'suspended') {
            _audioCtxMain.resume().catch(function(){});
        }
        // 2) Si l'audio jouait et s'est mis en pause à cause de l'interruption système
        if (window._audioWasPlayingBeforeHide && audio) {
            if (audio.paused) {
                // Audio vraiment pausé — on relance
                audio.play().catch(function() {});
            } else {
                // Audio "joue" mais silencieux car AudioContext suspendu
                // Forcer une micro-pause/reprise pour débloquer la chaîne audio
                if (_audioCtxMain && _audioCtxMain.state === 'suspended') {
                    audio.pause();
                    _audioCtxMain.resume().then(function() {
                        audio.play().catch(function(){});
                    }).catch(function(){
                        audio.play().catch(function(){});
                    });
                }
            }
        }
    } catch(e) {}
}

document.addEventListener('visibilitychange', function() {
    if (document.hidden) {
        // Sauvegarder l'état avant de partir en arrière-plan
        window._audioWasPlayingBeforeHide = audio && !audio.paused;
        // Sauvegarder la position courante pour détecter si le timer a avancé sans son
        window._audioTimeBeforeHide = audio ? audio.currentTime : 0;
    } else {
        // Retour au premier plan — réveiller l'audio
        _resumeAudioAfterHide();
    }
});

window.addEventListener('focus', function() { _resumeAudioAfterHide(); });
window.addEventListener('pageshow', function() { _resumeAudioAfterHide(); });


// ─── WEB AUDIO API GAIN BOOSTER ──────────────────────────────
// Booste le volume au-delà de la limite HTML5 (jusqu'à 3x)
let _audioCtxMain = null;
let _gainNode = null;
let _sourceConnected = false;

function _initAudioBoost() {
    if (_audioCtxMain) return;
    try {
        _audioCtxMain = new (window.AudioContext || window.webkitAudioContext)();
        const source = _audioCtxMain.createMediaElementSource(audio);
        _gainNode = _audioCtxMain.createGain();
        source.connect(_gainNode);
        _gainNode.connect(_audioCtxMain.destination);
        _sourceConnected = true;
        // Appliquer le gain sauvegardé
        const saved = parseFloat(localStorage.getItem('ms_audio_gain') || '1.5');
        _gainNode.gain.value = saved;
        // ── Fix son coupé en arrière-plan ──────────────────────────
        // Le son passe par ce AudioContext (pour le boost de volume).
        // Android/Chrome suspend automatiquement le contexte quand
        // l'app part en arrière-plan : l'<audio> continue de jouer
        // (paused === false) mais plus aucun son ne sort, car la chaîne
        // audio est coupée en amont. On réagit dès que ça arrive au
        // lieu d'attendre le retour au premier plan.
        _audioCtxMain.onstatechange = function() {
            if (_audioCtxMain.state === 'suspended' && audio && !audio.paused) {
                _audioCtxMain.resume().catch(function(){});
            }
        };
    } catch(e) {
        console.warn('AudioContext boost non disponible:', e);
    }
}

// ── Watchdog : filet de sécurité indépendant des événements ────────
// Certains appareils/webviews ne déclenchent pas 'visibilitychange',
// 'focus' ou 'statechange' de façon fiable. On vérifie donc toutes les
// 1.5s si l'audio est censé jouer mais que le contexte est suspendu,
// et on le relance. Coût quasi nul (juste une lecture d'état).
setInterval(function() {
    try {
        if (audio && !audio.paused && _audioCtxMain && _audioCtxMain.state === 'suspended') {
            _audioCtxMain.resume().catch(function(){});
        }
    } catch(e) {}
}, 1500);

function setAudioGain(val) {
    // Initialiser au premier appel (nécessite un geste utilisateur)
    if (!_audioCtxMain) _initAudioBoost();
    const v = Math.max(0.1, Math.min(3.0, parseFloat(val)));
    if (_gainNode) _gainNode.gain.value = v;
    localStorage.setItem('ms_audio_gain', v.toString());
    // Mettre à jour l'affichage du slider si visible
    const sl = document.getElementById('ms-gain-slider');
    if (sl) sl.value = v;
    const lb = document.getElementById('ms-gain-label');
    if (lb) lb.textContent = Math.round(v * 100) + '%';
}

// Initialiser au premier play (geste utilisateur requis)
audio.addEventListener('play', function() {
    if (!_audioCtxMain) _initAudioBoost();
    if (_audioCtxMain && _audioCtxMain.state === 'suspended') {
        _audioCtxMain.resume();
    }
}, { once: false });

