function getCoins() {
    return parseInt(localStorage.getItem('ms_coins') || '0');
}
function saveCoins(amount) {
    localStorage.setItem('ms_coins', Math.max(0, amount).toString());
}
function awardCoins(amount, reason) { if (amount > 0) playSound('coin');
    const current = getCoins();
    saveCoins(current + amount);
    showCoinToast(amount, reason);
    updateCoinDisplay();
    if (typeof _sessionTrackCoins === 'function') _sessionTrackCoins(amount);
}
function spendCoins(amount) {
    const current = getCoins();
    if (current < amount) return false;
    saveCoins(current - amount);
    updateCoinDisplay();
    return true;
}
function showCoinToast(amount, reason) {
    const existing = document.getElementById('coin-toast');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.id = 'coin-toast';
    toast.style.cssText = `
        position:fixed; top:95px; left:50%; transform:translateX(-50%) translateY(-10px);
        background:linear-gradient(135deg,#1a1a0a,#2a2a10);
        border:1px solid #f1c40f88; color:#f1c40f;
        font-weight:bold; font-size:0.85rem;
        padding:9px 20px; border-radius:30px;
        z-index:9999; pointer-events:none;
        box-shadow:0 4px 20px rgba(241,196,15,0.2);
        transition: opacity 0.4s, transform 0.4s;
        white-space:nowrap;
    `;
    toast.innerHTML = `🪙 +${amount} — ${reason}`;
    document.body.appendChild(toast);
    requestAnimationFrame(() => {
        toast.style.transform = 'translateX(-50%) translateY(0)';
        toast.style.opacity = '1';
    });
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(-50%) translateY(-10px)';
        setTimeout(() => toast.remove(), 200);
    }, 2200);
}
function updateCoinDisplay() {
    const el = document.getElementById('coin-display');
    if (el) el.innerText = `🪙 ${getCoins()}`;
}

