function confirmBuy(itemId) {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    if (!item) return;
    const owned = getOwnedItems();
    // Déjà acheté → activer direct sans confirmation
    if (owned.includes(itemId)) { activateItem(itemId); showShop(); return; }

    // Modal de confirmation
    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;`;
    overlay.innerHTML = `
        <div style="background:#0d0820;border:1.5px solid ${item.rare ? '#f1c40f' : '#333'};border-radius:24px;padding:28px 24px;max-width:320px;width:100%;text-align:center;">
            <div style="font-size:2.5rem;margin-bottom:12px;">${item.icon}</div>
            <div style="font-size:1rem;font-weight:900;color:#fff;margin-bottom:6px;">${item.label}</div>
            <div style="font-size:0.75rem;color:#666;margin-bottom:20px;">${item.desc}</div>
            <div style="background:rgba(241,196,15,0.1);border:1px solid rgba(241,196,15,0.3);border-radius:12px;padding:12px;margin-bottom:24px;">
                <div style="font-size:1.2rem;font-weight:900;color:#f1c40f;">🪙 ${item.price} pièces</div>
                <div style="font-size:0.68rem;color:#555;margin-top:4px;">Solde après : ${getCoins() - item.price} 🪙</div>
            </div>
            ${getCoins() < item.price ? `<div style="font-size:0.8rem;color:#e74c3c;font-weight:700;margin-bottom:16px;">❌ Pas assez de pièces</div>` : ''}
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
                <div id="cancel-buy" style="padding:12px;border-radius:12px;background:rgba(255,255,255,0.06);border:1px solid #333;color:#888;font-weight:800;font-size:0.82rem;cursor:pointer;">Annuler</div>
                <div id="confirm-buy" style="padding:12px;border-radius:12px;background:${getCoins() < item.price ? '#333' : 'linear-gradient(135deg,#8a2be2,#6a0dad)'};color:${getCoins() < item.price ? '#555' : '#fff'};font-weight:900;font-size:0.82rem;cursor:${getCoins() < item.price ? 'default' : 'pointer'};">Acheter</div>
            </div>
        </div>`;
    document.body.appendChild(overlay);
    overlay.querySelector('#cancel-buy').onclick = () => overlay.remove();
    overlay.querySelector('#confirm-buy').onclick = () => {
        if (getCoins() < item.price) return;
        overlay.remove();
        buyItem(itemId);
    };
}

function activateItem(itemId) {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    if (!item) return;
    if (item.type === 'theme') { localStorage.setItem('ms_active_theme', item.color); applyTheme(item.color); }
    else if (item.type === 'title') { localStorage.setItem('ms_active_title', item.titleText); }
    else if (item.type === 'frame') { localStorage.setItem('ms_active_frame', item.frameColor); }
    showToast(`✅ ${item.label} activé !`);
}

function buyItem(itemId) {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    if (!item) return;
    const owned = getOwnedItems();
    if (owned.includes(itemId)) { activateItem(itemId); showShop(); return; }
    if (!spendCoins(item.price)) { showToast('🪙 Pas assez de pièces !'); return; }
    owned.push(itemId);
    localStorage.setItem('ms_owned_items', JSON.stringify(owned));

    if (item.type === 'boost' && item.gameBoost) {
        const b = getBoosts();
        if (item.gameBoost === 'pack') {
            b.hint = (b.hint || 0) + 3; b.skip = (b.skip || 0) + 3; b.time = (b.time || 0) + 3;
            showToast('🎒 Pack activé : 3x Indice, 3x Passe, 3x +10s !');
        } else {
            b[item.gameBoost] = (b[item.gameBoost] || 0) + 1;
            showToast('✅ ' + item.label + ' ajouté !');
        }
        setBoosts(b);
        // Retirer des owned pour permettre de racheter
        const oi = owned.indexOf(itemId); if (oi > -1) owned.splice(oi, 1);
        localStorage.setItem('ms_owned_items', JSON.stringify(owned));
        showShop(); return;
    } else if (item.type === 'boost') {
        const expiry = Date.now() + 24 * 60 * 60 * 1000;
        localStorage.setItem('ms_boost_' + item.boostType, expiry.toString());
        showToast('⚡ ' + item.label + ' actif pendant 24h !');
    } else {
        activateItem(itemId);
        showToast(`🎉 ${item.label} débloqué !`);
    }
    showShop();
}

function applyTheme(color) {
    document.documentElement.style.setProperty('--neon', color);
    document.documentElement.style.setProperty('--neon-light', color + 'cc');
    document.documentElement.style.setProperty('--neon-glow', color + '55');
}

function showWheel() {
    currentLevel = 'wheel';
    updateHeaderBtns();
    sectionTitle.innerText = 'ROUE DU DESTIN';

    const SPIN_COST    = 10;
    const MAX_DAILY    = 3;

    // ─── Segments : weight = probabilité réelle → taille visuelle proportionnelle ───
    const segments = [
        { label: 'RIEN',     emoji: '❌', bg: '#111',    text: '#444',    coins: 0,   type: 'nothing', weight: 28   },
        { label: '+5',       emoji: '⚡', bg: '#0d1b3e', text: '#5b9bd5', coins: 5,   type: 'coins',   weight: 24   },
        { label: 'RIEN',     emoji: '❌', bg: '#1a1a1a', text: '#555',    coins: 0,   type: 'nothing', weight: 14   },
        { label: '+10',      emoji: '💫', bg: '#0d2e1e', text: '#2ecc71', coins: 10,  type: 'coins',   weight: 13   },
        { label: '+20',      emoji: '🔥', bg: '#2e1a00', text: '#e67e22', coins: 20,  type: 'coins',   weight: 9    },
        { label: '+35',      emoji: '🎯', bg: '#1e0a2e', text: '#a855f7', coins: 35,  type: 'coins',   weight: 6    },
        { label: '+50',      emoji: '💎', bg: '#0a1e3e', text: '#38bdf8', coins: 50,  type: 'coins',   weight: 3.5, rare: true },
        { label: '+100',     emoji: '👑', bg: '#2e2000', text: '#f1c40f', coins: 100, type: 'coins',   weight: 2,   rare: true },
        { label: 'JACKPOT',  emoji: '🎰', bg: '#2a0040', text: '#ff55ff', coins: 250, type: 'coins',   weight: 0.5, jackpot: true },
    ];

    // 🔀 Mélanger aléatoirement l'ordre à chaque ouverture → anti-triche
    for (let i = segments.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [segments[i], segments[j]] = [segments[j], segments[i]];
    }

    const totalWeight = segments.reduce((s, sg) => s + sg.weight, 0);

    // Pré-calculer les angles cumulatifs de chaque segment
    let cumAngle = 0;
    const segAngles = segments.map(sg => {
        const arc = (sg.weight / totalWeight) * Math.PI * 2;
        const start = cumAngle;
        cumAngle += arc;
        return { start, arc, mid: start + arc / 2 };
    });

    // ─── Spins journaliers ───
    const today    = new Date().toDateString();
    let spinData;
    try { spinData = JSON.parse(localStorage.getItem('wheelSpinData') || '{}'); } catch(e) { spinData = {}; }
    if (spinData.date !== today) { spinData.date = today; spinData.count = 0; spinData.history = []; }
    const spinsLeft = MAX_DAILY - (spinData.count || 0);

    // ─── Historique des 5 derniers gains ───
    const history = (spinData.history || []).slice(-5);
    const histHtml = history.length === 0 ? '' : `
        <div style="margin-bottom:8px; text-align:center;">
            <div style="font-size:0.55rem; color:#333; letter-spacing:2px; font-weight:700; margin-bottom:5px;">DERNIERS RÉSULTATS</div>
            <div style="display:flex; justify-content:center; gap:6px; flex-wrap:wrap;">
                ${history.map(h => `<span style="background:#111; border:1px solid #222; border-radius:20px; padding:3px 10px; font-size:0.7rem; font-weight:700; color:${h === 0 ? '#444' : '#f1c40f'};">${h === 0 ? '—' : '+' + h + ' 🪙'}</span>`).join('')}
            </div>
        </div>`;

    // ─── Légende probabilités ───
    const legendHtml = segments.map(sg => {
        const pct = ((sg.weight / totalWeight) * 100).toFixed(1);
        return `<div style="display:flex; align-items:center; gap:6px; margin-bottom:3px;">
            <div style="width:10px; height:10px; border-radius:2px; background:${sg.bg}; border:1px solid ${sg.text}; flex-shrink:0;"></div>
            <span style="font-size:0.7rem; color:${sg.type === 'nothing' ? '#444' : sg.text}; flex:1;">${sg.emoji} ${sg.label === 'JACKPOT' ? 'JACKPOT +250' : sg.label === 'RIEN' ? 'Rien' : sg.label + ' 🪙'}</span>
            <span style="font-size:0.65rem; color:#444; font-weight:700;">${pct}%</span>
        </div>`;
    }).join('');

    const size = Math.min(window.innerWidth - 16, 380);
    const cx = size / 2, cy = size / 2, r = size / 2 - 8;

    // Injecter les styles CSS de la roue
    if (!document.getElementById('wheel-styles')) {
        const s = document.createElement('style');
        s.id = 'wheel-styles';
        s.textContent = `
            @keyframes confettiFall {
                0%   { transform:translateY(0) rotate(0deg); opacity:1; }
                100% { transform:translateY(105vh) rotate(720deg); opacity:0; }
            }
            @keyframes wheelResultPop {
                0%   { transform:scale(0.5); opacity:0; }
                60%  { transform:scale(1.08); }
                100% { transform:scale(1); opacity:1; }
            }
            @keyframes glowPulse {
                0%,100% { box-shadow:0 0 40px rgba(138,43,226,0.5); }
                50%      { box-shadow:0 0 80px rgba(138,43,226,0.9), 0 0 120px rgba(138,43,226,0.3); }
            }
            @keyframes amPlayPulse {
                0%,100% { box-shadow:0 0 0 3px rgba(255,255,255,0.15), 0 0 16px rgba(255,255,255,0.2); }
                50%      { box-shadow:0 0 0 6px rgba(255,255,255,0.08), 0 0 28px rgba(255,255,255,0.35); }
            }
        `;
        document.head.appendChild(s);
    }

    mainGrid.innerHTML = `
        <div style="grid-column:1/-1; text-align:center; padding-bottom:20px; user-select:none;">

            <!-- Solde + Spins — barre compacte -->
            <div style="display:inline-flex; align-items:center; gap:14px; background:#111; border:1px solid #222; border-radius:30px; padding:7px 18px; margin-bottom:12px;">
                <span style="font-size:0.9rem; font-weight:900; color:#f1c40f;" id="wheel-coins">${getCoins()} 🪙</span>
                <div style="width:1px; height:14px; background:#333;"></div>
                <span style="font-size:0.9rem; font-weight:900; color:${spinsLeft > 0 ? getActiveTheme() : '#555'};" id="wheel-spins-left">${spinsLeft}/${MAX_DAILY} 🎰</span>
            </div>

            ${histHtml}

            <!-- Roue -->
            <div style="position:relative; display:inline-block; margin-bottom:6px;">
                <div style="
                    position:absolute; top:-20px; left:50%; transform:translateX(-50%);
                    width:0; height:0;
                    border-left:11px solid transparent;
                    border-right:11px solid transparent;
                    border-top:24px solid #f1c40f;
                    z-index:10;
                    filter:drop-shadow(0 3px 8px rgba(0,0,0,0.9));
                "></div>
                <canvas id="wheel-canvas" width="${size}" height="${size}" style="
                    border-radius:50%; display:block;
                    animation:glowPulse 3s ease-in-out infinite;
                    will-change:transform,box-shadow;
                    transform:translateZ(0);
                "></canvas>
            </div>

            <!-- Zone résultat -->
            <div id="wheel-result" style="min-height:40px; margin-bottom:6px; display:flex; align-items:center; justify-content:center;"></div>

            <!-- Bouton spin -->
            <div id="wheel-launch-btn" onclick="doSpin()" style="
                display:inline-flex; align-items:center; justify-content:center; gap:10px;
                background:linear-gradient(135deg,var(--neon),var(--neon-light));
                color:#fff; padding:13px 36px; border-radius:16px;
                font-size:0.95rem; font-weight:900; cursor:pointer;
                box-shadow:0 0 30px var(--neon-glow);
                transition:transform 0.15s, opacity 0.2s;
                letter-spacing:0.5px;
            " onmouseenter="this.style.transform='scale(1.04)'" onmouseleave="this.style.transform='scale(1)'">
                🎰 LANCER — ${SPIN_COST} 🪙
            </div>

            <div style="font-size:0.62rem; color:#333; margin-top:6px; letter-spacing:0.5px;">
                Taille des segments = probabilité réelle · Max ${MAX_DAILY} spins / jour
            </div>

            <!-- Légende probabilités -->
            <div style="
                margin-top:14px; background:#0d0d0d; border:1px solid #1e1e1e;
                border-radius:16px; padding:12px 16px; text-align:left;
                max-width:280px; margin-left:auto; margin-right:auto;
            ">
                <div style="font-size:0.58rem; color:#444; letter-spacing:2px; font-weight:700; margin-bottom:8px; text-align:center;">PROBABILITÉS</div>
                ${legendHtml}
            </div>

        </div>`;

    const canvas = document.getElementById('wheel-canvas');
    const ctx    = canvas.getContext('2d');
    window._wheelAngle    = 0; // 🔧 FIX : reset car segments remélangés à chaque ouverture
    window._wheelSpinning = false;
    if (window._wheelAnimFrame) { cancelAnimationFrame(window._wheelAnimFrame); window._wheelAnimFrame = null; }

    // ─── Dessin de la roue ───
    function drawWheel(angle) {
        ctx.clearRect(0, 0, size, size);

        segments.forEach((seg, i) => {
            const sa     = segAngles[i];
            const startA = angle + sa.start - Math.PI / 2;
            const endA   = startA + sa.arc;

            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.arc(cx, cy, r, startA, endA);
            ctx.closePath();
            ctx.fillStyle = seg.bg;
            ctx.fill();

            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // Halo sur les segments rares
            if (seg.rare || seg.jackpot) {
                ctx.beginPath();
                ctx.moveTo(cx, cy);
                ctx.arc(cx, cy, r, startA, endA);
                ctx.closePath();
                ctx.strokeStyle = seg.jackpot ? 'rgba(255,85,255,0.7)' : seg.coins >= 100 ? 'rgba(241,196,15,0.55)' : 'rgba(56,189,248,0.45)';
                ctx.lineWidth = 3;
                ctx.stroke();
            }

            // Texte — taille adaptée à la taille du segment
            const arcDeg = sa.arc * 180 / Math.PI;
            if (arcDeg < 5) return;

            const midA = startA + sa.arc / 2;
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(midA);
            ctx.textAlign = 'center';

            // Positionner le texte à 65% du rayon pour bien le centrer dans le segment
            const textDist = r * 0.62;

            if (arcDeg >= 22) {
                // Grand segment : emoji + label sur 2 lignes
                const fs = Math.min(20, Math.max(14, arcDeg * 0.52));
                ctx.font = `bold ${fs}px sans-serif`;
                ctx.fillStyle = seg.text;
                ctx.fillText(seg.label === 'JACKPOT' ? '🎰' : seg.label, textDist, -fs * 0.55);
                if (seg.type !== 'nothing') {
                    ctx.font = `${fs - 1}px sans-serif`;
                    ctx.fillText('🪙', textDist, fs * 0.95);
                }
            } else if (arcDeg >= 10) {
                // Segment moyen : juste le label
                const fs = Math.min(16, Math.max(13, arcDeg * 0.50));
                ctx.fillStyle = seg.text;
                ctx.font = `bold ${fs}px sans-serif`;
                ctx.fillText(seg.coins > 0 ? seg.label : '✗', textDist, 5);
            } else if (arcDeg >= 5) {
                // Petit segment : label compact
                ctx.fillStyle = seg.text;
                ctx.font = 'bold 11px sans-serif';
                ctx.fillText(seg.coins > 0 ? `+${seg.coins}` : '✗', textDist, 4);
            }
            ctx.restore();
        });

        // Hub central
        const hubGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, 28);
        hubGrad.addColorStop(0, '#3a1a6e');
        hubGrad.addColorStop(1, '#0d0820');
        ctx.beginPath();
        ctx.arc(cx, cy, 28, 0, 2 * Math.PI);
        ctx.fillStyle = hubGrad;
        ctx.fill();
        ctx.strokeStyle = getActiveTheme();
        ctx.lineWidth = 2.5;
        ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.font = '16px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('🎰', cx, cy);
    }

    window._drawWheel = drawWheel;
    drawWheel(0);

    // ─── Sélection aléatoire pondérée ───
    function weightedRandom() {
        let rnd = Math.random() * totalWeight;
        for (let i = 0; i < segments.length; i++) {
            rnd -= segments[i].weight;
            if (rnd <= 0) return i;
        }
        return segments.length - 1;
    }

    // ─── Confettis ───
    function spawnConfetti(count) {
        const colors = ['#f1c40f','#8a2be2','#2ecc71','#e74c3c','#3498db','#ff55ff','#fff'];
        for (let i = 0; i < count; i++) {
            const el = document.createElement('div');
            const sz = 4 + Math.random() * 9;
            el.style.cssText = `
                position:fixed; width:${sz}px; height:${sz}px;
                background:${colors[Math.floor(Math.random() * colors.length)]};
                border-radius:${Math.random() > 0.5 ? '50%' : '2px'};
                left:${Math.random() * 100}vw; top:-12px;
                z-index:99999; pointer-events:none;
                animation:confettiFall ${1.2 + Math.random() * 1.8}s ease-in ${Math.random() * 0.6}s forwards;
            `;
            document.body.appendChild(el);
            setTimeout(() => el.remove(), 3200);
        }
    }

    // ─── Affichage du résultat ───
    function showWheelResult(seg) {
        const el = document.getElementById('wheel-result');
        if (seg.type === 'nothing') {
            el.innerHTML = `<div style="font-size:0.95rem; font-weight:900; color:#555; animation:wheelResultPop 0.4s ease;">😔 Rien cette fois...</div>`;
            if (navigator.vibrate) navigator.vibrate([60]);
        } else {
            awardCoins(seg.coins, 'Roue du Destin !');
            const wcEl = document.getElementById('wheel-coins');
            if (wcEl) wcEl.innerText = getCoins() + ' 🪙';

            if (seg.jackpot) {
                if (navigator.vibrate) navigator.vibrate([100,50,100,50,200]);
                spawnConfetti(65);
                el.innerHTML = `
                    <div style="animation:wheelResultPop 0.4s ease; text-align:center;">
                        <div style="font-size:2rem; margin-bottom:4px;">🎰🎰🎰</div>
                        <div style="font-size:1.3rem; font-weight:900;
                            background:linear-gradient(90deg,#f1c40f,#ff55ff,#f1c40f);
                            -webkit-background-clip:text; -webkit-text-fill-color:transparent;
                            background-clip:text; margin-bottom:4px;">
                            JACKPOT ! +${seg.coins} 🪙
                        </div>
                        <div style="font-size:0.68rem; color:#888;">Chance ultime — 0.5% de probabilité !</div>
                    </div>`;
            } else if (seg.rare) {
                if (navigator.vibrate) navigator.vibrate([80,40,80]);
                spawnConfetti(28);
                el.innerHTML = `
                    <div style="animation:wheelResultPop 0.4s ease; text-align:center;">
                        <div style="font-size:1.5rem; font-weight:900; color:#f1c40f; margin-bottom:2px;">${seg.emoji} +${seg.coins} 🪙 !</div>
                        <div style="font-size:0.68rem; color:#888;">Gros gain !</div>
                    </div>`;
            } else {
                if (navigator.vibrate) navigator.vibrate(60);
                el.innerHTML = `
                    <div style="animation:wheelResultPop 0.4s ease;">
                        <div style="font-size:1.25rem; font-weight:900; color:#f1c40f;">${seg.emoji} +${seg.coins} 🪙 !</div>
                    </div>`;
            }
        }
    }

    // ─── Lancer la roue ───
    window.doSpin = () => {
        if (window._wheelSpinning) return;
        // 🔒 Verrou posé IMMÉDIATEMENT — empêche tout double-tap/double-appel
        window._wheelSpinning = true;
        if (window._wheelAnimFrame) { cancelAnimationFrame(window._wheelAnimFrame); window._wheelAnimFrame = null; }

        let sd;
        try { sd = JSON.parse(localStorage.getItem('wheelSpinData') || '{}'); } catch(e) { sd = {}; }
        const todayStr = new Date().toDateString();
        if (sd.date !== todayStr) { sd.date = todayStr; sd.count = 0; sd.history = []; }

        if ((sd.count || 0) >= MAX_DAILY) {
            window._wheelSpinning = false;
            showToast('🔄 Limite journalière atteinte ! Reviens demain.');
            return;
        }
        if (getCoins() < SPIN_COST) {
            window._wheelSpinning = false;
            showToast(`🪙 Il te faut ${SPIN_COST} pièces pour jouer !`);
            return;
        }

        spendCoins(SPIN_COST);
        updateCoinDisplay();

        sd.count = (sd.count || 0) + 1;
        const winIndex = weightedRandom();
        const winSeg   = segments[winIndex];
        if (!sd.history) sd.history = [];
        sd.history.push(winSeg.coins);
        localStorage.setItem('wheelSpinData', JSON.stringify(sd));

        const wcEl = document.getElementById('wheel-coins');
        if (wcEl) wcEl.innerText = getCoins() + ' 🪙';
        const slEl = document.getElementById('wheel-spins-left');
        const newLeft = MAX_DAILY - sd.count;
        if (slEl) { slEl.innerText = `${newLeft} / ${MAX_DAILY}`; slEl.style.color = newLeft > 0 ? getActiveTheme() : '#555'; }

        const btn = document.getElementById('wheel-launch-btn');
        if (btn) { btn.style.opacity = '0.35'; btn.style.pointerEvents = 'none'; }
        const _wheelRes = document.getElementById('wheel-result');
        if (_wheelRes) _wheelRes.innerHTML = '';

        // Angle cible : milieu du segment gagnant sous la flèche
        const winMidAngle = segAngles[winIndex].start + segAngles[winIndex].arc / 2;
        let targetAngle = -winMidAngle;
        targetAngle = ((targetAngle % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);

        const currentAngle = ((window._wheelAngle % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
        let delta = targetAngle - currentAngle;
        if (delta <= 0) delta += Math.PI * 2;

        // Micro-variation dans le segment (plus naturel)
        const jitter        = (Math.random() - 0.5) * segAngles[winIndex].arc * 0.55;
        const spins         = 7 + Math.floor(Math.random() * 5);
        const totalRotation = Math.PI * 2 * spins + delta + jitter;

        // Durée plus longue pour les gros gains (suspense)
        const base     = 3800 + Math.random() * 800;
        const duration = winSeg.jackpot ? base + 2200 : winSeg.rare ? base + 1000 : base;

        const startTime  = performance.now();
        const startAngle = window._wheelAngle;

        // Easing mixte : vif au départ, très progressif sur les 30% finaux → pas de saut
        function easeOut(t) {
            if (t < 0.7) {
                // Phase rapide : expo-out classique
                return 1 - Math.pow(1 - t / 0.7, 3) * 0.7;
            } else {
                // Phase lente : décélération linéaire ultra-douce
                const p = (t - 0.7) / 0.3;
                return 0.3 + p * 0.7 - 0.04 * Math.sin(p * Math.PI);
            }
        }

        function animate(now) {
            const t = Math.min((now - startTime) / duration, 1);
            window._wheelAngle = startAngle + totalRotation * easeOut(t);
            window._drawWheel(window._wheelAngle);
            if (t < 1) { window._wheelAnimFrame = requestAnimationFrame(animate); return; }

            window._wheelSpinning = false;
            showWheelResult(winSeg);
            setTimeout(() => {
                if (btn) { btn.style.opacity = '1'; btn.style.pointerEvents = 'auto'; }
            }, 1400);
        }
        window._wheelAnimFrame = requestAnimationFrame(animate);
    };
}

function spinWheel() { showWheel(); }



function showShop() {
    currentLevel = 'shop';
    updateHeaderBtns();
    sectionTitle.innerText = 'BOUTIQUE';
    const owned = getOwnedItems();
    const coins = getCoins();
    const activeTheme = getActiveTheme();
    const activeTitle = getActiveTitle();
    const activeFrame = getActiveFrame();

    // Violet gratuit — précalculé pour éviter les backticks imbriqués
    const violetBorderColor = activeTheme === '#8a2be2' ? '#8a2be2' : 'rgba(138,43,226,0.25)';
    const violetBtn = activeTheme === '#8a2be2'
        ? '<div style="font-size:0.75rem; font-weight:800; color:#2ecc71;">✅ Actif</div>'
        : '<div onclick="applyTheme(\'#8a2be2\'); localStorage.setItem(\'ms_active_theme\',\'#8a2be2\'); showShop();" style="font-size:0.78rem; font-weight:900; color:#fff; cursor:pointer; padding:8px 16px; background:linear-gradient(135deg,#8a2be2,#6a0dad); border-radius:12px;">Revenir</div>';

    const renderSection = (title, type, emoji) => {
        const items = SHOP_ITEMS.filter(i => i.type === type);
        return `
            <div style="grid-column:1/-1;display:flex;align-items:center;gap:8px;margin:8px 0 4px;">
                <span style="font-size:0.9rem;">${emoji}</span>
                <span style="font-size:0.65rem;color:#555;letter-spacing:2px;font-weight:700;">${title}</span>
            </div>
            ${items.map(item => {
                const isOwned = owned.includes(item.id);
                const isActive = (item.type==='theme' && activeTheme===item.color) || (item.type==='title' && activeTitle===item.titleText) || (item.type==='frame' && activeFrame===item.frameColor);
                const canAfford = coins >= item.price;
                return `
                <div onclick="confirmBuy('${item.id}')" style="grid-column:span 1;background:${item.rare ? 'linear-gradient(145deg,#1a1000,#2a1800)' : 'rgba(255,255,255,0.03)'};border:1.5px solid ${isActive ? (item.rare?'#f1c40f':'var(--neon)') : isOwned ? '#333' : item.rare ? '#f1c40f44' : '#222'};border-radius:18px;padding:18px 10px;text-align:center;cursor:pointer;position:relative;transition:transform 0.15s;" onmouseenter="this.style.transform='translateY(-2px)'" onmouseleave="this.style.transform='translateY(0)'">
                    ${item.rare ? '<div style="position:absolute;top:8px;right:8px;font-size:0.55rem;color:#f1c40f;font-weight:800;letter-spacing:1px;">RARE</div>' : ''}
                    <div style="font-size:1.8rem;margin-bottom:8px;">${item.icon}</div>
                    <div style="font-size:0.72rem;font-weight:900;color:#fff;margin-bottom:4px;">${item.label}</div>
                    <div style="font-size:0.6rem;color:#555;margin-bottom:8px;">${item.desc}</div>
                    <div style="font-size:0.7rem;font-weight:800;color:${isActive ? '#2ecc71' : isOwned ? 'var(--neon)' : canAfford ? '#f1c40f' : '#555'};">
                        ${isActive ? '✅ Actif' : isOwned ? '✓ Activer' : `🪙 ${item.price}`}
                    </div>
                </div>`;
            }).join('')}`;
    };

    mainGrid.innerHTML = `
        <div style="grid-column:1/-1;text-align:center;padding:4px 0 16px;">
            <div style="font-size:1.2rem;font-weight:900;color:#f1c40f;">🪙 ${coins} pièces</div>
        </div>

        <!-- 💜 Violet Original — gratuit, toujours dispo -->
        <div style="grid-column:1/-1; display:flex; align-items:center; justify-content:space-between; background:rgba(138,43,226,0.08); border:1.5px solid ${violetBorderColor}; border-radius:16px; padding:16px 18px; margin-bottom:4px;">
            <div style="display:flex; align-items:center; gap:14px;">
                <span style="font-size:1.6rem;">💜</span>
                <div>
                    <div style="font-size:0.85rem; font-weight:900; color:#fff;">Violet Original</div>
                    <div style="font-size:0.65rem; color:var(--neon); margin-top:3px;">Thème de base — toujours gratuit 🆓</div>
                </div>
            </div>
            ${violetBtn}
        </div>

        <!-- 🎰 Roue du Destin — clic = page dédiée -->
        <div onclick="showWheel()" style="grid-column:1/-1; background:linear-gradient(135deg,#1a0a2e,#2a0a1e); border:1.5px solid var(--neon-glow); border-radius:20px; padding:20px; display:flex; align-items:center; gap:16px; cursor:pointer; margin-bottom:4px; transition:border-color 0.2s;" onmouseenter="this.style.borderColor=getActiveTheme()" onmouseleave="this.style.borderColor='var(--neon-glow)'">
            <div style="font-size:2.8rem;">🎰</div>
            <div style="flex:1;">
                <div style="font-size:0.88rem; font-weight:900; color:#fff; margin-bottom:4px;">Roue du Destin</div>
                <div style="font-size:0.7rem; color:var(--neon);">Hasard total · Mise 10 🪙 · Jusqu'à 100 🪙</div>
            </div>
            <i class="fas fa-chevron-right" style="color:#555; font-size:0.9rem;"></i>
        </div>

        ${renderSection('THÈMES', 'theme', '🎨')}
        ${renderSection('TITRES DE PROFIL', 'title', '👑')}
        ${renderSection('CADRES DE PROFIL', 'frame', '🖼️')}
        ${renderSection('BOOSTS', 'boost', '⚡')}
    `;
}

const LEVELS = [
    // 🆕 Titres de paliers plus motivants (demandé) — mêmes seuils XP,
    // mêmes couleurs, juste des noms qui donnent envie de progresser.
    { min: 0,    label: "🌱 Apprenti",              color: "#95a5a6" },
    { min: 100,  label: "📖 Étudiant sérieux",      color: "#3498db" },
    { min: 250,  label: "🔥 Révisant du feu",       color: "#e67e22" },
    { min: 500,  label: "⚡ Philosophe",             color: "#9b59b6" },
    { min: 800,  label: "🎯 Stratège du Bac",       color: "#e74c3c" },
    { min: 1200, label: "👑 Légende de Terminale",  color: "#f1c40f" },
];

function getXPData() {
    // 🔧 FIX (progression perdue au changement d'appareil) : si un compte
    // est connecté et que Firestore a déjà répondu, on lit les vraies
    // données serveur (source de vérité, identiques sur tous les
    // appareils). Sinon (invité, ou avant que Firestore ait répondu), on
    // retombe sur le cache local pour ne jamais bloquer l'affichage.
    if (window.MS && window.MS.user && window.MS.userData) {
        return window.MS.userData;
    }
    try {
        return JSON.parse(localStorage.getItem('xpData')) || { xp: 0, streak: 0, lastDate: null, quizDone: [] };
    } catch(e) {
        localStorage.removeItem('xpData');
        return { xp: 0, streak: 0, lastDate: null, quizDone: [] };
    }
}
function saveXPData(data) {
    // Cache local d'abord : l'app reste instantanée et fonctionne hors ligne.
    localStorage.setItem('xpData', JSON.stringify(data));
    // 🔧 FIX (progression jamais envoyée au serveur) : on pousse aussi
    // vers Firestore quand un compte est connecté, via le pont exposé
    // dans firebase-config.js (voir commentaire là-bas).
    if (window.MS && window.MS.user && typeof window._msSaveUserData === 'function') {
        window._msSaveUserData(data);
    }
}

function getCurrentLevel(xp) {
    let level = LEVELS[0];
    for (const l of LEVELS) { if (xp >= l.min) level = l; }
    return level;
}
function getNextLevel(xp) {
    for (const l of LEVELS) { if (xp < l.min) return l; }
    return null;
}

function updateStreak() {
    const data = getXPData();
    const today = new Date().toDateString();
    if (data.lastDate === today) return data; // Déjà compté aujourd'hui
    const yesterday = new Date(Date.now() - 86400000).toDateString();
    if (data.lastDate === yesterday) {
        // Streak continue → bonus XP (seulement si streak >= 2)
        data.streak += 1;
        data.xp += XP_REWARDS.STREAK_BONUS * Math.min(data.streak, 10);
        setTimeout(() => awardCoins(COIN_REWARDS.STREAK_DAILY, 'Connexion du jour 🔥'), 1500);
    } else {
        data.streak = 1;
    }
    data.lastDate = today;
    saveXPData(data);
    return data;
}

// ─── SÉRIE HEBDOMADAIRE ────────────────────────────────────────
// 5 jours actifs sur les 7 derniers → +50 XP +30 🪙 (une fois par semaine)
function checkSerieHebdo() {
    // Clé semaine ISO (ex: "2026-W16")
    const now = new Date();
    const startOfYear = new Date(now.getFullYear(), 0, 1);
    const weekNum = Math.ceil(((now - startOfYear) / 86400000 + startOfYear.getDay() + 1) / 7);
    const weekKey = now.getFullYear() + '-W' + weekNum;
    const rewardKey = 'ms_serie_hebdo_' + weekKey;
    if (localStorage.getItem(rewardKey)) return; // Déjà récompensé cette semaine

    const xpHistory = JSON.parse(localStorage.getItem('ms_xp_history') || '{}');
    let activeDays = 0;
    for (let i = 0; i < 7; i++) {
        const d = new Date(now); d.setDate(d.getDate() - i);
        const key = d.toISOString().slice(0, 10);
        if ((xpHistory[key] || 0) > 0) activeDays++;
    }
    if (activeDays >= 5) {
        localStorage.setItem(rewardKey, '1');
        // Reward : +50 XP +30 coins
        setTimeout(function() {
            awardXP(50, 'Série hebdo 5/7 🗓️');
            setTimeout(function() { awardCoins(30, 'Série hebdo 🗓️'); }, 1000);
            // Toast spécial
            const t = document.createElement('div');
            t.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:linear-gradient(135deg,#0a1a0a,#1a2a10);border:2px solid #22c55e88;border-radius:20px;padding:24px 28px;text-align:center;z-index:99999;box-shadow:0 10px 40px #22c55e33;';
            t.innerHTML = '<div style="font-size:2rem;margin-bottom:8px;">🗓️</div>'
                + '<div style="font-size:1rem;font-weight:900;color:#fff;margin-bottom:4px;">Série hebdo accomplie !</div>'
                + '<div style="font-size:0.75rem;color:#22c55e;">' + activeDays + ' jours actifs cette semaine</div>'
                + '<div style="font-size:0.8rem;color:#f1c40f;font-weight:800;margin-top:10px;">+50 XP &nbsp;+30 🪙</div>';
            document.body.appendChild(t);
            setTimeout(function() { if (t.parentNode) t.remove(); }, 3500);
        }, 2000);
    }
}

function awardXP(amount, reason) {
    const data = getXPData();
    // 🆕 On note le palier AVANT le gain, pour pouvoir détecter un
    // passage de niveau juste après et déclencher la célébration.
    const levelBefore = getCurrentLevel(data.xp || 0);
    data.xp += amount;
    saveXPData(data);
    showXPToast(amount, reason);
    updateXPBar();
    recordDailyXP(amount);
    if (typeof _sessionTrackXP === 'function') _sessionTrackXP(amount);

    const levelAfter = getCurrentLevel(data.xp);
    if (levelAfter.label !== levelBefore.label) {
        // Petit délai pour ne pas superposer les deux toasts (XP puis niveau).
        setTimeout(() => showLevelUpToast(levelAfter), 900);
        // 🆕 ANALYTICS : passage de palier, événement rare et significatif —
        // utile pour mesurer la progression réelle et la rétention.
        if (typeof window._msTrack === 'function') {
            window._msTrack('level_up', { new_level: levelAfter.label, total_xp: data.xp });
        }
    }
}

// 🆕 Célébration de passage de palier — plus marquante qu'un simple
// toast XP, car ça n'arrive qu'occasionnellement (contrairement au
// toast XP qui apparaît à chaque petite action).
function showLevelUpToast(level) {
    const existing = document.getElementById('level-up-toast');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.id = 'level-up-toast';
    toast.style.cssText = `
        position:fixed; top:50%; left:50%; transform:translate(-50%,-50%) scale(0.85);
        background:linear-gradient(135deg,#1a1a2e,#16213e);
        border:1.5px solid ${level.color}88; color:#fff;
        text-align:center; padding:22px 30px; border-radius:20px;
        box-shadow:0 10px 40px ${level.color}44;
        z-index:99999; opacity:0; transition:all 0.35s cubic-bezier(.34,1.56,.64,1);
    `;
    toast.innerHTML = `
        <div style="font-size:0.72rem;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">Nouveau palier</div>
        <div style="font-size:1.3rem;font-weight:900;color:${level.color};">${level.label}</div>
    `;
    document.body.appendChild(toast);
    requestAnimationFrame(() => {
        toast.style.opacity = '1';
        toast.style.transform = 'translate(-50%,-50%) scale(1)';
    });
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translate(-50%,-50%) scale(0.9)';
        setTimeout(() => toast.remove(), 350);
    }, 2800);
}

function showXPToast(amount, reason) {
    const existing = document.getElementById('xp-toast');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.id = 'xp-toast';
    toast.style.cssText = `
        position:fixed; top:55px; left:50%; transform:translateX(-50%) translateY(-10px);
        background:linear-gradient(135deg,#1a1a2e,#16213e);
        border:1px solid #f1c40f66; color:#f1c40f;
        font-weight:bold; font-size:0.88rem;
        padding:10px 22px; border-radius:30px;
        box-shadow:0 4px 20px #f1c40f33;
        z-index:9999; opacity:0; transition:all 0.3s ease; white-space:nowrap;
    `;
    toast.textContent = `+${amount} XP ⚡ ${reason}`;
    document.body.appendChild(toast);
    requestAnimationFrame(() => {
        toast.style.opacity = '1';
        toast.style.transform = 'translateX(-50%) translateY(0)';
    });
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(-50%) translateY(-10px)';
        setTimeout(() => toast.remove(), 200);
    }, 2500);
}

function updateXPBar() {
    const data = getXPData();
    const bar = document.getElementById('xp-bar-fill');
    const xpText = document.getElementById('xp-text');
    const levelText = document.getElementById('level-text');
    const streakText = document.getElementById('streak-text');
    if (!bar) return;
    const level = getCurrentLevel(data.xp);
    const next = getNextLevel(data.xp);
    const xpInLevel = data.xp - level.min;
    const xpNeeded = next ? next.min - level.min : 1;
    const pct = next ? Math.min(100, Math.round((xpInLevel / xpNeeded) * 100)) : 100;
    bar.style.width = pct + '%';
    bar.style.background = `linear-gradient(90deg,${level.color},${level.color}aa)`;
    if (xpText) xpText.textContent = next ? `${xpInLevel}/${xpNeeded} XP` : `${data.xp} XP ✓`;
    if (levelText) { levelText.textContent = level.label; levelText.style.color = level.color; }
    if (streakText) streakText.textContent = `🔥 ${data.streak}j`;
}

function injectXPBar() {
    if (document.getElementById('xp-hud')) return;
    const data = getXPData();
    const level = getCurrentLevel(data.xp);
    const next = getNextLevel(data.xp);
    const xpInLevel = data.xp - level.min;
    const xpNeeded = next ? next.min - level.min : 1;
    const pct = next ? Math.min(100, Math.round((xpInLevel / xpNeeded) * 100)) : 100;
    const hud = document.createElement('div');
    hud.id = 'xp-hud';
    hud.style.cssText = `
        position:fixed; top:0; left:0; right:0; z-index:1000;
        background:#0d0d0d; border-bottom:1px solid #1e1e1e;
        padding:7px 14px 9px;
        display:flex; align-items:center; gap:10px;
    `;
    hud.innerHTML = `
        <span id="level-text" style="font-size:0.75rem;font-weight:bold;color:${level.color};white-space:nowrap;flex-shrink:0;">${level.label}</span>
        <div style="flex:1;background:#1e1e1e;border-radius:10px;height:7px;overflow:hidden;">
            <div id="xp-bar-fill" style="height:100%;width:${pct}%;background:linear-gradient(90deg,${level.color},${level.color}aa);border-radius:10px;transition:width 0.6s ease;"></div>
        </div>
        <span id="xp-text" style="font-size:0.7rem;color:#666;white-space:nowrap;flex-shrink:0;">${next ? `${xpInLevel}/${xpNeeded}` : `MAX`}</span>
        <span id="coin-display" style="font-size:0.75rem;font-weight:bold;color:#f1c40f;white-space:nowrap;flex-shrink:0;cursor:pointer;" onclick="showShop()">🪙 ${getCoins()}</span>
        <span id="streak-text" style="font-size:0.78rem;font-weight:bold;color:#e67e22;white-space:nowrap;flex-shrink:0;cursor:pointer;" onclick="showStreakModal()">🔥 ${data.streak}j</span>
    `;
    document.body.prepend(hud);
    const appDiv = document.getElementById('app');
    if (appDiv) appDiv.style.paddingTop = '38px';
}

function showStreakModal() {
    const data = getXPData();
    const level = getCurrentLevel(data.xp);
    const next = getNextLevel(data.xp);
    const existing = document.getElementById('streak-modal');
    if (existing) { existing.remove(); return; }
    const modal = document.createElement('div');
    modal.id = 'streak-modal';
    modal.style.cssText = `
        position:fixed; top:50px; left:50%; transform:translateX(-50%);
        background:#141414; border:1px solid #2a2a2a; border-radius:20px;
        padding:24px 28px; z-index:9998; min-width:260px; max-width:320px;
        box-shadow:0 10px 40px rgba(0,0,0,0.8);
        text-align:center;
    `;
    const days = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];
    const today = new Date().getDay();
    const dotsHtml = days.map((d, i) => {
        const active = i === today;
        const past = (i < today && data.streak >= today - i) || (i === today);
        return `<div style="text-align:center;">
            <div style="width:34px;height:34px;border-radius:50%;margin:0 auto 4px;
                background:${past ? '#e67e22' : '#1e1e1e'};
                border:2px solid ${past ? '#e67e22' : '#333'};
                display:flex;align-items:center;justify-content:center;
                font-size:1rem;">${past ? '🔥' : ''}</div>
            <div style="font-size:0.65rem;color:${active ? '#e67e22' : '#666'};font-weight:${active?'bold':'normal'};">${d}</div>
        </div>`;
    }).join('');
    modal.innerHTML = `
        <div style="font-size:2.5rem;margin-bottom:6px;">🔥</div>
        <div style="font-size:1.5rem;font-weight:900;color:#e67e22;margin-bottom:2px;">${data.streak} jour${data.streak > 1 ? 's' : ''} de suite</div>
        <div style="font-size:0.8rem;color:#666;margin-bottom:18px;">${(function(){
            const s = data.streak;
            if (s === 0) return "Lance ta série aujourd'hui !";
            if (s === 1) return "🎯 Première journée — c'est parti poto !";
            if (s <= 3) return "🔥 " + s + " jours — chaud comme la drill !";
            if (s <= 6) return "💪 " + s + " jours — t'es dans le bon flow !";
            if (s <= 13) return "⚡ " + s + " jours — régularité = maîtrise !";
            if (s <= 20) return "🚀 " + s + " jours — niveau élite, continue !";
            if (s <= 29) return "👑 " + s + " jours — t'es un monstre du Bac !";
            return "🏆 " + s + " jours — LÉGENDE MusicSchool !";
        })()}</div>
        <div style="display:flex;justify-content:center;gap:6px;margin-bottom:20px;">${dotsHtml}</div>
        <div style="background:#1a1a1a;border-radius:12px;padding:14px;margin-bottom:14px;">
            <div style="font-size:0.7rem;color:${level.color};font-weight:bold;letter-spacing:1px;margin-bottom:8px;">⚡ NIVEAU : ${level.label}</div>
            <div style="background:#111;border-radius:8px;height:8px;overflow:hidden;margin-bottom:6px;">
                <div style="height:100%;width:${next ? Math.round(((data.xp - level.min)/(next.min - level.min))*100) : 100}%;background:${level.color};border-radius:8px;transition:width 0.5s;"></div>
            </div>
            <div style="font-size:0.8rem;color:#aaa;">${data.xp} XP${next ? ` → ${next.min} XP pour "${next.label}"` : ' — Niveau MAX 👑'}</div>
        </div>
        <button onclick="document.getElementById('streak-modal').remove()" style="
            background:#1e1e1e;border:1px solid #333;color:#aaa;
            padding:8px 20px;border-radius:20px;font-size:0.85rem;cursor:pointer;
        ">Fermer</button>
    `;
    document.body.appendChild(modal);
    document.addEventListener('click', function closeModal(e) {
        if (!modal.contains(e.target) && e.target.id !== 'streak-text') {
            modal.remove();
            document.removeEventListener('click', closeModal);
        }
    }, { capture: true });
}



