function showToast(message) {
    const existing = document.getElementById('ms-toast');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.id = 'ms-toast';
    toast.style.cssText = `
        position:fixed; bottom:90px; left:50%; transform:translateX(-50%) translateY(10px);
        background:#1e1e1e; border:1px solid #333; color:#fff;
        font-size:0.85rem; font-weight:600;
        padding:12px 22px; border-radius:30px;
        box-shadow:0 4px 20px rgba(0,0,0,0.6);
        z-index:99999; opacity:0; transition:all 0.3s ease;
        white-space:nowrap; max-width:90vw; text-align:center;
    `;
    toast.textContent = message;
    document.body.appendChild(toast);
    requestAnimationFrame(() => {
        toast.style.opacity = '1';
        toast.style.transform = 'translateX(-50%) translateY(0)';
    });
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(-50%) translateY(10px)';
        setTimeout(() => toast.remove(), 200);
    }, 3000);
}

function updateHeaderBtns() {
    // Réappliquer la couleur du titre selon la matière courante
    if (window._setTitleColor && currentSubject) {
        window._setTitleColor(currentSubject);
    } else if (window._setTitleColor && currentLevel === 'a-mediter') {
        window._setTitleColor('a-mediter');
    }
    const drawerBtn = document.getElementById('drawer-btn');
    const backBtnEl = document.getElementById('back-btn');
    const onGrades = (currentLevel === 'grades');
    const searchBar = document.getElementById('ms-search-bar');
    const hideSearch = ['profile','stats','shop','wheel','minigames','minigames-picker','minigames-chapter','game-match','game-sprint','game-word','game-flash','game-truefalse','game-chrono','game-result','quiz-surprise','classement','favorites'].includes(currentLevel);
    if (searchBar) searchBar.style.display = hideSearch ? 'none' : (currentLevel !== null ? 'block' : 'none');

    if (drawerBtn) {
        if (onGrades) drawerBtn.classList.remove('hidden');
        else drawerBtn.classList.add('hidden');
    }
    // Bouton header toujours masqué — remplacé par le bouton fixe
    if (backBtnEl) backBtnEl.classList.add('hidden');

    // Supprimer le bouton search du header (doublon avec barre d'accueil)
    const oldSearchBtn = document.getElementById('global-search-btn');
    if (oldSearchBtn) oldSearchBtn.remove();

    // Bouton retour fixe en haut à gauche — couleur du thème actif
    const theme = getActiveTheme();
    let floatBack = document.getElementById('float-back-btn');
    if (!floatBack) {
        floatBack = document.createElement('div');
        floatBack.id = 'float-back-btn';
        floatBack.onclick = goBack;
        document.body.appendChild(floatBack);
    }
    floatBack.style.cssText = `position:fixed; top:52px; left:12px; z-index:1001; width:44px; height:44px; border-radius:50%; background:rgba(20,10,40,0.92); border:1.5px solid ${theme}88; display:flex; align-items:center; justify-content:center; cursor:pointer; box-shadow:0 4px 20px ${theme}44; backdrop-filter:blur(10px); transition:all 0.2s;`;
    floatBack.innerHTML = `<span style="color:${theme}; font-size:1.1rem; font-weight:900; line-height:1;">‹</span>`;
    floatBack.style.display = onGrades ? 'none' : 'flex';
    // ✅ Si le player est ouvert, toujours masquer le bouton retour flottant
    const _fp = document.getElementById('full-player');
    if (_fp && !_fp.classList.contains('hidden')) {
        floatBack.style.display = 'none';
    }

    const tiroir = document.getElementById('tiroir-grades');
    if (tiroir) tiroir.style.display = 'none';

    const tiroirToggle = document.getElementById('tiroir-toggle');
    if (tiroirToggle) tiroirToggle.style.display = onGrades ? 'flex' : 'none';

    // 🔧 FIX : le rond avatar en haut à droite (bouton "aller au profil")
    // n'a plus de raison d'être visible une fois qu'on EST sur le profil
    // — le gros avatar centré, plus bas, fait déjà ce rôle.
    const profileBtn = document.getElementById('profile-btn');
    if (profileBtn) profileBtn.style.display = (currentLevel === 'profile') ? 'none' : 'flex';
}

// 🔧 NOUVEAU : titre de section pleine largeur dans une grille de dossiers
// (ex: séparer "TES COURS" des "OUTILS" dans l'écran d'une matière).
function _sectionHeader(text, icon) {
    const div = document.createElement('div');
    div.style.cssText = 'grid-column:1/-1;display:flex;align-items:center;gap:8px;margin:6px 2px 2px;padding-top:6px;';
    div.innerHTML = `<span style="font-size:0.72rem;font-weight:900;letter-spacing:1.2px;color:#888;text-transform:uppercase;">${icon ? icon + ' ' : ''}${text}</span><span style="flex:1;height:1px;background:linear-gradient(90deg,#8a2be255,transparent);"></span>`;
    return div;
}

