// ── Helpers streak méditation ────────────────────────────────
// ── Helpers streak méditation ────────────────────────────────
function getAMStreak() {
    try { return JSON.parse(localStorage.getItem('ms_am_streak') || '{"count":0,"last":""}'); }
    catch(e) { return { count: 0, last: '' }; }
}
function updateAMStreak() {
    const today = new Date().toISOString().split('T')[0];
    const s = getAMStreak();
    const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
    if (s.last === today) return s;
    const newCount = (s.last === yesterday) ? s.count + 1 : 1;
    const newStreak = { count: newCount, last: today };
    localStorage.setItem('ms_am_streak', JSON.stringify(newStreak));
    return newStreak;
}

// ── Vote "T'as vécu ça ?" ────────────────────────────────────
function getAMVotes() {
    try { return JSON.parse(localStorage.getItem('ms_am_votes') || '{"oui":0,"non":0,"voted":false}'); }
    catch(e) { return { oui: 0, non: 0, voted: false }; }
}
function submitAMVote(choice) {
    const v = getAMVotes();
    if (v.voted) return;
    v[choice]++;
    v.voted = true;
    localStorage.setItem('ms_am_votes', JSON.stringify(v));
    renderAMVote();
    showToast(choice === 'oui' ? '😭 On est tous passés par là !' : '😑 T\'es fort toi...');
    awardXP(5, 'Vote méditation !');
    awardCoins(2, 'Vote');
}
function renderAMVote() {
    const el = document.getElementById('am-vote-zone');
    if (!el) return;
    const v = getAMVotes();
    const total = v.oui + v.non;
    const ouiPct = total > 0 ? Math.round(v.oui / total * 100) : 50;
    const nonPct = 100 - ouiPct;
    if (v.voted) {
        el.innerHTML = `
            <div style="font-size:0.7rem;color:#f59e0b88;font-weight:700;letter-spacing:1px;margin-bottom:10px;text-align:center;">📊 RÉSULTATS</div>
            <div style="margin-bottom:8px;">
                <div style="display:flex;justify-content:space-between;font-size:0.72rem;color:#ccc;margin-bottom:4px;">
                    <span>😭 T'as vécu ça</span><span style="color:#f59e0b;font-weight:800;">${ouiPct}%</span>
                </div>
                <div style="height:6px;background:#1a1000;border-radius:4px;overflow:hidden;">
                    <div style="height:100%;width:${ouiPct}%;background:linear-gradient(90deg,#f59e0b,#fbbf24);border-radius:4px;transition:width 0.6s;"></div>
                </div>
            </div>
            <div>
                <div style="display:flex;justify-content:space-between;font-size:0.72rem;color:#ccc;margin-bottom:4px;">
                    <span>😑 Jamais vu</span><span style="color:#888;font-weight:800;">${nonPct}%</span>
                </div>
                <div style="height:6px;background:#1a1a1a;border-radius:4px;overflow:hidden;">
                    <div style="height:100%;width:${nonPct}%;background:#444;border-radius:4px;transition:width 0.6s;"></div>
                </div>
            </div>
            <div style="font-size:0.65rem;color:#555;text-align:center;margin-top:8px;">${total} vote${total>1?'s':''} au total</div>
        `;
    } else {
        el.innerHTML = `
            <div style="font-size:0.72rem;color:#f59e0b;font-weight:700;text-align:center;margin-bottom:12px;">T'as déjà vécu un de ces moments ? 😑</div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
                <button onclick="submitAMVote('oui')" style="padding:12px;background:#1a1000;border:1.5px solid #f59e0b55;border-radius:12px;color:#f59e0b;font-size:0.82rem;font-weight:800;cursor:pointer;">😭 Oui trop</button>
                <button onclick="submitAMVote('non')" style="padding:12px;background:#111;border:1.5px solid #333;border-radius:12px;color:#888;font-size:0.82rem;font-weight:800;cursor:pointer;">😑 Jamais</button>
            </div>
        `;
    }
}

