function fillAMSituation(text) {
    const inp = document.getElementById('am-soumet-input');
    if (inp) { inp.value = text; inp.style.height = 'auto'; inp.style.height = inp.scrollHeight + 'px'; }
}

async function sendAMSituation() {
    const inp = document.getElementById('am-soumet-input');
    const msgs = document.getElementById('am-soumet-messages');
    const btn = document.getElementById('am-soumet-send');
    if (!inp || !msgs) return;
    const text = inp.value.trim();
    if (!text) return;

    inp.value = '';
    inp.style.height = 'auto';
    if (btn) btn.disabled = true;

    // Message user
    const userDiv = document.createElement('div');
    userDiv.style.cssText = 'display:flex;justify-content:flex-end;';
    userDiv.innerHTML = `<div style="background:linear-gradient(135deg,#f59e0b,#f97316);border-radius:16px 16px 4px 16px;padding:12px 15px;max-width:82%;font-size:0.82rem;color:#000;font-weight:700;line-height:1.5;">${text}</div>`;
    msgs.appendChild(userDiv);

    // Typing indicator
    const typingDiv = document.createElement('div');
    typingDiv.id = 'am-typing';
    typingDiv.style.cssText = 'display:flex;justify-content:flex-start;';
    typingDiv.innerHTML = `<div style="padding:12px 16px;border-radius:16px 16px 16px 4px;background:#1a1000;border:1px solid #f59e0b22;">
        <div style="display:flex;gap:5px;align-items:center;">
            <div style="width:6px;height:6px;border-radius:50%;background:#f59e0b;animation:bounce 1s infinite 0s;"></div>
            <div style="width:6px;height:6px;border-radius:50%;background:#f59e0b;animation:bounce 1s infinite 0.2s;"></div>
            <div style="width:6px;height:6px;border-radius:50%;background:#f59e0b;animation:bounce 1s infinite 0.4s;"></div>
        </div>
    </div>`;
    msgs.appendChild(typingDiv);
    msgs.scrollTop = msgs.scrollHeight;

    var systemPrompt = 'Tu es "À Méditer 😑" — le poto sage qui réagit aux situations gênantes avec humour bienveillant et vérité. Tu parles comme un ami qui a du recul, pas de structure rigide. Tu ressens la scène, tu la commentes naturellement, et tu finis par une **💡 Leçon du moment** courte et mémorable. Si on demande une maxime, t\'en sors une vraie. 120 mots max. Français naturel.';

    try {
        const reply = await callClaude(systemPrompt, text);
        document.getElementById('am-typing')?.remove();
        const replyDiv = document.createElement('div');
        replyDiv.style.cssText = 'display:flex;justify-content:flex-start;';
        replyDiv.innerHTML = `<div style="background:#1a1000;border:1px solid #f59e0b22;border-radius:16px 16px 16px 4px;padding:14px 16px;max-width:85%;font-size:0.82rem;color:#ccc;line-height:1.7;">${_parseMarkdown(_escapeHtml(reply))}</div>`;
        msgs.appendChild(replyDiv);
        msgs.scrollTop = msgs.scrollHeight;
        awardXP(8, 'Méditation IA 😑');
        awardCoins(3, 'Méditation');
    } catch(err) {
        document.getElementById('am-typing')?.remove();
        const errDiv = document.createElement('div');
        errDiv.style.cssText = 'display:flex;justify-content:flex-start;';
        errDiv.innerHTML = `<div style="background:#1a1000;border:1px solid #f59e0b22;border-radius:16px 16px 16px 4px;padding:14px 16px;max-width:85%;font-size:0.82rem;color:#e74c3c;">⚠️ Connexion impossible. Réessaie.</div>`;
        msgs.appendChild(errDiv);
        msgs.scrollTop = msgs.scrollHeight;
    }
    if (btn) btn.disabled = false;
}

