function gradeMatch(l) {
    if (!l) return false;
    // Pas de grade → leçon universelle visible pour toutes les classes
    if (!l.grade) return true;
    const g = selectedGrade || 'terminale';
    const s = selectedSerie || null;
    const gradeOK = l.grade === g ||
           (g === 'terminale' && l.grade === 'première-terminale') ||
           (g === '1ere' && l.grade === 'première-terminale') ||
           (g === '1ere' && l.grade === 'premiere');
    if (!gradeOK) return false;
    if (s && l.series && l.series.length > 0 && !l.series.includes(s)) return false;
    return true;
}
