// ── Dossier notion dans la fiche philosophe ─────────────────────
function openPhiloNotionFolder(index, notion) {
    const p = philosophersData[index];
    if (!p || !p.quotes) return;

    const notionColors = {
        'Liberté':'#27ae60','Vérité':'#f39c12','Conscience':'#e74c3c',
        'Bonheur':'#e67e22','Justice':'#3498db','La religion':'#8e44ad',
        'La nature':'#2ecc71','La morale':'#e74c3c','Le temps':'#16a085',
        'Raison':'#f39c12','Travail':'#95a5a6','Le langage':'#3498db',
        'Le désir':'#e91e63',"L'État":'#2980b9','Autrui':'#e67e22',
        'Général':'#888'
    };
    const col = notionColors[notion] || p.color;

    // Filtrer les citations de cette notion
    const citations = p.quotes.filter(function(q){ return (q.notion || 'Général') === notion; });

    // Créer une overlay par-dessus la fiche
    var existing = document.getElementById('philo-notion-overlay');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'philo-notion-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;background:#09090f;overflow-y:auto;';

    var citationsHtml = citations.map(function(c, i) {
        // Explication générée depuis la pensée du philosophe si pas présente
        var explication = c.explication || (p.pensee ? p.pensee.split('.')[0] + '.' : 'Citation fondamentale de ' + p.name + ' sur la notion de ' + notion + '.');
        var bacUsage = c.bac || 'Utilisable dans une dissertation sur ' + notion + '. Cite ' + p.name + ' (' + (c.source || p.oeuvre) + ') pour illustrer ta thèse. Mets en opposition avec ' + p.contradiction + '.';

        var copyFn = "navigator.clipboard&&navigator.clipboard.writeText(" + JSON.stringify(c.text) + ").then(function(){showToast('📋 Citation copiée !')})";

        return '<div style="background:linear-gradient(145deg,#0d0d0d,#120c1e);border:1.5px solid ' + col + '33;border-radius:20px;padding:20px;margin-bottom:12px;">' +
            // Citation
            '<div style="position:relative;margin-bottom:14px;">' +
            '<div style="font-size:2rem;color:' + col + ';opacity:0.25;position:absolute;top:-8px;left:-4px;font-family:Georgia,serif;line-height:1;">"</div>' +
            '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;padding-left:16px;">' +
            '<div style="font-size:0.92rem;font-weight:800;color:#fff;line-height:1.5;font-style:italic;flex:1;">' + c.text + '</div>' +
            '<button onclick="' + copyFn + '" style="flex-shrink:0;background:' + col + '18;border:1px solid ' + col + '44;border-radius:8px;padding:4px 8px;cursor:pointer;font-size:0.7rem;color:' + col + ';">📋</button>' +
            '</div>' +
            '<div style="font-size:0.7rem;color:' + col + ';font-weight:700;margin-top:6px;padding-left:16px;">— ' + p.name + (c.source ? ' <span style="font-style:italic;font-weight:400;color:#555;">· ' + c.source + '</span>' : '') + '</div>' +
            '</div>' +
            // Séparateur
            '<div style="height:1px;background:#222;margin:12px 0;"></div>' +
            // Ce qu'il veut dire
            '<div style="margin-bottom:10px;">' +
            '<div style="font-size:0.62rem;color:#555;font-weight:900;letter-spacing:1.5px;margin-bottom:6px;">💡 CE QU\'IL VEUT DIRE</div>' +
            '<div style="font-size:0.82rem;color:#ccc;line-height:1.6;">' + explication + '</div>' +
            '</div>' +
            // Au Bac
            '<div style="background:#8a2be211;border:1px solid #8a2be233;border-radius:12px;padding:10px;">' +
            '<div style="font-size:0.62rem;color:#8a2be2;font-weight:900;letter-spacing:1px;margin-bottom:4px;">🎯 AU BAC</div>' +
            '<div style="font-size:0.78rem;color:#aaa;line-height:1.5;">' + bacUsage + '</div>' +
            '</div>' +
            '</div>';
    }).join('');

    overlay.innerHTML =
        // Header
        '<div style="position:sticky;top:0;z-index:10;background:#0d0d16;border-bottom:1px solid #1a1a2e;padding:12px 16px;display:flex;align-items:center;gap:12px;">' +
        '<button onclick="document.getElementById(\'philo-notion-overlay\').remove()" style="width:34px;height:34px;border-radius:50%;background:#151522;border:1px solid #222;color:#888;font-size:1.2rem;cursor:pointer;flex-shrink:0;">‹</button>' +
        '<div>' +
        '<div style="font-size:0.62rem;color:' + col + ';font-weight:800;letter-spacing:1px;">' + p.name.toUpperCase() + '</div>' +
        '<div style="font-size:1rem;font-weight:900;color:#fff;">' + notion + '</div>' +
        '</div>' +
        '</div>' +
        // Contenu
        '<div style="padding:16px;">' +
        // Sous-titre
        '<div style="background:' + col + '15;border:1px solid ' + col + '33;border-radius:14px;padding:12px 16px;margin-bottom:16px;display:flex;align-items:center;gap:10px;">' +
        '<div style="font-size:1.4rem;">' + (notion === 'Liberté' ? '🕊️' : notion === 'Vérité' ? '🔍' : notion === 'Conscience' ? '🧠' : notion === 'Bonheur' ? '😊' : notion === 'Justice' ? '⚖️' : notion === 'La religion' ? '✝️' : notion === 'La nature' ? '🌿' : notion === 'Le temps' ? '⏳' : notion === 'La morale' ? '⚖️' : notion === 'Raison' ? '🧩' : '📚') + '</div>' +
        '<div>' +
        '<div style="font-size:0.88rem;font-weight:800;color:#fff;">' + notion + '</div>' +
        '<div style="font-size:0.65rem;color:#555;margin-top:2px;">' + citations.length + ' citation' + (citations.length > 1 ? 's' : '') + ' de ' + p.name + '</div>' +
        '</div>' +
        '</div>' +
        citationsHtml +
        '<div style="height:40px;"></div>' +
        '</div>';

    document.getElementById('full-player').appendChild(overlay);
    overlay.scrollTop = 0;
}

