// showDailyMotivation supprimée — remplacée par showStartupQuote (avec photo auteur)
function closeDailyMotivation() {
    var el = document.getElementById('daily-motivation');
    if (el) {
        el.style.transition = 'opacity 0.3s';
        el.style.opacity = '0';
        setTimeout(function() { el.remove(); checkDailyObjectif(); }, 300);
    } else {
        checkDailyObjectif();
    }
}

function checkDailyObjectif() {
    var today = new Date().toDateString();
    var lastCheck = localStorage.getItem('ms_objectif_date');

    // Initialiser l'objectif du jour si nouveau jour
    if (lastCheck !== today) {
        localStorage.setItem('ms_objectif_date', today);
        localStorage.setItem('ms_objectif_done', '0');
        // Notifier via toast discret
        setTimeout(function() {
            showObjectifToast();
        }, 1000);
    }
}

function showObjectifToast() {
    var done = parseInt(localStorage.getItem('ms_objectif_done')||'0');
    var goal = 3;
    if (done >= goal) return;

    var toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%) translateY(20px);z-index:9999;background:linear-gradient(135deg,#1a0a2e,#2d1b69);border:1px solid #a855f744;border-radius:16px;padding:12px 20px;display:flex;align-items:center;gap:10px;opacity:0;transition:all 0.4s cubic-bezier(0.34,1.56,0.64,1);box-shadow:0 8px 30px #8a2be244;min-width:260px;';
    toast.innerHTML =
        '<div style="font-size:1.2rem;">🎯</div>' +
        '<div>' +
        '<div style="font-size:0.78rem;font-weight:900;color:#fff;">Objectif du jour</div>' +
        '<div style="font-size:0.68rem;color:#a855f7;">Écoute ' + goal + ' cours · Gagne 50 🪙</div>' +
        '<div style="margin-top:6px;width:160px;height:4px;background:#ffffff15;border-radius:2px;overflow:hidden;">' +
        '<div style="height:100%;width:' + Math.round(done/goal*100) + '%;background:linear-gradient(90deg,#8a2be2,#a855f7);border-radius:2px;"></div>' +
        '</div>' +
        '<div style="font-size:0.6rem;color:#555;margin-top:3px;">' + done + ' / ' + goal + ' cours</div>' +
        '</div>';

    document.body.appendChild(toast);
    setTimeout(function() {
        toast.style.opacity = '1';
        toast.style.transform = 'translateX(-50%) translateY(0)';
    }, 50);
    setTimeout(function() {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(-50%) translateY(20px)';
        setTimeout(function() { toast.remove(); }, 400);
    }, 4000);
}

function updateDailyObjectif() {
    var today = new Date().toDateString();
    if (localStorage.getItem('ms_objectif_date') !== today) return;
    var done = parseInt(localStorage.getItem('ms_objectif_done')||'0') + 1;
    localStorage.setItem('ms_objectif_done', done.toString());
    var goal = 3;
    if (done === goal) {
        // Donner la récompense
        var coins = parseInt(localStorage.getItem('ms_coins')||'0') + 50;
        localStorage.setItem('ms_coins', coins.toString());
        // Toast de victoire
        var toast = document.createElement('div');
        toast.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%) translateY(20px);z-index:9999;background:linear-gradient(135deg,#1a1000,#2a2000);border:1px solid #ffc10766;border-radius:16px;padding:14px 24px;text-align:center;opacity:0;transition:all 0.4s cubic-bezier(0.34,1.56,0.64,1);box-shadow:0 8px 30px #ffc10744;';
        toast.innerHTML = '<div style="font-size:1.5rem;margin-bottom:4px;">🏆</div><div style="font-size:0.82rem;font-weight:900;color:#ffc107;">Objectif du jour atteint !</div><div style="font-size:0.7rem;color:#888;margin-top:2px;">+50 🪙 pièces ajoutées</div>';
        document.body.appendChild(toast);
        setTimeout(function() { toast.style.opacity='1'; toast.style.transform='translateX(-50%) translateY(0)'; }, 50);
        setTimeout(function() { toast.style.opacity='0'; setTimeout(function(){toast.remove();},400); }, 3500);
    }
}

function showSplash(onDone) {
    const splash = document.createElement('div');
    splash.id = 'splash-screen';
    splash.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;width:100vw;height:100vh;z-index:99999;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:Montserrat,sans-serif;overflow:hidden;';
    // Force exact screen height via JS (contourne les barres Android)
    splash.style.height = window.innerHeight + 'px';
    window.addEventListener('resize', function _splashResize(){ splash.style.height = window.innerHeight + 'px'; window.removeEventListener('resize', _splashResize); });

    splash.innerHTML = `
        <style>
            @keyframes splashFadeOut { from{opacity:1;transform:scale(1);} to{opacity:0;transform:scale(1.05);} }

            /* Particules */
            @keyframes floatUp {
                0%   { opacity:0; transform:translateY(0) scale(0); }
                20%  { opacity:1; }
                100% { opacity:0; transform:translateY(-120px) scale(1.5); }
            }

            /* Ring tournant */
            @keyframes spinRing {
                from { transform:rotate(0deg); }
                to   { transform:rotate(360deg); }
            }
            @keyframes spinRingRev {
                from { transform:rotate(0deg); }
                to   { transform:rotate(-360deg); }
            }

            /* Logo */
            @keyframes logoSlam {
                0%   { opacity:0; transform:scale(2) translateY(-30px); filter:blur(20px); }
                50%  { opacity:1; transform:scale(0.95) translateY(2px); filter:blur(0); }
                70%  { transform:scale(1.03); }
                100% { transform:scale(1); }
            }

            /* Tagline */
            @keyframes tagSlide {
                0%   { opacity:0; letter-spacing:8px; }
                100% { opacity:1; letter-spacing:3px; }
            }

            /* Dot pulse */
            @keyframes dotPulse {
                0%,100% { transform:scale(1); text-shadow:0 0 10px #a855f7; }
                50%     { transform:scale(1.4); text-shadow:0 0 30px #a855f7, 0 0 60px #8a2be2; }
            }

            /* Glow pulse sur le logo */
            @keyframes glowPulse {
                0%,100% { text-shadow:0 0 20px rgba(138,43,226,0.4); }
                50%     { text-shadow:0 0 60px rgba(168,85,247,0.9), 0 0 100px rgba(138,43,226,0.5); }
            }

            /* Bars EQ */
            @keyframes eqBounce {
                0%,100% { transform:scaleY(0.3); }
                50%     { transform:scaleY(1); }
            }

            /* Progress shimmer */
            @keyframes shimmer {
                0%   { background-position:-200% center; }
                100% { background-position:200% center; }
            }

            #sp-logo {
                animation: logoSlam 0.7s cubic-bezier(.22,.68,0,1.2) 0.3s both,
                           glowPulse 2s ease-in-out 1.2s infinite;
            }
            #sp-dot { animation: dotPulse 1.2s ease-in-out 1s infinite; display:inline-block; }
            #sp-sub { opacity:0; animation: tagSlide 0.5s ease 0.9s forwards; }
            #sp-ring1 { animation: spinRing 3s linear infinite; }
            #sp-ring2 { animation: spinRingRev 2s linear infinite; }
        </style>

        <!-- FOND GLITCH/GRAIN -->
        <div style="position:absolute;inset:0;background:radial-gradient(ellipse at 50% 0%,#2a0a4a 0%,#000 60%);"></div>
        <div style="position:absolute;inset:0;background:radial-gradient(ellipse at 50% 100%,#0a0020 0%,transparent 60%);"></div>

        <!-- LIGNES DE SCAN -->
        <div style="position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(138,43,226,0.03) 3px,rgba(138,43,226,0.03) 4px);pointer-events:none;"></div>

        <!-- PARTICULES -->
        <div id="sp-particles" style="position:absolute;inset:0;pointer-events:none;"></div>

        <!-- RINGS ROTATIFS -->
        <div style="position:absolute;width:min(500px,92vw);height:min(500px,92vw);opacity:0.18;">
            <div id="sp-ring1" style="position:absolute;inset:0;border:1px solid #a855f7;border-radius:50%;border-top-color:transparent;border-bottom-color:transparent;"></div>
            <div id="sp-ring2" style="position:absolute;inset:20px;border:1px solid #8a2be2;border-radius:50%;border-left-color:transparent;border-right-color:transparent;"></div>
            <div style="position:absolute;inset:40px;border:1px dashed #6a1b9a;border-radius:50%;opacity:0.5;"></div>
        </div>

        <!-- EQUALIZER -->
        <div id="sp-eq" style="display:flex;align-items:flex-end;gap:5px;height:80px;margin-bottom:clamp(16px,4vw,32px);position:relative;">
            ${[28,44,18,56,34,64,24,52,16,42,60,22,48,30,54].map((h,i) =>
                `<div class="sp-bar" data-base="${h}" style="width:4px;height:${h}px;border-radius:4px;background:linear-gradient(to top,#8a2be2,#c084fc,#fff);transform-origin:bottom;transition:height 0.08s ease;box-shadow:0 0 8px #a855f755;"></div>`
            ).join('')}
        </div>

        <!-- LOGO -->
        <div id="sp-logo" style="font-size:clamp(2.8rem,11vw,4.2rem);font-weight:900;color:#fff;letter-spacing:-2px;line-height:1;margin-bottom:14px;position:relative;">
            Music<span style="color:#a855f7;">School</span><span id="sp-dot" style="color:#a855f7;">.</span>
        </div>

        <!-- TAGLINE -->
        <div id="sp-sub" style="font-size:0.85rem;font-weight:800;letter-spacing:2px;color:#a855f7;margin-bottom:clamp(24px,6vw,60px);">
            La sagesse en mouvement
        </div>

        <!-- BARRE PROGRESS -->
        <div style="position:relative;width:min(260px,78vw);">
            <div style="width:100%;height:2px;background:#111;border-radius:2px;overflow:hidden;">
                <div id="sp-bar-prog" style="height:100%;width:0%;background:linear-gradient(90deg,#6a0dad,#a855f7,#e879f9,#a855f7);background-size:200% 100%;animation:shimmer 1.5s linear infinite;border-radius:2px;transition:width 0.05s linear;"></div>
            </div>
            <div id="sp-pct" style="text-align:center;font-size:0.58rem;color:#444;margin-top:6px;font-weight:700;letter-spacing:2px;">0%</div>
        </div>
    `;

    document.body.appendChild(splash);

    // ── Force plein écran au démarrage ──
    (function() {
        var el = document.documentElement;
        var fn = el.requestFullscreen || el.webkitRequestFullscreen || el.mozRequestFullScreen || el.msRequestFullscreen;
        if (fn) { try { var _p = fn.call(el); if (_p && _p.catch) _p.catch(function(){}); } catch(e) {} }
    })();

    // Générer des particules flottantes
    const particlesEl = document.getElementById('sp-particles');
    for (let i = 0; i < 20; i++) {
        const p = document.createElement('div');
        const size = 2 + Math.random() * 4;
        const x = 10 + Math.random() * 80;
        const delay = Math.random() * 3;
        const dur = 2 + Math.random() * 2;
        p.style.cssText = `position:absolute;left:${x}%;bottom:${10 + Math.random() * 30}%;width:${size}px;height:${size}px;border-radius:50%;background:${Math.random()>0.5?'#a855f7':'#38bdf8'};animation:floatUp ${dur}s ease-in ${delay}s infinite;`;
        particlesEl.appendChild(p);
    }

    // ── EQ + Progress via requestAnimationFrame ────────────────
    // rAF est garanti de tourner avant chaque repaint, même sur Android
    // WebCode avec un gros fichier JS — contrairement à setInterval qui
    // se bloque quand le main thread est surchargé.
    const eqBars = splash.querySelectorAll('.sp-bar');
    const bar   = document.getElementById('sp-bar-prog');
    const pctEl = document.getElementById('sp-pct');

    let pct       = 0;
    let lastTime  = 0;
    let eqTimer   = 0;
    let _done     = false;

    function _exitSplash() {
        if (_done) return;
        _done = true;
        if (bar) bar.style.width = '100%';
        if (pctEl) pctEl.textContent = '100%';

        // Fade-out via transition CSS (plus fiable que animation sur Android)
        splash.style.transition = 'opacity 0.45s ease';
        splash.style.opacity = '0';

        // Lancer onDone() via transitionend + fallback 600ms
        let _launched = false;
        function _launch() {
            if (_launched) return;
            _launched = true;
            if (splash.parentNode) splash.parentNode.removeChild(splash);
            try { onDone(); } catch(e) { console.error('[Splash] onDone error:', e); }
        }
        splash.addEventListener('transitionend', _launch, { once: true });
        setTimeout(_launch, 600); // fallback si transitionend ne se déclenche pas
    }

    function _rafLoop(ts) {
        if (_done) return;
        const delta = ts - lastTime;

        // Progression rapide : ~3% tous les 40ms → 100% en ~1.3s max
        // On ralentit artificiellement entre 70-90% pour l'effet visuel
        if (delta >= 40) {
            lastTime = ts;
            let step = pct < 70 ? (2.5 + Math.random() * 2) : (0.8 + Math.random() * 0.8);
            pct += step;
            if (pct >= 100) { _exitSplash(); return; }
            if (bar) bar.style.width = pct + '%';
            if (pctEl) pctEl.textContent = Math.floor(pct) + '%';
        }

        // EQ animation toutes les ~90ms
        eqTimer += delta || 16;
        if (eqTimer >= 90) {
            eqTimer = 0;
            eqBars.forEach(b => {
                const base = parseInt(b.dataset.base);
                b.style.height = Math.max(4, base * (0.2 + Math.random())) + 'px';
            });
        }

        requestAnimationFrame(_rafLoop);
    }

    requestAnimationFrame(_rafLoop);

    // ⚡ Filet de sécurité — déclenche onDone après 2.5s max
    // (réduit depuis 4s car le splash ne doit jamais bloquer l'app)
    setTimeout(() => {
        _exitSplash();
        setTimeout(() => {
            const s = document.getElementById('splash-screen');
            if (s) s.remove();
            try { if (!document.getElementById('main-grid')?.innerHTML) onDone(); } catch(e) {}
        }, 600);
    }, 2500);
}

