function getSprintQuestions() {
    const all = [
        { q: 'Qui a dit "Je pense, donc je suis" ?', choices: ['Kant', 'Descartes', 'Platon', 'Spinoza'], answer: 1 },
        { q: 'Qui est le père de la psychanalyse ?', choices: ['Jung', 'Adler', 'Freud', 'Lacan'], answer: 2 },
        { q: 'Quel philosophe a écrit "Le Capital" ?', choices: ['Engels', 'Lénine', 'Marx', 'Proudhon'], answer: 2 },
        { q: '"Deviens ce que tu es" — qui ?', choices: ['Schopenhauer', 'Hegel', 'Nietzsche', 'Kant'], answer: 2 },
        { q: 'Sartre appartient à quel courant ?', choices: ['Stoïcisme', 'Existentialisme', 'Idéalisme', 'Empirisme'], answer: 1 },
        { q: 'Camus a écrit quel roman en 1942 ?', choices: ['La Nausée', "L'Étranger", 'La Chute', 'Le Mythe'], answer: 1 },
        { q: 'Qui a écrit "Les Misérables" ?', choices: ['Flaubert', 'Zola', 'Victor Hugo', 'Balzac'], answer: 2 },
        { q: '"Germinal" est de quel auteur ?', choices: ['Maupassant', 'Hugo', 'Flaubert', 'Zola'], answer: 3 },
        { q: 'Baudelaire a écrit quel recueil ?', choices: ['Les Illuminations', 'Les Fleurs du Mal', 'Alcools', 'Calligrammes'], answer: 1 },
        { q: '"Madame Bovary" est un roman de ?', choices: ['Stendhal', 'Balzac', 'Flaubert', 'Zola'], answer: 2 },
        { q: 'En quelle année tombe le mur de Berlin ?', choices: ['1985', '1991', '1989', '1987'], answer: 2 },
        { q: 'La Révolution française commence en ?', choices: ['1776', '1799', '1789', '1815'], answer: 2 },
        { q: 'Quelle est la capitale du Brésil ?', choices: ['Rio', 'São Paulo', 'Brasilia', 'Salvador'], answer: 2 },
        { q: "Quelle est la capitale de l'Australie ?", choices: ['Sydney', 'Melbourne', 'Perth', 'Canberra'], answer: 3 },
        { q: 'Qui a fondé l\'Académie d\'Athènes ?', choices: ['Socrate', 'Aristote', 'Platon', 'Épicure'], answer: 2 },
    ];
    return all.sort(() => Math.random() - 0.5).slice(0, 10);
}

function getFavorites() {
    // Synchronise favoris avec likedLessons
    return JSON.parse(localStorage.getItem('likedLessons')) || [];
}

function showFavorites() {
    _saveScroll(_scrollKey('profile', '')); window.scrollTo({ top: 0, behavior: 'instant' }); _pushNav('favorites'); currentLevel = 'favorites';
    updateHeaderBtns();
    sectionTitle.innerText = 'MES FAVORIS';
    const favIds = getFavorites();
    const favLessons = lessonsData.filter(l => favIds.includes(l.id));

    if (favLessons.length === 0) {
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1; text-align:center; padding:60px 20px;">
                <div style="font-size:3rem; margin-bottom:16px;">❤️</div>
                <div style="font-size:0.9rem; font-weight:800; color:#fff; margin-bottom:8px;">Aucun favori pour l'instant</div>
                <div style="font-size:0.75rem; color:#555;">Appuie sur le ❤️ dans un cours pour le sauvegarder ici</div>
            </div>`;
        return;
    }

    mainGrid.innerHTML = `
        <div style="grid-column:1/-1; text-align:center; padding:4px 0 12px;">
            <div style="font-size:0.6rem; color:#444; letter-spacing:2.5px; font-weight:700;">${favLessons.length} COURS SAUVEGARDÉS</div>
        </div>`;

    favLessons.forEach(lesson => {
        const div = document.createElement('div');
        div.className = 'track-card';
        div.style.cssText += `border-color: rgba(231,76,60,0.25); transition: transform 0.15s ease;`;
        div.onmouseenter = () => div.style.transform = 'translateX(4px)';
        div.onmouseleave = () => div.style.transform = 'translateX(0)';
        div.innerHTML = `
            <div class="track-info">
                <h3 style="color:#fff;">${lesson.title}</h3>
                <div style="display:flex;gap:6px;align-items:center;margin-top:3px;">
                    <span style="font-size:0.65rem;color:#e74c3c;font-weight:bold;">❤️ ${lesson.subject.toUpperCase()}</span>
                    <span style="font-size:0.65rem;color:#555;">• ${lesson.category}</span>
                </div>
            </div>
            <div class="play-btn-circle" style="background:linear-gradient(135deg,#8a2be2,#6a0dad);">
                <i class="fas fa-play"></i>
            </div>`;
        div.onclick = () => {
            currentSubject = lesson.subject;
            currentCategory = lesson.category;
            // ✅ Playlist = uniquement les favoris, dans l'ordre affiché
            currentPlaylist = favLessons;
            viewingIndex = currentPlaylist.findIndex(l => l.id === lesson.id);
            if (viewingIndex === -1) viewingIndex = 0;
            currentlyPlayingId = lesson.id;
            resetListenTracker(lesson.id);
            audio.src = lesson.audio;
            audio.play();
            openPlayer(viewingIndex);
        };
        // Surligner si en cours de lecture
        if (currentlyPlayingId && lesson.id === currentlyPlayingId) {
            div.style.background = 'rgba(138,43,226,0.12)';
            div.style.borderColor = 'rgba(138,43,226,0.5)';
            div.style.boxShadow = '0 0 16px rgba(138,43,226,0.15)';
        }
        mainGrid.appendChild(div);
    });
}

