function getSubjectData(key, chapterId) {
    const sess = getGameSession();
    if (!sess) return [];
    const data = GAME_DATA[sess.subjectId];
    if (!data) return [];
    const arr = data[key] || [];
    const chapter = chapterId || sess.chapterId || 'all';
    if (chapter === 'all') return arr;
    return arr.filter(item => !item.chapter || item.chapter === chapter);
}

// ─── Veille d\'examen : filtre les questions ratées ───
function getExamModeQuestions(subjectId, key) {
    const wrong = getWrongAnswers(subjectId);
    const data = GAME_DATA[subjectId];
    if (!data) return [];
    const all = data[key] || [];
    const wrongQs = all.filter(q => wrong[q.q || q.word || q.front]);
    // Si pas assez de questions ratées, compléter avec des questions aléatoires
    if (wrongQs.length < 5) {
        const rest = all.filter(q => !wrong[q.q || q.word || q.front])
                        .sort(() => Math.random() - 0.5)
                        .slice(0, 10 - wrongQs.length);
        return [...wrongQs, ...rest];
    }
    return wrongQs.sort((a, b) => {
        const ka = a.q || a.word || a.front;
        const kb = b.q || b.word || b.front;
        return (wrong[kb] || 0) - (wrong[ka] || 0);
    });
}

