// ═══════════════════════════════════════════════════

function cleanupGames() {
    if (window._activeGameTimer) { clearInterval(window._activeGameTimer); window._activeGameTimer = null; }
    window._flipCard = null;
    window._rateCard = null;
    window._guessLetter = null;
    window._wordDone = false;
    window._gameGeneration = (window._gameGeneration || 0) + 1;
}

function startGame(type) {
    cleanupGames();
    const sess = getGameSession();
    if (!sess) { showMiniGames(); return; }
    touchGameSession();
    if (type === 'match') startMatchGame();
    else if (type === 'sprint') startSprintGame();
    else if (type === 'word') startWordGame();
    else if (type === 'flash') startFlashGame();
    else if (type === 'truefalse') startTrueFalseGame();
    else if (type === 'chrono') startChronoGame();
}

function startMatchGame() {
    currentLevel = 'game-match';
    updateHeaderBtns();
    const sess = getGameSession();
    const subj = GAME_SUBJECTS.find(s => s.id === sess?.subjectId) || GAME_SUBJECTS[0];
    sectionTitle.innerText = 'RELIER 🔗';
    const sets = getSubjectData('match');
    const pairs = sets.sort(() => Math.random() - 0.5).slice(0, Math.min(7, sets.length));
    let errors = 0, matched = 0, selected = null;
    const lefts = pairs.map((p, i) => ({ id: i, text: p.left, paired: false })).sort(() => Math.random() - 0.5);
    const rights = pairs.map((p, i) => ({ id: i, text: p.right, paired: false })).sort(() => Math.random() - 0.5);

    function render() {
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1; display:flex; justify-content:space-between; align-items:center; padding:0 0 12px;">
                <div style="font-size:0.65rem; color:${subj.color}; font-weight:700;">${subj.emoji} ${subj.label}</div>
                <div style="font-size:0.75rem; color:#e74c3c; font-weight:700;">${errors} ❌</div>
            </div>
            <div style="grid-column:1/-1; display:grid; grid-template-columns:1fr 1fr; gap:10px;">
                <div id="col-left" style="display:flex;flex-direction:column;gap:8px;"></div>
                <div id="col-right" style="display:flex;flex-direction:column;gap:8px;"></div>
            </div>`;
        const cl = document.getElementById('col-left');
        const cr = document.getElementById('col-right');
        lefts.forEach(item => {
            const d = document.createElement('div');
            const isSel = selected && selected.side === 'left' && selected.id === item.id;
            d.style.cssText = `padding:10px 8px;border-radius:12px;font-size:0.68rem;font-weight:700;cursor:${item.paired?'default':'pointer'};text-align:center;border:1.5px solid ${item.paired?'#2ecc7144':isSel?subj.color:'#333'};background:${item.paired?'rgba(46,204,113,0.1)':isSel?subj.color+'22':'rgba(255,255,255,0.03)'};color:${item.paired?'#2ecc71':'#fff'};`;
            d.innerText = item.paired ? '✓' : item.text;
            if (!item.paired) d.onclick = () => pick('left', item.id);
            cl.appendChild(d);
        });
        rights.forEach(item => {
            const d = document.createElement('div');
            const isSel = selected && selected.side === 'right' && selected.id === item.id;
            d.style.cssText = `padding:10px 8px;border-radius:12px;font-size:0.68rem;font-weight:700;cursor:${item.paired?'default':'pointer'};text-align:center;border:1.5px solid ${item.paired?'#2ecc7144':isSel?subj.color:'#333'};background:${item.paired?'rgba(46,204,113,0.1)':isSel?subj.color+'22':'rgba(255,255,255,0.03)'};color:${item.paired?'#2ecc71':'#fff'};`;
            d.innerText = item.paired ? '✓' : item.text;
            if (!item.paired) d.onclick = () => pick('right', item.id);
            cr.appendChild(d);
        });
    }
    function pick(side, id) {
        if (!selected) { selected = { side, id }; render(); return; }
        if (selected.side === side) { selected = { side, id }; render(); return; }
        const leftId = side === 'right' ? selected.id : id;
        const rightId = side === 'right' ? id : selected.id;
        if (leftId === rightId) {
            lefts.find(l => l.id === leftId).paired = true;
            rights.find(r => r.id === rightId).paired = true;
            matched++; selected = null; render();
            if (matched === pairs.length) {
                const coins = Math.max(5, 20 - errors * 3);
                setTimeout(() => { awardCoins(coins, 'Relier terminé !'); awardXP(10, 'Mini-jeu !'); showGameResult('🔗 RELIER', matched, pairs.length, errors, coins, 'match'); }, 400);
            }
        } else { errors++; selected = null; render(); }
    }
    render();
}

function startSprintGame(examMode) {
    currentLevel = 'game-sprint';
    updateHeaderBtns();
    const sess = getGameSession();
    const subj = GAME_SUBJECTS.find(s => s.id === sess?.subjectId) || GAME_SUBJECTS[0];
    sectionTitle.innerText = 'SPRINT ⚡';
    const pool = examMode
        ? getExamModeQuestions(subj.id, 'sprint')
        : getSubjectData('sprint');
    const questions = pool.sort(() => Math.random() - 0.5).slice(0, 10);
    let qIndex = 0, score = 0, timer = null, timeLeft = 15;

    function showQ() {
        if (qIndex >= questions.length) {
            clearInterval(timer);
            const coins = Math.round((score / questions.length) * 30);
            awardCoins(coins, 'Sprint terminé !');
            awardXP(score * 2, 'Sprint !');
            showGameResult('⚡ SPRINT', score, questions.length, 0, coins, 'sprint');
            return;
        }
        const q = questions[qIndex]; timeLeft = 15;
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
                    <div style="font-size:0.65rem;color:${subj.color};font-weight:700;">${subj.emoji} ${subj.label}</div>
                    <div id="spr-timer" style="font-size:1rem;font-weight:900;color:#e67e22;">⏱ ${timeLeft}s</div>
                    <div style="font-size:0.72rem;font-weight:700;"><span style="color:#2ecc71;">✓ ${score}</span> · <span style="color:#e74c3c;">✗ ${qIndex - score}</span> · <span style="color:#888;">${qIndex+1}/${questions.length}</span></div>
                </div>
                <div style="background:rgba(255,255,255,0.04);border-radius:16px;padding:20px;margin-bottom:14px;border:1px solid #222;">
                    <div style="font-size:0.88rem;font-weight:800;color:#fff;line-height:1.4;">${q.q}</div>
                </div>
                <div style="display:flex;gap:8px;justify-content:center;margin-bottom:14px;" id="boost-bar">
                    ${getBoosts().hint > 0 ? `<div onclick="useSprintBoost('hint',${qIndex})" style="font-size:0.7rem;padding:6px 14px;border-radius:20px;background:rgba(241,196,15,0.1);border:1px solid #f1c40f44;color:#f1c40f;cursor:pointer;">💡 Indice</div>` : ''}
                    ${getBoosts().skip > 0 ? `<div onclick="useSprintBoost('skip',${qIndex})" style="font-size:0.7rem;padding:6px 14px;border-radius:20px;background:rgba(52,152,219,0.1);border:1px solid #3498db44;color:#3498db;cursor:pointer;">⏭️ Passer</div>` : ''}
                    ${getBoosts().time > 0 ? `<div onclick="useSprintBoost('time',${qIndex})" style="font-size:0.7rem;padding:6px 14px;border-radius:20px;background:rgba(46,204,113,0.1);border:1px solid #2ecc7144;color:#2ecc71;cursor:pointer;">⏱️ +10s</div>` : ''}
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;" id="choices"></div>
            </div>`;
        const grid = document.getElementById('choices');
        q.choices.forEach((c, i) => {
            const btn = document.createElement('div');
            btn.style.cssText = `padding:14px 10px;border-radius:14px;font-size:0.76rem;font-weight:700;cursor:pointer;text-align:center;border:1.5px solid #333;background:rgba(255,255,255,0.03);color:#fff;`;
            btn.innerText = c;
            btn.onclick = () => answer(i);
            grid.appendChild(btn);
        });
        clearInterval(timer);
        timer = setInterval(() => {
            timeLeft--;
            const el = document.getElementById('spr-timer');
            if (el) el.innerText = `⏱ ${timeLeft}s`, el.style.color = timeLeft <= 5 ? '#e74c3c' : '#e67e22';
            if (timeLeft <= 0) {
                clearInterval(timer);
                window._activeGameTimer = null;
                recordWrongAnswer(subj.id, q.q);
                qIndex++; showQ();
            }
        }, 1000);
        window._activeGameTimer = timer;
    }

    window.useSprintBoost = (type, qi) => {
        if (qi !== qIndex) return;
        if (type === 'hint') {
            if (!useBoost('hint')) return;
            const q = questions[qIndex];
            // Reveal one wrong answer
            const wrongIdx = q.choices.findIndex((_, i) => i !== q.answer);
            const btns = document.querySelectorAll('#choices div');
            if (btns[wrongIdx]) { btns[wrongIdx].style.opacity = '0.3'; btns[wrongIdx].onclick = null; }
        } else if (type === 'skip') {
            if (!useBoost('skip')) return;
            clearInterval(timer); qIndex++; showQ();
        } else if (type === 'time') {
            if (!useBoost('time')) return;
            timeLeft += 10;
            const el = document.getElementById('spr-timer');
            if (el) el.innerText = `⏱ ${timeLeft}s`;
        }
        // Refresh boost bar
        const bb = document.getElementById('boost-bar');
        const boosts = getBoosts();
        if (bb) bb.innerHTML = `
            ${boosts.hint > 0 ? `<div onclick="useSprintBoost('hint',${qIndex})" style="font-size:0.7rem;padding:6px 14px;border-radius:20px;background:rgba(241,196,15,0.1);border:1px solid #f1c40f44;color:#f1c40f;cursor:pointer;">💡 Indice ×${boosts.hint}</div>` : ''}
            ${boosts.skip > 0 ? `<div onclick="useSprintBoost('skip',${qIndex})" style="font-size:0.7rem;padding:6px 14px;border-radius:20px;background:rgba(52,152,219,0.1);border:1px solid #3498db44;color:#3498db;cursor:pointer;">⏭️ Passer ×${boosts.skip}</div>` : ''}
            ${boosts.time > 0 ? `<div onclick="useSprintBoost('time',${qIndex})" style="font-size:0.7rem;padding:6px 14px;border-radius:20px;background:rgba(46,204,113,0.1);border:1px solid #2ecc7144;color:#2ecc71;cursor:pointer;">⏱️ +10s ×${boosts.time}</div>` : ''}`;
    };

    function answer(i) {
        clearInterval(timer);
        window._activeGameTimer = null;
        const q = questions[qIndex];
        const correct = i === q.answer;
        if (correct) { score++; playSound('correct'); } else { recordWrongAnswer(subj.id, q.q); playSound('wrong'); }
        document.querySelectorAll('#choices div').forEach((btn, idx) => {
            btn.onclick = null;
            btn.style.transition = 'all 0.2s';
            if (idx === q.answer) { btn.style.background = 'rgba(46,204,113,0.25)'; btn.style.borderColor = '#2ecc71'; btn.style.color = '#2ecc71'; }
            if (idx === i && i !== q.answer) { btn.style.background = 'rgba(231,76,60,0.25)'; btn.style.borderColor = '#e74c3c'; btn.style.color = '#e74c3c'; }
        });
        const _gen = window._gameGeneration;
        setTimeout(() => { if (window._gameGeneration === _gen) { qIndex++; showQ(); } }, 900);
    }
    showQ();
}

function startWordGame() {
    currentLevel = 'game-word';
    updateHeaderBtns();
    const sess = getGameSession();
    const subj = GAME_SUBJECTS.find(s => s.id === sess?.subjectId) || GAME_SUBJECTS[0];
    sectionTitle.innerText = 'MOT CACHÉ 🧩';
    const words = getSubjectData('words');
    const pick = words[Math.floor(Math.random() * words.length)];
    const letters = pick.word.split('');
    let guessed = [], errors = 0;
    const maxErrors = 6;
    const alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
    window._wordDone = false;

    function render() {
        const won = letters.every(l => guessed.includes(l));
        const lost = errors >= maxErrors;
        const display = letters.map(l => guessed.includes(l) ? l : '_').join(' ');
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;">
                <div style="font-size:0.65rem;color:${subj.color};font-weight:700;margin-bottom:12px;">${subj.emoji} ${subj.label}</div>
                <div style="font-size:0.78rem;color:#666;margin-bottom:20px;font-style:italic;">"${pick.hint}"</div>
                <div style="font-size:1.5rem;font-weight:900;letter-spacing:8px;color:#fff;margin-bottom:8px;font-family:monospace;">${display}</div>
                <div style="font-size:0.7rem;color:#555;margin-bottom:20px;">${letters.length} lettres</div>
                <div style="display:flex;justify-content:center;gap:6px;margin-bottom:20px;">
                    ${Array(maxErrors).fill(0).map((_,i)=>`<div style="width:10px;height:10px;border-radius:50%;background:${i<errors?'#e74c3c':'#333'};"></div>`).join('')}
                </div>
                ${won ? '<div style="font-size:1.2rem;font-weight:900;color:#2ecc71;margin-bottom:16px;">🎉 Bravo !</div>' : ''}
                ${lost ? `<div style="font-size:0.9rem;font-weight:900;color:#e74c3c;margin-bottom:8px;">❌ Perdu !</div><div style="font-size:0.8rem;color:#888;margin-bottom:16px;">Le mot : <b style="color:#fff;">${pick.word}</b></div>` : ''}
                ${!won && !lost ? `<div style="display:flex;flex-wrap:wrap;justify-content:center;gap:5px;max-width:340px;margin:0 auto;">
                    ${alpha.map(l => `<div onclick="window._guessLetter('${l}')" style="width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:0.75rem;font-weight:800;cursor:${guessed.includes(l)?'default':'pointer'};border:1.5px solid ${guessed.includes(l)?(letters.includes(l)?'#2ecc71':'#e74c3c'):'#333'};background:${guessed.includes(l)?(letters.includes(l)?'rgba(46,204,113,0.15)':'rgba(231,76,60,0.1)'):'rgba(255,255,255,0.03)'};color:${guessed.includes(l)?(letters.includes(l)?'#2ecc71':'#555'):'#fff'};">${l}</div>`).join('')}
                </div>` : ''}
                ${won || lost ? `<div onclick="startGame('word')" style="display:inline-block;margin-top:16px;background:linear-gradient(135deg,var(--neon),var(--neon-light));color:#fff;padding:12px 28px;border-radius:14px;font-weight:900;font-size:0.85rem;cursor:pointer;">Rejouer</div>` : ''}
            </div>`;
        if (won && !window._wordDone) {
            window._wordDone = true;
            const coins = Math.max(3, 15 - errors * 2);
            const _wgen = window._gameGeneration; setTimeout(() => { if (window._gameGeneration === _wgen) { awardCoins(coins, 'Mot caché !'); awardXP(8, 'Mini-jeu !'); } }, 300);
        }
        if (lost && !window._wordDone) {
            window._wordDone = true;
            recordWrongAnswer(subj.id, pick.word);
        }
    }
    window._guessLetter = (l) => {
        if (guessed.includes(l) || errors >= maxErrors || letters.every(lt => guessed.includes(lt))) return;
        guessed.push(l);
        if (!letters.includes(l)) { errors++; playSound('wrong'); } else { playSound('correct'); }
        render();
    };
    render();
}

function startFlashGame(examMode) {
    currentLevel = 'game-flash';
    updateHeaderBtns();
    const sess = getGameSession();
    const subj = GAME_SUBJECTS.find(s => s.id === sess?.subjectId) || GAME_SUBJECTS[0];
    sectionTitle.innerText = 'FLASHCARDS 🃏';
    const pool = examMode
        ? getExamModeQuestions(subj.id, 'flash')
        : getSubjectData('flash');
    const cards = pool.sort(() => Math.random() - 0.5);
    let idx = 0, flipped = false, score = 0, hintShown = false;

    function getCardHint(card) {
        const text = (card.front + ' ' + (card.back || '')).toLowerCase();
        for (const p of philosophersData) {
            const names = p.name.toLowerCase().split(/[\s\-]+/);
            for (const n of names) {
                if (n.length > 3 && text.includes(n)) return { type: 'philo', data: p };
            }
        }
        if (typeof frenchAuthorsData !== 'undefined') {
            for (const a of frenchAuthorsData) {
                const names = a.name.toLowerCase().split(/[\s\-]+/);
                for (const n of names) {
                    if (n.length > 3 && text.includes(n)) return { type: 'auteur', data: a };
                }
            }
        }
        return null;
    }

    function showCard() {
        if (idx >= cards.length) {
            const coins = Math.round((score / cards.length) * 10);
            awardCoins(coins, 'Flashcards terminées !');
            awardXP(score * 3, 'Flashcards !');
            showGameResult('🃏 FLASHCARDS', score, cards.length, 0, coins, 'flash');
            return;
        }
        const card = cards[idx];
        const hint = getCardHint(card);
        const hintBtnHtml = (!flipped && hint && !hintShown) ? `
            <div onclick="window._showFlashHint()" style="margin-top:14px;display:inline-block;padding:8px 20px;border-radius:12px;background:rgba(241,196,15,0.08);border:1px solid rgba(241,196,15,0.3);color:#f1c40f;font-size:0.72rem;font-weight:700;cursor:pointer;">
                💡 Qui est l'auteur ?
            </div>` : '';
        const hintBoxHtml = (!flipped && hint && hintShown) ? `
            <div style="margin-top:12px;background:rgba(255,255,255,0.03);border:1px solid #2a2a2a;border-radius:14px;padding:14px 16px;max-width:300px;margin-left:auto;margin-right:auto;text-align:left;">
                <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
                    ${hint.data.image ? `<img loading="lazy" src="${hint.data.image}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;object-position:top;border:1.5px solid ${hint.data.color||'#555'}44;flex-shrink:0;;will-change:transform;transform:translateZ(0);" onerror="_lessonImgError(this)">` : ''}
                    <div>
                        <div style="font-size:0.78rem;font-weight:800;color:#fff;">${hint.data.name}</div>
                        <div style="font-size:0.65rem;color:#666;margin-top:1px;">${hint.data.dates || hint.data.era || ''}</div>
                    </div>
                </div>
                <div style="font-size:0.7rem;color:#999;line-height:1.55;">${(hint.data.pensee || hint.data.quote || '').substring(0, 130)}…</div>
            </div>` : '';
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;">
                <div style="font-size:0.65rem;color:${subj.color};font-weight:700;margin-bottom:8px;">${subj.emoji} ${subj.label} · ${idx+1}/${cards.length}</div>
                <div style="font-size:0.7rem;color:#555;margin-bottom:20px;">${flipped ? 'RÉPONSE' : 'QUESTION — Tap pour retourner'}</div>
                <div onclick="window._flipCard()" style="min-height:160px;background:${flipped?'rgba(46,204,113,0.06)':'rgba(255,255,255,0.03)'};border:1.5px solid ${flipped?'#2ecc7144':'#333'};border-radius:20px;padding:28px 20px;cursor:pointer;display:flex;align-items:center;justify-content:center;margin-bottom:8px;transition:all 0.3s;">
                    <div style="font-size:0.88rem;font-weight:${flipped?'700':'800'};color:${flipped?'#2ecc71':'#fff'};line-height:1.5;text-align:center;">${flipped ? card.back : card.front}</div>
                </div>
                ${hintBtnHtml}
                ${hintBoxHtml}
                ${flipped ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:280px;margin:16px auto 0;">
                    <div onclick="window._rateCard(false)" style="padding:14px;border-radius:14px;background:rgba(231,76,60,0.1);border:1.5px solid #e74c3c44;color:#e74c3c;font-weight:900;font-size:0.82rem;cursor:pointer;text-align:center;">😕 Pas su</div>
                    <div onclick="window._rateCard(true)" style="padding:14px;border-radius:14px;background:rgba(46,204,113,0.1);border:1.5px solid #2ecc7144;color:#2ecc71;font-weight:900;font-size:0.82rem;cursor:pointer;text-align:center;">✅ Je savais</div>
                </div>` : ''}
            </div>`;
    }
    window._flipCard = () => { flipped = true; showCard(); };
    window._showFlashHint = () => { hintShown = true; showCard(); };
    window._rateCard = (knew) => {
        if (!knew) recordWrongAnswer(subj.id, cards[idx].front);
        if (knew) { score++; playSound('correct'); } else { playSound('wrong'); }
        idx++; flipped = false; hintShown = false; showCard();
    };
    showCard();
}

function showGameResult(title, score, total, errors, coins, gameType) {
    currentLevel = 'game-result';
    updateHeaderBtns();
    sectionTitle.innerText = 'RÉSULTAT';
    const sess = getGameSession();
    const subj = sess ? GAME_SUBJECTS.find(s => s.id === sess.subjectId) : null;
    const pct = Math.round((score/total)*100);
    const emoji = pct===100?'🏆':pct>=70?'🎉':pct>=40?'👍':'💪';
    const wrong = subj ? Object.keys(getWrongAnswers(subj.id)).length : 0;

    mainGrid.className = (mainGrid.className||'').replace(/page-transition[\w-]*/g,'').trim();
    mainGrid.style.opacity = '';
    mainGrid.style.transform = '';
    void mainGrid.offsetWidth;
    mainGrid.classList.add('page-transition-scale');

    // Barre de score animée
    const barColor = pct===100?'#f1c40f':pct>=70?'#2ecc71':pct>=40?'#e67e22':'#e74c3c';

    mainGrid.innerHTML = `
        <div style="grid-column:1/-1;text-align:center;padding:16px 0;">
            <div style="font-size:3.5rem;margin-bottom:10px;animation:popIn 0.4s cubic-bezier(0.22,1,0.36,1);">${emoji}</div>
            <div style="font-size:0.65rem;color:#555;letter-spacing:2px;font-weight:700;margin-bottom:6px;">${title}</div>
            ${subj ? `<div style="font-size:0.68rem;color:${subj.color};font-weight:700;margin-bottom:10px;">${subj.emoji} ${subj.label}</div>` : ''}

            <div style="margin:0 auto 18px;max-width:280px;">
                <div style="font-size:2.8rem;font-weight:900;color:#fff;margin-bottom:4px;">${score}<span style="font-size:1.4rem;color:#444;">/${total}</span></div>
                <div style="font-size:0.82rem;color:${barColor};font-weight:700;margin-bottom:12px;">${pct}%</div>
                <div style="background:#111;border-radius:99px;height:6px;overflow:hidden;">
                    <div id="result-bar" style="height:100%;width:0%;background:${barColor};border-radius:99px;transition:width 0.8s cubic-bezier(0.22,1,0.36,1);"></div>
                </div>
            </div>

            ${wrong > 0
                ? `<div style="font-size:0.72rem;color:#e74c3c;margin-bottom:14px;padding:8px 14px;background:rgba(231,76,60,0.08);border-radius:10px;display:inline-block;">⚠️ ${wrong} erreur(s) à retravailler</div>`
                : `<div style="font-size:0.72rem;color:#2ecc71;margin-bottom:14px;padding:8px 14px;background:rgba(46,204,113,0.08);border-radius:10px;display:inline-block;">✅ Parfait, aucune erreur !</div>`
            }

            <div style="background:rgba(241,196,15,0.07);border:1.5px solid rgba(241,196,15,0.2);border-radius:18px;padding:18px;margin-bottom:24px;display:inline-block;min-width:180px;animation:popIn 0.5s 0.2s cubic-bezier(0.22,1,0.36,1) both;">
                <div style="font-size:1.8rem;font-weight:900;color:#f1c40f;">🪙 +${coins}</div>
                <div style="font-size:0.65rem;color:#888;margin-top:4px;">pièces gagnées</div>
            </div>

            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:300px;margin:0 auto;">
                <div onclick="startGame('${gameType}')" class="ms-btn-press" style="padding:16px;border-radius:16px;background:var(--neon-glow);border:1.5px solid var(--neon);color:var(--neon);font-weight:900;font-size:0.85rem;cursor:pointer;text-align:center;animation:popIn 0.4s 0.35s both;">🔄 Rejouer</div>
                <div onclick="showMiniGames()" class="ms-btn-press" style="padding:16px;border-radius:16px;background:rgba(255,255,255,0.04);border:1.5px solid #333;color:#aaa;font-weight:900;font-size:0.85rem;cursor:pointer;text-align:center;animation:popIn 0.4s 0.45s both;">🎮 Jeux</div>
            </div>
            ${wrong > 0 ? `<div onclick="startExamMode()" class="ms-btn-press" style="margin-top:12px;padding:12px;border-radius:14px;background:rgba(231,76,60,0.08);border:1.5px solid #e74c3c44;color:#e74c3c;font-weight:900;font-size:0.78rem;cursor:pointer;text-align:center;max-width:300px;margin:12px auto 0;display:block;animation:popIn 0.4s 0.55s both;">🎯 Mode Veille d'exam</div>` : ''}
        </div>`;

    // Animer la barre après render
    setTimeout(() => {
        const bar = document.getElementById('result-bar');
        if (bar) bar.style.width = pct + '%';
    }, 100);

    // Confettis si score parfait
    if (pct === 100) { launchConfetti(); playSound('perfect'); } else if (pct >= 70) { playSound('coin'); }
}

function launchConfetti() {
    if (document.getElementById('confetti-canvas')) return;
    const canvas = document.createElement('canvas');
    canvas.id = 'confetti-canvas';
    canvas.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:9999;';
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const colors = ['#f1c40f','#2ecc71','#3498db','#e74c3c','#9b59b6','#1abc9c'];
    const particles = Array.from({length:80}, () => ({
        x: Math.random() * canvas.width,
        y: -10,
        size: Math.random()*6+4,
        color: colors[Math.floor(Math.random()*colors.length)],
        vx: (Math.random()-0.5)*3,
        vy: Math.random()*3+2,
        rot: Math.random()*360,
        vrot: (Math.random()-0.5)*8
    }));
    let frame = 0;
    function draw() {
        ctx.clearRect(0,0,canvas.width,canvas.height);
        particles.forEach(p => {
            p.x += p.vx; p.y += p.vy; p.rot += p.vrot;
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rot * Math.PI/180);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = Math.max(0, 1 - frame/120);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            ctx.restore();
        });
        frame++;
        if (frame < 130) requestAnimationFrame(draw);
        else canvas.remove();
    }
    draw();
}

// ═══════════════════════════════════════════════════════
// 🎮 JEU VRAI / FAUX
// ═══════════════════════════════════════════════════════
function startTrueFalseGame() {
    currentLevel = 'game-truefalse';
    updateHeaderBtns();
    const sess = getGameSession();
    const subj = GAME_SUBJECTS.find(s => s.id === sess?.subjectId) || GAME_SUBJECTS[0];
    sectionTitle.innerText = 'VRAI / FAUX ✅';

    // Générer les questions Vrai/Faux depuis le sprint (on inverse certaines réponses)
    const pool = getSubjectData('sprint');
    const questions = pool.sort(() => Math.random() - 0.5).slice(0, 12).map(q => {
        const correct = q.choices[q.answer];
        const wrong = q.choices.find((_, i) => i !== q.answer);
        const isTrue = Math.random() > 0.5;
        return {
            question: q.q,
            statement: isTrue ? correct : wrong,
            answer: isTrue,
            correctAnswer: correct
        };
    });

    let idx = 0, score = 0, streak = 0, bestStreak = 0;
    const _gen = window._gameGeneration;

    function showQ() {
        if (window._gameGeneration !== _gen) return;
        if (idx >= questions.length) {
            const coins = Math.round((score / questions.length) * 25);
            awardCoins(coins, 'Vrai/Faux terminé !');
            awardXP(score * 3, 'Vrai/Faux !');
            showGameResult('✅ VRAI / FAUX', score, questions.length, 0, coins, 'truefalse');
            return;
        }
        const q = questions[idx];
        const pct = Math.round((idx / questions.length) * 100);

        mainGrid.className = (mainGrid.className||'').replace(/page-transition[\w-]*/g,'').trim();
        void mainGrid.offsetWidth;
        mainGrid.classList.add('page-transition-scale');
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
                    <div style="font-size:0.65rem;color:${subj.color};font-weight:700;">${subj.emoji} ${subj.label}</div>
                    <div style="font-size:0.72rem;font-weight:700;color:#f1c40f;">🔥 ×${streak}</div>
                    <div style="font-size:0.72rem;color:#888;">${idx+1}/${questions.length}</div>
                </div>
                <div style="background:#111;border-radius:8px;height:4px;margin-bottom:20px;overflow:hidden;">
                    <div style="height:100%;width:${pct}%;background:${subj.color};border-radius:8px;transition:width 0.3s;"></div>
                </div>
                <div style="background:rgba(255,255,255,0.04);border:1px solid #222;border-radius:18px;padding:20px;margin-bottom:16px;">
                    <div style="font-size:0.6rem;color:#555;letter-spacing:2px;font-weight:700;margin-bottom:10px;">PROPOSITION</div>
                    <div style="font-size:0.95rem;font-weight:800;color:#fff;line-height:1.5;">${q.statement}</div>
                    <div style="font-size:0.7rem;color:#555;margin-top:10px;font-style:italic;">Concerne : ${q.question.substring(0,60)}...</div>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:16px;">
                    <div id="btn-vrai" onclick="answerTF(true)" class="ms-btn-press" style="padding:22px 10px;border-radius:18px;background:rgba(46,204,113,0.1);border:2px solid #2ecc7155;color:#2ecc71;font-weight:900;font-size:1rem;cursor:pointer;text-align:center;transition:all 0.15s;">
                        ✅ VRAI
                    </div>
                    <div id="btn-faux" onclick="answerTF(false)" class="ms-btn-press" style="padding:22px 10px;border-radius:18px;background:rgba(231,76,60,0.1);border:2px solid #e74c3c55;color:#e74c3c;font-weight:900;font-size:1rem;cursor:pointer;text-align:center;transition:all 0.15s;">
                        ❌ FAUX
                    </div>
                </div>
                <div style="display:flex;justify-content:space-between;padding:10px 4px;">
                    <div style="font-size:0.68rem;color:#2ecc71;font-weight:700;">✓ ${score} corrects</div>
                    <div style="font-size:0.68rem;color:#f1c40f;font-weight:700;">🏆 Meilleure série : ${bestStreak}</div>
                </div>
            </div>`;

        window.answerTF = (userAnswer) => {
            if (window._gameGeneration !== _gen) return;
            const correct = userAnswer === q.answer;
            if (correct) { score++; streak++; bestStreak = Math.max(bestStreak, streak); playSound(streak >= 3 ? 'streak' : 'correct'); }
            else { streak = 0; playSound('wrong'); }

            const btnV = document.getElementById('btn-vrai');
            const btnF = document.getElementById('btn-faux');
            if (btnV) btnV.onclick = null;
            if (btnF) btnF.onclick = null;

            // Feedback visuel
            if (q.answer === true) {
                if (btnV) { btnV.style.background='rgba(46,204,113,0.3)'; btnV.style.borderColor='#2ecc71'; btnV.style.transform='scale(1.04)'; }
            } else {
                if (btnF) { btnF.style.background='rgba(231,76,60,0.3)'; btnF.style.borderColor='#e74c3c'; btnF.style.transform='scale(1.04)'; }
            }
            if (!correct) {
                if (userAnswer === true && btnV) { btnV.style.background='rgba(231,76,60,0.2)'; btnV.style.borderColor='#e74c3c'; }
                if (userAnswer === false && btnF) { btnF.style.background='rgba(231,76,60,0.2)'; btnF.style.borderColor='#e74c3c'; }
                // Montrer la bonne réponse
                const hint = document.createElement('div');
                hint.style.cssText = 'grid-column:1/-1;text-align:center;padding:8px;background:rgba(241,196,15,0.08);border-radius:12px;font-size:0.75rem;color:#f1c40f;margin-top:-4px;';
                hint.innerText = '💡 Bonne réponse : ' + q.correctAnswer.substring(0,60);
                const grid = document.querySelector('#btn-vrai')?.parentNode;
                if (grid) grid.after(hint);
            }

            idx++;
            const _g2 = window._gameGeneration;
            setTimeout(() => { if (window._gameGeneration === _g2) showQ(); }, correct ? 700 : 1200);
        };
    }
    showQ();
}

// ═══════════════════════════════════════════════════════
// 🎮 JEU CHRONO — Réponds le plus vite possible
// ═══════════════════════════════════════════════════════
function startChronoGame() {
    currentLevel = 'game-chrono';
    updateHeaderBtns();
    const sess = getGameSession();
    const subj = GAME_SUBJECTS.find(s => s.id === sess?.subjectId) || GAME_SUBJECTS[0];
    sectionTitle.innerText = 'CHRONO ⏱️';

    const pool = getSubjectData('sprint');
    const questions = pool.sort(() => Math.random() - 0.5).slice(0, 8);
    let idx = 0, totalTime = 0, score = 0;
    const _gen = window._gameGeneration;

    function showQ() {
        if (window._gameGeneration !== _gen) return;
        if (idx >= questions.length) {
            const avgTime = Math.round(totalTime / questions.length / 100) / 10;
            const coins = Math.max(5, Math.round(35 - avgTime * 2));
            awardCoins(coins, 'Chrono terminé !');
            awardXP(score * 4, 'Chrono !');
            showChronoResult(score, questions.length, totalTime, coins);
            return;
        }
        const q = questions[idx];
        const startTime = Date.now();

        mainGrid.className = (mainGrid.className||'').replace(/page-transition[\w-]*/g,'').trim();
        void mainGrid.offsetWidth;
        mainGrid.classList.add('page-transition-scale');
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
                    <div style="font-size:0.65rem;color:${subj.color};font-weight:700;">${subj.emoji} ${idx+1}/${questions.length}</div>
                    <div id="chrono-display" style="font-size:1.4rem;font-weight:900;color:#e67e22;font-variant-numeric:tabular-nums;">0.0s</div>
                    <div style="font-size:0.72rem;color:#888;font-weight:700;">✓ ${score}</div>
                </div>
                <div style="background:rgba(255,255,255,0.04);border:1px solid #222;border-radius:18px;padding:22px 18px;margin-bottom:20px;">
                    <div style="font-size:0.95rem;font-weight:800;color:#fff;line-height:1.5;">${q.q}</div>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;" id="chrono-choices"></div>
            </div>`;

        // Timer visuel
        const chronoEl = document.getElementById('chrono-display');
        const timerInterval = setInterval(() => {
            if (window._gameGeneration !== _gen || !document.getElementById('chrono-display')) {
                clearInterval(timerInterval);
                return;
            }
            const elapsed = (Date.now() - startTime) / 1000;
            if (chronoEl) {
                chronoEl.innerText = elapsed.toFixed(1) + 's';
                chronoEl.style.color = elapsed < 3 ? '#2ecc71' : elapsed < 6 ? '#e67e22' : '#e74c3c';
            }
        }, 100);
        window._activeGameTimer = timerInterval;

        const grid = document.getElementById('chrono-choices');
        q.choices.forEach((c, i) => {
            const btn = document.createElement('div');
            btn.className = 'ms-btn-press';
            btn.style.cssText = 'padding:14px 10px;border-radius:14px;font-size:0.76rem;font-weight:700;cursor:pointer;text-align:center;border:1.5px solid #333;background:rgba(255,255,255,0.03);color:#fff;transition:all 0.15s;';
            btn.innerText = c;
            btn.onclick = () => {
                clearInterval(timerInterval);
                window._activeGameTimer = null;
                const elapsed = Date.now() - startTime;
                totalTime += elapsed;
                const correct = i === q.answer;
                if (correct) { score++; playSound('correct'); }
                else { recordWrongAnswer(subj.id, q.q); playSound('wrong'); }

                // Feedback
                document.querySelectorAll('#chrono-choices div').forEach((b, bi) => {
                    b.onclick = null;
                    if (bi === q.answer) { b.style.background='rgba(46,204,113,0.25)'; b.style.borderColor='#2ecc71'; b.style.color='#2ecc71'; }
                    if (bi === i && i !== q.answer) { b.style.background='rgba(231,76,60,0.25)'; b.style.borderColor='#e74c3c'; b.style.color='#e74c3c'; }
                });

                // Afficher le temps
                const timeDisplay = document.createElement('div');
                timeDisplay.style.cssText = 'text-align:center;margin-top:14px;font-size:0.9rem;font-weight:900;color:' + (correct ? '#2ecc71' : '#e74c3c') + ';animation:popIn 0.3s ease;';
                timeDisplay.innerText = (correct ? '✅ ' : '❌ ') + (elapsed/1000).toFixed(2) + 's';
                mainGrid.querySelector('div').appendChild(timeDisplay);

                idx++;
                const _g2 = window._gameGeneration;
                setTimeout(() => { if (window._gameGeneration === _g2) showQ(); }, 900);
            };
            if (grid) grid.appendChild(btn);
        });
    }
    showQ();
}

function showChronoResult(score, total, totalTimeMs, coins) {
    currentLevel = 'game-result';
    updateHeaderBtns();
    sectionTitle.innerText = 'RÉSULTAT';
    const avgTime = (totalTimeMs / total / 1000).toFixed(2);
    const bestPossible = 2.0;
    const pct = Math.round((score/total)*100);
    const emoji = pct===100?'🏆':pct>=70?'🎉':pct>=40?'👍':'💪';
    const sess = getGameSession();
    const subj = sess ? GAME_SUBJECTS.find(s => s.id === sess.subjectId) : null;

    mainGrid.className = (mainGrid.className||'').replace(/page-transition[\w-]*/g,'').trim();
    mainGrid.style.opacity = '';
    mainGrid.style.transform = '';
    void mainGrid.offsetWidth;
    mainGrid.classList.add('page-transition-scale');
    mainGrid.innerHTML = `
        <div style="grid-column:1/-1;text-align:center;padding:20px 0;">
            <div style="font-size:3rem;margin-bottom:12px;animation:popIn 0.4s ease;">${emoji}</div>
            <div style="font-size:0.7rem;color:#555;letter-spacing:2px;font-weight:700;margin-bottom:8px;">⏱️ CHRONO</div>
            ${subj ? `<div style="font-size:0.68rem;color:${subj.color};font-weight:700;margin-bottom:12px;">${subj.emoji} ${subj.label}</div>` : ''}
            <div style="font-size:2.5rem;font-weight:900;color:#fff;margin-bottom:4px;">${score}/${total}</div>
            <div style="font-size:0.85rem;color:#666;margin-bottom:16px;">${pct}% de réussite</div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:280px;margin:0 auto 20px;">
                <div style="background:rgba(230,126,22,0.08);border:1px solid rgba(230,126,22,0.3);border-radius:14px;padding:14px;">
                    <div style="font-size:1.3rem;font-weight:900;color:#e67e22;">${avgTime}s</div>
                    <div style="font-size:0.62rem;color:#666;margin-top:3px;">Temps moyen</div>
                </div>
                <div style="background:rgba(241,196,15,0.08);border:1px solid rgba(241,196,15,0.3);border-radius:14px;padding:14px;">
                    <div style="font-size:1.3rem;font-weight:900;color:#f1c40f;">🪙 +${coins}</div>
                    <div style="font-size:0.62rem;color:#666;margin-top:3px;">Pièces gagnées</div>
                </div>
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:300px;margin:0 auto;">
                <div onclick="startGame('chrono')" class="ms-btn-press" style="padding:14px;border-radius:14px;background:var(--neon-glow);border:1.5px solid var(--neon);color:var(--neon);font-weight:900;font-size:0.82rem;cursor:pointer;text-align:center;">🔄 Rejouer</div>
                <div onclick="showMiniGames()" class="ms-btn-press" style="padding:14px;border-radius:14px;background:rgba(255,255,255,0.04);border:1.5px solid #444;color:#aaa;font-weight:900;font-size:0.82rem;cursor:pointer;text-align:center;">🎮 Jeux</div>
            </div>
        </div>`;
}



// ═══════════════════════════════════════════════════════════════
// 🔊 SONS DE FEEDBACK — Web Audio API (zéro fichier externe)
// ═══════════════════════════════════════════════════════════════
let _audioCtx = null;

function getAudioCtx() {
    if (!_audioCtx) _audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return _audioCtx;
}

function playSound(type) {
    try {
        const ctx = getAudioCtx();
        if (ctx.state === 'suspended') ctx.resume();

        const sounds = {
            correct: () => {
                // Son montant joyeux
                const times = [0, 0.1, 0.2];
                const freqs = [523, 659, 784]; // Do Mi Sol
                times.forEach((t, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.value = freqs[i];
                    gain.gain.setValueAtTime(0.18, ctx.currentTime + t);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + t + 0.18);
                    osc.start(ctx.currentTime + t);
                    osc.stop(ctx.currentTime + t + 0.18);
                });
            },
            wrong: () => {
                // Son descendant grave
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain); gain.connect(ctx.destination);
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(300, ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(150, ctx.currentTime + 0.25);
                gain.gain.setValueAtTime(0.12, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.25);
            },
            perfect: () => {
                // Fanfare victoire
                const notes = [523, 659, 784, 1047];
                const times = [0, 0.12, 0.24, 0.36];
                notes.forEach((freq, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.value = freq;
                    gain.gain.setValueAtTime(0.2, ctx.currentTime + times[i]);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + times[i] + 0.22);
                    osc.start(ctx.currentTime + times[i]);
                    osc.stop(ctx.currentTime + times[i] + 0.22);
                });
            },
            coin: () => {
                // Ding pièce
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain); gain.connect(ctx.destination);
                osc.type = 'sine';
                osc.frequency.setValueAtTime(1200, ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(900, ctx.currentTime + 0.15);
                gain.gain.setValueAtTime(0.15, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.3);
            },
            click: () => {
                // Tap léger
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain); gain.connect(ctx.destination);
                osc.type = 'sine';
                osc.frequency.value = 800;
                gain.gain.setValueAtTime(0.08, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.06);
                osc.start(ctx.currentTime);
                osc.stop(ctx.currentTime + 0.06);
            },
            streak: () => {
                // Série ! Son ascendant rapide
                [400, 600, 900, 1200].forEach((freq, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.value = freq;
                    gain.gain.setValueAtTime(0.15, ctx.currentTime + i*0.07);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i*0.07 + 0.12);
                    osc.start(ctx.currentTime + i*0.07);
                    osc.stop(ctx.currentTime + i*0.07 + 0.12);
                });
            }
        };

        if (sounds[type]) sounds[type]();
    } catch(e) {
        // Silencieux si Web Audio non supporté
    }
}

