// ── Text-to-Speech ────────────────────────────────────────────
let _ttsActive = false;
function musikSpeak(text, btnEl) {
    if (!window.speechSynthesis) { showToast('🔇 TTS non supporté sur ce navigateur'); return; }
    if (_ttsActive) {
        window.speechSynthesis.cancel();
        _ttsActive = false;
        if (btnEl) { btnEl.style.background = 'transparent'; btnEl.innerHTML = '🔊'; }
        return;
    }
    const clean = text.replace(/\*\*/g,'').replace(/\*/g,'').replace(/#{1,3}\s/g,'').trim();
    const utt = new SpeechSynthesisUtterance(clean);
    utt.lang = 'fr-FR';
    utt.rate = 1.05;
    const voices = window.speechSynthesis.getVoices();
    const frVoice = voices.find(v => v.lang.startsWith('fr'));
    if (frVoice) utt.voice = frVoice;
    _ttsActive = true;
    if (btnEl) { btnEl.style.background = '#a855f722'; btnEl.innerHTML = '⏹'; }
    utt.onend = () => {
        _ttsActive = false;
        if (btnEl) { btnEl.style.background = 'transparent'; btnEl.innerHTML = '🔊'; }
    };
    utt.onerror = () => { _ttsActive = false; };
    window.speechSynthesis.speak(utt);
}

// ── Mots-clés cliquables ──────────────────────────────────────
// Nettoie le markdown pour la copie — texte propre sans codes
function _stripMarkdown(text) {
    return text
        .replace(/%%ACTION%%[\s\S]*?%%END%%/g, '')
        .replace(/\*\*([^*]+)\*\*/g, '$1')
        .replace(/__([^_]+)__/g, '$1')
        .replace(/\*([^*\n]+)\*/g, '$1')
        .replace(/_([^_\n]+)_/g, '$1')
        .replace(/~~([^~\n]+)~~/g, '$1')
        .replace(/^[-\u2022] /gm, '\u2022 ')
        .replace(/\u00ab([^\u00bb]+)\u00bb/g, '"$1"')
        .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
        .replace(/#{1,6} /g, '')
        .trim();
}

function _parseMarkdown(text) {
    // Supprime les ~~ barrés
    let t = text.replace(/~~([^~\n]+)~~/g, '$1');
    // Gras **texte**
    t = t.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
    t = t.replace(/__([^_\n]+)__/g, '<strong>$1</strong>');
    // Italique *texte* ou _texte_ (simple)
    t = t.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');
    t = t.replace(/(?<![\w])_([^_\n]+)_(?![\w])/g, '<em>$1</em>');
    // Listes à puces (- ou * en début de ligne)
    t = t.replace(/^[\-•] (.+)$/gm, '<li style="margin-left:12px;margin-bottom:3px;">$1</li>');
    t = t.replace(/(<li[^>]*>[\s\S]*?<\/li>\n?)+/g, m => `<ul style="padding-left:4px;margin:6px 0;list-style:disc;">${m}</ul>`);
    // Sauts de ligne
    t = t.replace(/\n/g, '<br>');
    return t;
}

// Rendu final d'un message IA : highlight dico puis markdown
function _renderAIText(text) {
    // 0. Blocs citations « ... » — extraits avant le reste pour éviter les interférences
    const CITE_PLACEHOLDER = '\x00CITE_BLOCK_';
    const citeBlocks = [];
    const textNoCites = text.replace(/«([^»]{4,400})»/g, function(match, inner) {
        const idx = citeBlocks.length;
        citeBlocks.push(inner.trim());
        return CITE_PLACEHOLDER + idx + '\x00';
    });

    // 1. Highlight dico + philosophes sur le texte sans citations
    const withHighlight = _highlightDicoAndPhilos(textNoCites);

    // 2. Markdown + sauts de ligne
    let rendered = withHighlight
        .replace(/~~([^~<\n]+)~~/g, '$1')
        .replace(/\*\*([^*<\n]+)\*\*/g, '<strong>$1</strong>')
        .replace(/__([^_<\n]+)__/g, '<strong>$1</strong>')
        .replace(/\*([^*<\n]+)\*/g, '<em>$1</em>')
        .replace(/(?<![\w])_([^_\n<]+)_(?![\w])/g, '<em>$1</em>')
        .replace(/^[\-•] (.+)$/gm, '<li style="margin-left:12px;margin-bottom:3px;">$1</li>')
        .replace(/(<li[^>]*>[\s\S]*?<\/li>\n?)+/g, m => `<ul style="padding-left:4px;margin:6px 0;list-style:disc;">${m}</ul>`)
        .replace(/\n/g, '<br>');

    // 3. Réinjecter les blocs citations stylés
    rendered = rendered.replace(new RegExp(CITE_PLACEHOLDER.replace('\x00','\\x00') + '(\\d+)\\x00', 'g'), function(_, i) {
        const quoteText = citeBlocks[parseInt(i)];
        const escaped = quoteText.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
        const copyFn = "navigator.clipboard&&navigator.clipboard.writeText(\"" + escaped.replace(/"/g,'\\"') + "\").then(function(){showToast('📋 Citation copiée !')});";
        return `<div style="
            display:flex;align-items:flex-start;gap:0;
            border-left:3px solid var(--neon,#8a2be2);
            background:rgba(138,43,226,0.07);
            border-radius:0 10px 10px 0;
            padding:10px 12px 10px 14px;
            margin:8px 0;position:relative;
        ">
            <div style="flex:1;font-style:italic;color:#ddddef;font-size:0.83rem;line-height:1.6;">«\u00a0${quoteText}\u00a0»</div>
            <button onclick="${copyFn}" title="Copier" style="
                flex-shrink:0;margin-left:8px;margin-top:2px;
                background:rgba(138,43,226,0.15);border:1px solid rgba(138,43,226,0.35);
                border-radius:8px;padding:4px 7px;cursor:pointer;
                font-size:0.7rem;color:#a855f7;line-height:1;
            ">📋</button>
        </div>`;
    });

    return rendered;
}

// ─── Highlight dico + noms de philosophes ──────────────────────
function _highlightDicoAndPhilos(text) {
    if (typeof DICO_DATA === 'undefined') return _escapeHtml(text);

    // Construire la liste des termes dico
    const mots = [
        ...DICO_DATA.map(d => ({ mot: d.mot, type: 'philo' })),
        ...(typeof DICO_LITTERAIRE_DATA !== 'undefined' ? DICO_LITTERAIRE_DATA.map(d => ({ mot: d.mot, type: 'litt' })) : [])
    ].filter(d => d.mot && d.mot.length > 4)
     .sort((a, b) => b.mot.length - a.mot.length);

    // Ajouter les noms de philosophes (prénom ou nom seul)
    const philoNames = typeof philosophersData !== 'undefined'
        ? philosophersData.map((p, idx) => ({ mot: p.name, type: 'philosopher', idx }))
            .filter(p => p.mot && p.mot.length > 3)
            .sort((a, b) => b.mot.length - a.mot.length)
        : [];

    const allTerms = [...philoNames, ...mots];

    const lower = text.toLowerCase();
    const matches = [];

    for (const entry of allTerms) {
        if (matches.length >= 10) break;
        const lm = entry.mot.toLowerCase();
        let idx = 0;
        while (idx < lower.length) {
            const pos = lower.indexOf(lm, idx);
            if (pos === -1) break;
            const before = pos === 0 ? ' ' : text[pos - 1];
            const after = pos + lm.length >= text.length ? ' ' : text[pos + lm.length];
            if (!/\w/.test(before) && !/\w/.test(after)) {
                const overlaps = matches.some(m => pos < m.end && pos + lm.length > m.start);
                if (!overlaps) {
                    matches.push({ start: pos, end: pos + lm.length, ...entry });
                }
            }
            idx = pos + lm.length;
        }
    }

    if (!matches.length) return _escapeHtml(text);

    matches.sort((a, b) => a.start - b.start);
    let result = '';
    let lastIdx = 0;
    for (const { start, end, mot, type, idx } of matches) {
        result += _escapeHtml(text.slice(lastIdx, start));
        let fn, color;
        if (type === 'philosopher') {
            fn = `openPhiloSheet(${idx});`;
            color = '#f1c40f';
        } else if (type === 'philo') {
            fn = `openDicoEntry('${mot.replace(/'/g,"\\'")}');closeSearch();`;
            color = '#a855f7';
        } else {
            fn = `openDicoLittEntry('${mot.replace(/'/g,"\\'")}');closeSearch();`;
            color = '#38bdf8';
        }
        result += `<span onclick="${fn}" style="color:${color};text-decoration:underline dotted ${color}66;cursor:pointer;font-weight:700;">${_escapeHtml(text.slice(start, end))}</span>`;
        lastIdx = end;
    }
    result += _escapeHtml(text.slice(lastIdx));
    return result;
}

function _escapeHtml(t) {
    return t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

