function _appendAISuggestions(topics) {
    const container = document.getElementById('ai-messages');
    if (!container || !topics || !topics.length) return;
    const div = document.createElement('div');
    div.style.cssText = 'display:flex;flex-wrap:wrap;gap:7px;padding:4px 0 4px 4px;animation:fadeInUp 0.2s ease;';
    topics.forEach(t => {
        const chip = document.createElement('span');
        chip.textContent = t;
        chip.style.cssText = 'padding:7px 13px;background:#1a1a2e;border:1px solid #7c3aed44;border-radius:20px;font-size:0.7rem;color:#a855f7;cursor:pointer;';
        chip.onclick = () => {
            const input = document.getElementById('ai-input');
            if (input) { input.value = t; sendAIMessage(); }
        };
        div.appendChild(chip);
    });
    container.appendChild(div);
    _aiAutoScroll(container);
}

function _extractSuggestions(text) {
    // Extraire les suggestions que l'IA met souvent en fin de réponse (lignes avec ? ou commençant par - ou *)
    const lines = text.split('\n').reverse();
    const suggestions = [];
    for (const line of lines) {
        const clean = line.replace(/^[-*•]\s*/, '').replace(/^\d+\.\s*/, '').trim();
        if (clean.endsWith('?') && clean.length > 10 && clean.length < 80) {
            suggestions.push(clean);
            if (suggestions.length >= 3) break;
        }
    }
    return suggestions.length ? suggestions : null;
}

// ── Historique persistant ──────────────────────────────────────
const AI_HISTORY_KEY = 'ms_ai_chat_history';
const AI_SESSIONS_KEY = 'ms_ai_sessions';

// ── Gestion sessions multiples ────────────────────────────────
function _loadSessions() {
    try { return JSON.parse(localStorage.getItem(AI_SESSIONS_KEY) || '[]'); } catch(e) { return []; }
}
function _saveSessions(sessions) {
    try { localStorage.setItem(AI_SESSIONS_KEY, JSON.stringify(sessions.slice(-30))); } catch(e) {} // max 30 sessions
}
async function _saveCurrentSession(history, existingId) {
    if (!history || history.length < 2) return null;
    const sessions = _loadSessions();
    // Mise à jour si session déjà créée (conv en cours)
    if (existingId) {
        const idx = sessions.findIndex(s => s.id === existingId);
        if (idx !== -1) { sessions[idx].history = history; _saveSessions(sessions); return existingId; }
    }
    const sessionId = 'sess_' + Date.now();
    const date = new Date();
    const label = date.toLocaleDateString('fr-FR', { day:'numeric', month:'short' }) + ' · ' + date.getHours().toString().padStart(2,'0') + 'h' + date.getMinutes().toString().padStart(2,'0');
    sessions.unshift({ id: sessionId, title: 'Conversation…', label, history });
    _saveSessions(sessions);
    return sessionId;
}

// Génère et met à jour le titre d'une session via GROQ (avec fallback immédiat)
async function _generateSessionTitle(sessionId, history) {
    if (!sessionId) return;
    // Extraire le 1er message user propre
    const firstUser = history.find(m => m.role === 'user');
    const cleanFirst = firstUser ? firstUser.content
        .replace(/\[TRACK_ACTUELLE[^\]]*\]\n?/g, '')
        .replace(/\[USER_ROLE:[^\]]*\]\n?/g, '')
        .replace(/\[COURS_ACTUEL[^\]]*\]\n?/g, '')
        .trim() : '';
    // Fallback immédiat — titre = début du 1er message
    if (cleanFirst) {
        const fallback = cleanFirst.slice(0, 40) + (cleanFirst.length > 40 ? '…' : '');
        const sessions0 = _loadSessions();
        const i0 = sessions0.findIndex(s => s.id === sessionId);
        if (i0 !== -1) { sessions0[i0].title = fallback; _saveSessions(sessions0); }
    }
    // Puis GROQ améliore le titre en arrière-plan
    try {
        const userMsgs = history
            .filter(m => m.role === 'user')
            .slice(0, 3)
            .map(m => m.content
                .replace(/\[TRACK_ACTUELLE[^\]]*\]\n?/g, '')
                .replace(/\[USER_ROLE:[^\]]*\]\n?/g, '')
                .replace(/\[COURS_ACTUEL[^\]]*\]\n?/g, '')
                .trim()
            ).join(' / ');
        const resp = await fetch(GROQ_PROXY_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: 'openai/gpt-oss-20b',
                max_tokens: 12,
                temperature: 0.3,
                messages: [
                    { role: 'system', content: "Génère un titre court (max 5 mots, sans ponctuation finale) résumant le sujet. Réponds UNIQUEMENT avec le titre, rien d'autre." },
                    { role: 'user', content: userMsgs }
                ]
            })
        });
        const data = await resp.json();
        const generated = data?.choices?.[0]?.message?.content?.trim();
        if (generated && generated.length > 0 && generated.length < 60) {
            const updated = _loadSessions();
            const idx = updated.findIndex(s => s.id === sessionId);
            if (idx !== -1) { updated[idx].title = generated; _saveSessions(updated); }
        }
    } catch(e) { /* Silencieux — fallback déjà appliqué */ }
}

