// ── Panneau historique style Claude.ai ───────────────────────
function openAIHistoryPanel() {
    const existing = document.getElementById('ai-history-panel');
    if (existing) { existing.remove(); return; }

    const sessions = _loadSessions();

    // Grouper les sessions par date
    function _groupSessions(list) {
        const groups = {};
        const now = new Date();
        const ORDER = ["Aujourd'hui", 'Hier', '7 derniers jours', '30 derniers jours', 'Plus ancien'];
        list.forEach((s, i) => {
            let groupKey = 'Plus ancien';
            try {
                const datePart = s.label.split(' · ')[0];
                const [day, monthStr] = datePart.split(' ');
                const months = {'janv':0,'févr':1,'mars':2,'avr':3,'mai':4,'juin':5,'juil':6,'août':7,'sept':8,'oct':9,'nov':10,'déc':11};
                const month = months[monthStr] ?? now.getMonth();
                const d = new Date(now.getFullYear(), month, parseInt(day));
                const diff = Math.floor((now - d) / 86400000);
                if (diff === 0) groupKey = "Aujourd'hui";
                else if (diff === 1) groupKey = 'Hier';
                else if (diff <= 7) groupKey = '7 derniers jours';
                else if (diff <= 30) groupKey = '30 derniers jours';
            } catch(e) {}
            if (!groups[groupKey]) groups[groupKey] = [];
            groups[groupKey].push({ ...s, _idx: i });
        });
        return { groups, ORDER };
    }

    // Construire le HTML de la liste
    let listHTML = '';
    if (!sessions.length) {
        listHTML = `<div style="padding:48px 20px;text-align:center;color:#333;font-size:0.8rem;">
            <div style="font-size:2.5rem;margin-bottom:12px;opacity:0.4;">💬</div>
            <div style="color:#555;">Aucune conversation<br>sauvegardée</div>
        </div>`;
    } else {
        const { groups, ORDER } = _groupSessions(sessions);
        ORDER.forEach(gk => {
            if (!groups[gk]) return;
            listHTML += `<div style="padding:14px 16px 4px;font-size:0.58rem;font-weight:700;color:#3a3a5a;letter-spacing:0.8px;text-transform:uppercase;">${gk}</div>`;
            groups[gk].forEach(s => {
                const msgCount = s.history.filter(m => m.role === 'user').length;
                listHTML += `
                    <div onclick="loadAISession(${s._idx});document.getElementById('ai-history-panel').remove();"
                         ontouchstart="this.style.background='#a855f712'" ontouchend="this.style.background='transparent'"
                         style="display:flex;align-items:center;gap:10px;padding:9px 12px;margin:1px 8px;border-radius:10px;cursor:pointer;transition:background 0.12s;-webkit-tap-highlight-color:transparent;">
                        <div style="flex:1;min-width:0;">
                            <div style="font-size:0.76rem;font-weight:500;color:#d0d0e8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${_escapeHtml(s.title)}</div>
                            <div style="font-size:0.58rem;color:#3a3a5c;margin-top:2px;">${s.label} · ${msgCount} msg</div>
                        </div>
                        <div style="font-size:0.9rem;color:#2a2a45;flex-shrink:0;">›</div>
                    </div>`;
            });
        });
    }

    // Overlay backdrop
    const overlay = document.createElement('div');
    overlay.id = 'ai-history-panel';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;display:flex;background:rgba(0,0,0,0.6);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);animation:_histFadeIn 0.15s ease;';

    // Sidebar
    const sidebar = document.createElement('div');
    sidebar.style.cssText = 'width:min(300px,85vw);height:100%;background:#0b0b18;display:flex;flex-direction:column;box-shadow:6px 0 40px rgba(0,0,0,0.9);animation:_histSlideIn 0.2s ease;overflow:hidden;';

    sidebar.innerHTML = `
        <style>
            @keyframes _histFadeIn{from{opacity:0}to{opacity:1}}
            @keyframes _histSlideIn{from{transform:translateX(-100%)}to{transform:translateX(0)}}
        </style>
        <div style="padding:14px 14px 12px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #ffffff08;flex-shrink:0;">
            <div style="width:30px;height:30px;border-radius:50%;overflow:hidden;flex-shrink:0;">${MUSIK_AVATAR_SVG}</div>
            <div style="flex:1;min-width:0;">
                <div style="font-size:0.82rem;font-weight:800;color:#fff;letter-spacing:0.2px;">MUSIK</div>
                <div style="font-size:0.56rem;color:#3a3a5c;margin-top:1px;">Historique des conversations</div>
            </div>
            <button onclick="document.getElementById('ai-history-panel').remove();"
                    style="background:none;border:none;color:#333;font-size:1.1rem;cursor:pointer;padding:4px 6px;border-radius:8px;line-height:1;flex-shrink:0;">✕</button>
        </div>
        <div style="flex:1;overflow-y:auto;padding:6px 0;">${listHTML}</div>
        <div style="padding:10px 12px 14px;border-top:1px solid #ffffff06;flex-shrink:0;display:flex;flex-direction:column;gap:7px;">
            <button onclick="_startNewAIChat();document.getElementById('ai-history-panel').remove();"
                    style="width:100%;background:linear-gradient(135deg,#a855f7,#7c3aed);border:none;border-radius:12px;color:#fff;font-size:0.74rem;font-weight:700;padding:10px;cursor:pointer;font-family:inherit;">
                ✏️ Nouvelle conversation
            </button>
            <button onclick="if(confirm('Effacer tout l\\'historique ?')){localStorage.removeItem('${AI_SESSIONS_KEY}');document.getElementById('ai-history-panel').remove();showToast('🗑️ Historique effacé');}"
                    style="width:100%;background:none;border:1px solid #ff444420;border-radius:12px;color:#ff5555;font-size:0.65rem;padding:8px;cursor:pointer;font-family:inherit;">
                🗑️ Tout effacer
            </button>
        </div>
    `;

    overlay.appendChild(sidebar);
    overlay.addEventListener('click', function(e) {
        if (!sidebar.contains(e.target)) overlay.remove();
    });
    document.body.appendChild(overlay);
}

function loadAISession(index) {
    const sessions = _loadSessions();
    const session = sessions[index];
    if (!session) return;
    // Sauvegarder la conversation courante avant de charger l'ancienne
    if (aiChatHistory.length >= 2) _saveCurrentSession(aiChatHistory, _aiSessionId);
    _aiSessionId = session.id;
    aiChatHistory = session.history;
    // Vider et re-render les messages
    const container = document.getElementById('ai-messages');
    if (!container) return;
    // Garder le message de bienvenue (premier enfant)
    const children = Array.from(container.children);
    children.slice(1).forEach(c => c.remove());
    // Indicateur de session chargée
    const sep = document.createElement('div');
    sep.style.cssText = 'text-align:center;font-size:0.58rem;color:#333;padding:4px 0 8px;';
    sep.textContent = '── ' + session.label + ' ──';
    container.appendChild(sep);
    aiChatHistory.forEach(m => appendAIMessage(m.role, m.content));
    setTimeout(_aiForceScroll, 50);
    showToast('📋 Conversation chargée');
}

