async function _triggerQuickQuiz(topic) {
    const input = document.getElementById('ai-input');
    if (!input) return;
    input.value = `Génère-moi 3 questions QCM (avec 4 choix A/B/C/D et la bonne réponse) sur : ${topic}. Format : une question par bloc, choix numérotés, réponse correcte à la fin.`;
    sendAIMessage();
}

function _appendQuizButton(parentDiv, text) {
    // Détecte si la réponse parle d'un cours ou d'une notion précise
    const lc = text.toLowerCase();
    const isCoursContent = lc.includes('liberté') || lc.includes('conscience') || lc.includes('philo')
        || lc.includes('sartre') || lc.includes('kant') || lc.includes('histoire')
        || lc.includes('maths') || lc.includes('théorème') || lc.includes('guerre')
        || lc.length > 300; // Réponse longue = probablement un cours
    if (!isCoursContent) return;

    const topic = (function() {
        const t = document.getElementById('ai-np-title');
        return t ? t.textContent.replace(/^🎵\s*/,'').trim() : 'ce cours';
    })();

    const container = document.getElementById('ai-messages');
    if (!container) return;
    const wrap = document.createElement('div');
    wrap.style.cssText = 'display:flex;justify-content:flex-start;padding:4px 0 4px 36px;';
    wrap.innerHTML = `<button onclick="_triggerQuickQuiz('${topic.replace(/'/g,"\\'")}');this.parentElement.remove();" style="background:linear-gradient(135deg,#0f3460,#1a4a7a);border:1px solid #3b82f633;border-radius:14px;color:#60a5fa;font-size:0.68rem;padding:6px 14px;cursor:pointer;font-family:inherit;">🎯 Tester mes connaissances sur ${topic}</button>`;
    container.appendChild(wrap);
}

