// FEATURE 3 — SAUVEGARDER UNE EXPLICATION
// ══════════════════════════════════════════════════════════════
function _saveExplanation(text) {
    const clean = text.replace(/\*\*/g,'').replace(/\*/g,'').replace(/<[^>]+>/g,'').trim();
    const track = (function() {
        const t = document.getElementById('ai-np-title');
        return t ? t.textContent.replace(/^🎵\s*/,'').trim() : 'Explication MUSIK';
    })();
    const blob = new Blob([`${track}\n${'─'.repeat(40)}\n\n${clean}\n\n─ Sauvegardé depuis MusicSchool`], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `MUSIK_${track.slice(0,30).replace(/[^a-zA-Z0-9]/g,'_')}.txt`;
    a.click(); URL.revokeObjectURL(url);
    showToast('📄 Explication sauvegardée !');
}

function _appendSaveButton(content, fullText) {
    if (fullText.length < 200) return; // Seulement pour les longues explications
    const btn = document.createElement('button');
    btn.title = 'Sauvegarder cette explication';
    btn.style.cssText = 'background:none;border:none;color:#2a2a3e;font-size:0.72rem;cursor:pointer;padding:0 0 0 6px;transition:color 0.2s;';
    btn.textContent = '💾';
    btn.ontouchstart = () => btn.style.color = '#a855f7';
    btn.ontouchend = () => btn.style.color = '#2a2a3e';
    btn.onclick = () => { _saveExplanation(fullText); };
    // Injecter dans la barre d'actions du message (à côté du 🔊)
    const actionRow = content.querySelector('div[style*="justify-content:space-between"]');
    if (actionRow) actionRow.appendChild(btn);
}

// ══════════════════════════════════════════════════════════════
// FEATURE 4 — STREAMING AVEC FADE-IN PAR PARAGRAPHE
// ══════════════════════════════════════════════════════════════
function _animateStreamParagraphs(contentEl) {
    if (!contentEl) return;
    // Ajouter un keyframe fadeInUp si pas déjà présent
    if (!document.getElementById('ai-fadein-style')) {
        const s = document.createElement('style');
        s.id = 'ai-fadein-style';
        s.textContent = '@keyframes fadeInUp{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}';
        document.head.appendChild(s);
    }
    // Animer les <br><br> comme séparateurs de paragraphes
    const html = contentEl.innerHTML;
    const parts = html.split(/<br><br>/i);
    if (parts.length <= 1) return;
    contentEl.innerHTML = parts.map((p, i) =>
        `<span style="display:block;animation:fadeInUp 0.25s ease ${(i*0.08).toFixed(2)}s both;">${p}</span>`
    ).join('<br>');
}

// ══════════════════════════════════════════════════════════════
// FEATURE 5 — RECONNAISSANCE VOCALE
// ══════════════════════════════════════════════════════════════
let _voiceRecognition = null;
let _voiceActive = false;

function toggleVoiceInput() {
    const btn = document.getElementById('ai-mic-btn');
    const input = document.getElementById('ai-input');

    if (_voiceActive) {
        if (_voiceRecognition) _voiceRecognition.stop();
        _voiceActive = false;
        if (btn) { btn.style.background = '#151522'; btn.style.color = '#555'; btn.style.boxShadow = 'none'; }
        return;
    }

    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { showToast('🎙️ Micro non supporté sur ce navigateur'); return; }

    _voiceRecognition = new SR();
    _voiceRecognition.lang = 'fr-FR';
    _voiceRecognition.interimResults = true;
    _voiceRecognition.maxAlternatives = 1;

    _voiceRecognition.onstart = () => {
        _voiceActive = true;
        if (btn) { btn.style.background = '#a855f722'; btn.style.color = '#a855f7'; btn.style.boxShadow = '0 0 0 3px #a855f733'; }
        if (input) input.placeholder = '🎙️ Parle, je t\'écoute...';
    };
    _voiceRecognition.onresult = (e) => {
        const transcript = Array.from(e.results).map(r => r[0].transcript).join('');
        if (input) input.value = transcript;
    };
    _voiceRecognition.onend = () => {
        _voiceActive = false;
        if (btn) { btn.style.background = '#151522'; btn.style.color = '#555'; btn.style.boxShadow = 'none'; }
        if (input) { input.placeholder = 'Dis quoi à MUSIK…'; input.style.height = 'auto'; input.style.height = Math.min(input.scrollHeight, 100) + 'px'; }
        // Auto-envoyer si du texte a été capté
        if (input && input.value.trim()) setTimeout(sendAIMessage, 300);
    };
    _voiceRecognition.onerror = (e) => {
        _voiceActive = false;
        if (btn) { btn.style.background = '#151522'; btn.style.color = '#555'; }
        if (e.error !== 'no-speech') showToast('🎙️ Erreur micro : ' + e.error);
    };
    _voiceRecognition.start();
}

// ── Affichage messages ──────────────────────────────────────────
function appendAIMessage(role, text) {
    const container = document.getElementById('ai-messages');
    if (!container) return null;
    const isUser = role === 'user';
    const now = new Date();
    const time = now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0');
    const div = document.createElement('div');
    const _cleanUserText = isUser ? text.replace(/\[TRACK_ACTUELLE[^\]]*\]\n?/g,'').replace(/\[USER_ROLE:[^\]]*\]\n?/g,'').replace(/\[COURS_ACTUEL[^\]]*\]\n?/g,'').trim() : text;
    const htmlText = isUser ? _escapeHtml(_cleanUserText).replace(/\n/g,'<br>') : _renderAIText(text);
    const msgId = 'msg_' + Date.now() + '_' + Math.random().toString(36).slice(2,5);

    if (isUser) {
        div.className = 'ai-msg-user';
        div.style.cssText = 'display:flex;justify-content:flex-end;padding:0 0 0 48px;';
        div.innerHTML = '<div style="background:linear-gradient(135deg,#6d28d9,#9333ea);padding:10px 14px 8px;border-radius:18px 4px 18px 18px;color:#fff;font-size:0.83rem;line-height:1.6;word-break:break-word;max-width:100%;box-shadow:0 2px 12px #6d28d944;">'
            + htmlText
            + '<div style="font-size:0.54rem;color:rgba(255,255,255,0.35);margin-top:4px;text-align:right;">' + time + '</div></div>';
    } else {
        div.className = 'ai-msg-bot';
        div.style.cssText = 'display:flex;align-items:flex-end;gap:7px;padding:0 48px 0 0;';
        // Construire le HTML sans interpolation inline de text (évite HTML raw visible)
        div.innerHTML = '<div style="width:24px;height:24px;border-radius:50%;overflow:hidden;flex-shrink:0;margin-bottom:20px;">' + MUSIK_AVATAR_SVG + '</div>'
            + '<div style="background:#131320;border:1px solid #ffffff0a;padding:10px 14px 8px;border-radius:4px 18px 18px 18px;color:#ddddef;font-size:0.83rem;line-height:1.65;word-break:break-word;max-width:100%;">'
            + htmlText
            + '<div style="display:flex;align-items:center;justify-content:space-between;margin-top:6px;gap:8px;">'
            + '<span style="font-size:0.54rem;color:#2a2a3e;">' + time + '</span>'
            + '<div style="display:flex;gap:6px;align-items:center;">'
            + '<button id="cp_' + msgId + '" title="Copier" style="background:none;border:none;color:#2a2a3e;font-size:0.78rem;cursor:pointer;padding:0;line-height:1;transition:color 0.2s;" ontouchstart="this.style.color=&quot;#a855f7&quot;" ontouchend="this.style.color=&quot;#2a2a3e&quot;">📋</button>'
            + '<button id="spk_' + msgId + '" style="background:none;border:none;color:#2a2a3e;font-size:0.78rem;cursor:pointer;padding:0;line-height:1;transition:color 0.2s;" ontouchstart="this.style.color=&quot;#a855f7&quot;" ontouchend="this.style.color=&quot;#2a2a3e&quot;">🔊</button>'
            + '</div></div></div>';
        // Wirer les handlers APRÈS injection DOM — jamais d'interpolation de texte dans onclick=""
        const rawText = text;
        requestAnimationFrame(function() {
            const cp = document.getElementById('cp_' + msgId);
            if (cp) cp.onclick = function() { navigator.clipboard && navigator.clipboard.writeText(_stripMarkdown(rawText)).then(function(){ showToast('📋 Copié !'); }); };
            const spk = document.getElementById('spk_' + msgId);
            if (spk) spk.onclick = function() { musikSpeak(rawText, spk); };
        });
    }
    container.appendChild(div);
    _aiAutoScroll(container);
    return div;
}

function appendAIStreamDiv() {
    const container = document.getElementById('ai-messages');
    if (!container) return null;
    const div = document.createElement('div');
    div.id = 'ai-stream-msg';
    div.className = 'ai-msg-bot';
    div.style.cssText = 'display:flex;align-items:flex-end;gap:7px;padding:0 48px 0 0;';
    div.innerHTML = `<div style="width:24px;height:24px;border-radius:50%;overflow:hidden;flex-shrink:0;margin-bottom:20px;">${MUSIK_AVATAR_SVG}</div><div id="ai-stream-content" class="ai-bubble-bot"><span id="ai-stream-cursor" style="display:inline-block;width:2px;height:13px;background:#a855f7;margin-left:1px;animation:blink 0.6s infinite;vertical-align:text-bottom;border-radius:1px;"></span></div>`;
    container.appendChild(div);
    if (!document.getElementById('ai-blink-style')) {
        const s = document.createElement('style');
        s.id = 'ai-blink-style';
        s.textContent = '@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}';
        document.head.appendChild(s);
    }
    // Pas de scroll auto au démarrage du stream
    return div;
}

function updateAIStreamContent(text) {
    const content = document.getElementById('ai-stream-content');
    const cursor = document.getElementById('ai-stream-cursor');
    if (!content) return;
    // Rendu markdown en temps réel pendant le streaming
    const displayText = text.replace(/%%ACTION%%.*?%%END%%/gs, '').trim();
    content.innerHTML = _parseMarkdown(_escapeHtml(displayText));
    if (cursor) content.appendChild(cursor);
    // Pas de scroll auto — l'utilisateur garde sa position
}

function finalizeAIStreamDiv(fullText) {
    const cursor = document.getElementById('ai-stream-cursor');
    if (cursor) cursor.remove();
    const streamDiv = document.getElementById('ai-stream-msg');
    if (streamDiv) {
        streamDiv.removeAttribute('id');
        const content = document.getElementById('ai-stream-content');
        if (content) {
            content.removeAttribute('id');
            const msgId = 'msg_' + Date.now();
            // Strip dev action tags from displayed text
            const displayText = fullText.replace(/%%ACTION%%.*?%%END%%/g, '').trim();
            const safeText = displayText.replace(/\\/g,'\\\\').replace(/"/g,'&quot;').replace(/\n/g,'\\n');
            const htmlText = _renderAIText(displayText);
            content.innerHTML = htmlText
                + `<div style="display:flex;align-items:center;justify-content:space-between;margin-top:6px;gap:8px;">
                    <span style="font-size:0.54rem;color:#2a2a3e;">${new Date().getHours().toString().padStart(2,'0')}:${new Date().getMinutes().toString().padStart(2,'0')}</span>
                    <div style="display:flex;gap:6px;align-items:center;">
                        <button onclick="navigator.clipboard&&navigator.clipboard.writeText(this.dataset.clip||'').then(()=>showToast('📋 Copié !'))"
                            title="Copier la réponse" data-clip="${safeText}"
                            style="background:none;border:none;color:#2a2a3e;font-size:0.78rem;cursor:pointer;padding:0;line-height:1;transition:color 0.2s;"
                            ontouchstart="this.style.color='#a855f7'" ontouchend="this.style.color='#2a2a3e'">📋</button>
                        <button id="${msgId}" onclick="musikSpeak(this.dataset.text,this)" data-text="${safeText}"
                            style="background:none;border:none;color:#2a2a3e;font-size:0.78rem;cursor:pointer;padding:0;line-height:1;transition:color 0.2s;"
                            ontouchstart="this.style.color='#a855f7'" ontouchend="this.style.color='#2a2a3e'">🔊</button>
                    </div>
                </div>`;
            _animateStreamParagraphs(content);
            _appendSaveButton(content, displayText);
            // Wirer le bouton copier après DOM (évite HTML raw)
            const cpBtn = document.getElementById('cp_' + msgId);
            if (cpBtn) cpBtn.onclick = () => navigator.clipboard && navigator.clipboard.writeText(_stripMarkdown(displayText)).then(() => showToast('📋 Copié !'));
        }
        // Execute any dev commands embedded in response (Boss only)
        if (_isBoss()) _executeDevCommands(fullText);
        const suggestions = _extractSuggestions(fullText);
        if (suggestions) _appendAISuggestions(suggestions);
        _appendContextualQuickReplies(streamDiv, fullText);
        _appendQuizButton(streamDiv, fullText);
        _appendReactionRow(streamDiv, fullText);
    }
}

// ─── MUSIK DEV COMMANDS (Boss mode only) ─────────────────────
function _executeDevCommands(text) {
    const regex = /%%ACTION%%\s*({[\s\S]*?})\s*%%END%%/g;
    let match;
    while ((match = regex.exec(text)) !== null) {
        try {
            const cmd = JSON.parse(match[1]);
            switch (cmd.cmd) {
                case 'VOLUME':
                    setAudioGain(parseFloat(cmd.value));
                    _devCommandFeedback('🔊 Volume réglé à ' + Math.round(cmd.value * 100) + '%');
                    break;
                case 'NIGHT_MODE':
                    const nm = JSON.parse(localStorage.getItem('ms_night_mode') || '{"mode":"off","startHour":21,"endHour":6}');
                    nm.mode = cmd.mode;
                    if (cmd.startHour !== undefined) nm.startHour = cmd.startHour;
                    if (cmd.endHour !== undefined) nm.endHour = cmd.endHour;
                    localStorage.setItem('ms_night_mode', JSON.stringify(nm));
                    applyNightMode();
                    _devCommandFeedback('🌙 Mode nuit : ' + cmd.mode);
                    break;
                case 'THEME':
                    if (cmd.color) {
                        localStorage.setItem('ms_active_theme', cmd.color);
                        applyTheme(cmd.color);
                        _devCommandFeedback('🎨 Thème changé : ' + cmd.color);
                    }
                    break;
                case 'TOAST':
                    if (cmd.msg) showToast('⚡ ' + cmd.msg);
                    break;
                case 'TEXT_STYLE': {
                    const cs = JSON.parse(localStorage.getItem('ms_chat_style') || '{}');
                    if (cmd.style !== undefined) cs.style = cmd.style; // 'normal'|'italic'|'bold'|'bold-italic'
                    localStorage.setItem('ms_chat_style', JSON.stringify(cs));
                    applyChatStyle();
                    const styleLabels = {'normal':'Normal','italic':'Italique','bold':'Gras','bold-italic':'Gras Italique'};
                    _devCommandFeedback('✍️ Style texte : ' + (styleLabels[cmd.style] || cmd.style));
                    break;
                }
                case 'FONT_SIZE': {
                    const cs = JSON.parse(localStorage.getItem('ms_chat_style') || '{}');
                    if (cmd.size !== undefined) cs.size = cmd.size; // 'small'|'normal'|'large'
                    localStorage.setItem('ms_chat_style', JSON.stringify(cs));
                    applyChatStyle();
                    const sizeLabels = {'small':'Petit','normal':'Normal','large':'Grand'};
                    _devCommandFeedback('🔡 Taille texte : ' + (sizeLabels[cmd.size] || cmd.size));
                    break;
                }
                case 'BUBBLE_COLOR': {
                    const cs = JSON.parse(localStorage.getItem('ms_chat_style') || '{}');
                    if (cmd.color !== undefined) cs.bubbleColor = cmd.color;
                    localStorage.setItem('ms_chat_style', JSON.stringify(cs));
                    applyChatStyle();
                    _devCommandFeedback('💬 Couleur bulle : ' + cmd.color);
                    break;
                }
                case 'RESET_STYLE': {
                    localStorage.removeItem('ms_chat_style');
                    applyChatStyle();
                    _devCommandFeedback('🔄 Style remis à zéro');
                    break;
                }
            }
        } catch(e) { console.log('Dev cmd parse error', e); }
    }
}

// ─── APPLY CHAT STYLE (Boss customization) ───────────────────
function applyChatStyle() {
    const cs = JSON.parse(localStorage.getItem('ms_chat_style') || '{}');
    const style = cs.style || 'normal';
    const size = cs.size || 'normal';
    const bubbleColor = cs.bubbleColor || null;

    const fontStyle = (style === 'italic' || style === 'bold-italic') ? 'italic' : 'normal';
    const fontWeight = (style === 'bold' || style === 'bold-italic') ? '700' : '400';
    const fontSizeMap = { small: '0.72rem', normal: '0.83rem', large: '0.96rem' };
    const fontSize = fontSizeMap[size] || '0.83rem';

    let el = document.getElementById('_ms_chat_style_tag');
    if (!el) {
        el = document.createElement('style');
        el.id = '_ms_chat_style_tag';
        document.head.appendChild(el);
    }
    const bubbleBg = bubbleColor ? bubbleColor : '#131320';
    el.textContent = [
        '#ai-messages .ai-msg-bot > div:nth-child(2) {',
        '  font-style:' + fontStyle + ' !important;',
        '  font-weight:' + fontWeight + ' !important;',
        '  font-size:' + fontSize + ' !important;',
        '  background:' + bubbleBg + ' !important;',
        '}',
        '#ai-stream-content {',
        '  font-style:' + fontStyle + ' !important;',
        '  font-weight:' + fontWeight + ' !important;',
        '  font-size:' + fontSize + ' !important;',
        '}'
    ].join('\n');
}

function _devCommandFeedback(msg) {
    const existing = document.getElementById('dev-action-badge');
    if (existing) existing.remove();

    // Couleur adaptée selon la commande
    let accent = '#f59e0b', glow = '#f59e0b33', icon = '⚡';
    if (msg.includes('nuit') || msg.includes('Mode')) { accent = '#818cf8'; glow = '#818cf833'; icon = '🌙'; }
    else if (msg.includes('Volume')) { accent = '#34d399'; glow = '#34d39933'; icon = '🔊'; }
    else if (msg.includes('Theme') || msg.includes('couleur') || msg.includes('Thème')) { accent = '#f472b6'; glow = '#f472b633'; icon = '🎨'; }

    if (!document.getElementById('_dcf_style')) {
        const s = document.createElement('style');
        s.id = '_dcf_style';
        s.textContent = '@keyframes dcfIn{from{opacity:0;transform:translateX(-50%) translateY(12px) scale(0.9)}to{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}} @keyframes dcfOut{from{opacity:1;transform:translateX(-50%) scale(1)}to{opacity:0;transform:translateX(-50%) scale(0.85)}} #dev-action-badge{animation:dcfIn 0.22s cubic-bezier(0.34,1.4,0.64,1) both;} #dev-action-badge.leaving{animation:dcfOut 0.18s ease forwards;}';
        document.head.appendChild(s);
    }

    const badge = document.createElement('div');
    badge.id = 'dev-action-badge';
    badge.style.cssText = 'position:fixed;bottom:120px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#0d0d1a,#1a1a2e);border:1.5px solid ' + accent + '66;border-radius:40px;padding:10px 20px 10px 14px;font-size:0.75rem;font-weight:800;color:' + accent + ';z-index:99999;box-shadow:0 6px 28px ' + glow + ',0 0 0 1px ' + accent + '22;white-space:nowrap;display:flex;align-items:center;gap:8px;';

    const iconEl = document.createElement('span');
    iconEl.style.fontSize = '1rem';
    iconEl.textContent = icon;

    const textEl = document.createElement('span');
    textEl.textContent = msg;

    const checkEl = document.createElement('span');
    checkEl.style.cssText = 'background:' + accent + '22;color:' + accent + ';width:18px;height:18px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:0.65rem;margin-left:4px;';
    checkEl.textContent = '✓';

    badge.appendChild(iconEl);
    badge.appendChild(textEl);
    badge.appendChild(checkEl);
    document.body.appendChild(badge);

    setTimeout(function(){
        badge.classList.add('leaving');
        setTimeout(function(){ if (badge.parentNode) badge.remove(); }, 200);
    }, 2800);
}

function _appendContextualQuickReplies(parentDiv, text) {
    // Supprimer les anciens quick replies
    document.querySelectorAll('.ai-qr-wrap').forEach(el => el.remove());

    const container = document.getElementById('ai-messages');
    if (!container) return;

    const lc = text.toLowerCase();
    let btns = [];

    // Contexte philo
    if (lc.includes('philosophe') || lc.includes('platon') || lc.includes('kant') || lc.includes('nietzsche') || lc.includes('sartre') || lc.includes('descartes')) {
        btns.push({ icon: '🏛️', label: 'Cite un auteur clé', msg: "Cite-moi un auteur clé et sa citation pour retenir ça" });
        btns.push({ icon: '🎤', label: 'Fais une punchline', msg: "Fais-moi une punchline pour retenir ce concept" });
    }
    // Contexte perso/émotions
    else if (lc.includes('fatigue') || lc.includes('stress') || lc.includes('difficile') || lc.includes('abandon') || lc.includes('capte') || lc.includes('ensemble')) {
        btns.push({ icon: '❤️', label: 'Besoin de réconfort', msg: "J'ai besoin de motivation là" });
        btns.push({ icon: '🎧', label: 'Quel son écouter ?', msg: "Quel cours tu me conseilles pour démarrer ?" });
    }
    // Contexte dissertation/méthode
    else if (lc.includes('dissert') || lc.includes('plan') || lc.includes('introduction') || lc.includes('conclusion')) {
        btns.push({ icon: '📋', label: 'Génère un plan', msg: "Génère-moi un plan complet pour ce sujet" });
        btns.push({ icon: '🎤', label: 'Punchline mémo', msg: "Fais-moi une punchline pour retenir la méthode" });
    }
    // Par défaut
    else {
        btns.push({ icon: '🔍', label: 'Explique plus simplement', msg: "Explique-moi ça plus simplement stp" });
        btns.push({ icon: '🎤', label: 'Punchline mémo', msg: "Fais-moi une punchline pour retenir ça" });
        btns.push({ icon: '💪', label: 'Motivation', msg: "J'ai besoin de motivation là" });
    }

    const wrap = document.createElement('div');
    wrap.className = 'ai-qr-wrap';
    wrap.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;padding:4px 0 4px 36px;';
    btns.forEach(function(b, i) {
        const btn = document.createElement('button');
        btn.className = 'ai-quick-reply-btn';
        btn.style.animationDelay = (i * 0.07) + 's';
        btn.textContent = b.icon + ' ' + b.label;
        btn.onclick = function() {
            // Supprimer tous les quick replies dès le clic
            document.querySelectorAll('.ai-qr-wrap').forEach(el => el.remove());
            const inp = document.getElementById('ai-input');
            if (inp) { inp.value = b.msg; sendAIMessage(); }
        };
        wrap.appendChild(btn);
    });
    container.appendChild(wrap);
}

// Auto-scroll intelligent
let _aiUserScrolled = false;
let _aiIsStreaming = false;

function _aiAutoScroll(container) {
    // Scroll auto vers le bas pour les nouveaux messages (pas pendant lecture)
    if (!_aiUserScrolled && !_aiIsStreaming) {
        requestAnimationFrame(() => { container.scrollTop = container.scrollHeight; });
    }
}

function _aiForceScroll() {
    const container = document.getElementById('ai-messages');
    if (container) {
        container.scrollTop = container.scrollHeight;
        _aiUserScrolled = false;
        const fab = document.getElementById('ai-scroll-fab');
        if (fab) fab.style.display = 'none';
    }
}

function _setupAIScrollListener() {
    const container = document.getElementById('ai-messages');
    if (!container) return;
    _aiUserScrolled = false;
    _aiIsStreaming = false;
    // Scroll to bottom on open
    requestAnimationFrame(() => { container.scrollTop = container.scrollHeight; });
    // Utiliser une fonction nommée pour pouvoir la retirer
    container._aiScrollHandler = () => {
        if (_aiIsStreaming) return;
        const atBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 60;
        _aiUserScrolled = !atBottom;
        const fab = document.getElementById('ai-scroll-fab');
        if (fab) fab.style.display = atBottom ? 'none' : 'flex';
    };
    container.addEventListener('scroll', container._aiScrollHandler, { passive: true });
}

function appendAITyping() {
    const container = document.getElementById('ai-messages');
    if (!container) return;
    const div = document.createElement('div');
    div.id = 'ai-typing';
    div.className = 'ai-msg-bot';
    div.style.cssText = 'display:flex;align-items:flex-end;gap:7px;padding:0 48px 0 0;';
    div.innerHTML = `
        <div style="width:24px;height:24px;border-radius:50%;overflow:hidden;flex-shrink:0;">${MUSIK_AVATAR_SVG}</div>
        <div style="background:#131320;border:1px solid #ffffff0a;padding:11px 15px;border-radius:4px 18px 18px 18px;display:flex;gap:5px;align-items:center;">
            <span style="width:7px;height:7px;border-radius:50%;background:#a855f7;display:inline-block;animation:typingPop 1.2s ease infinite 0s;"></span>
            <span style="width:7px;height:7px;border-radius:50%;background:#a855f7;display:inline-block;animation:typingPop 1.2s ease infinite 0.2s;"></span>
            <span style="width:7px;height:7px;border-radius:50%;background:#a855f7;display:inline-block;animation:typingPop 1.2s ease infinite 0.4s;"></span>
        </div>`;
    container.appendChild(div);
    _aiAutoScroll(container);
    if (!document.getElementById('ai-typing-style')) {
        const s = document.createElement('style');
        s.id = 'ai-typing-style';
        s.textContent = '@keyframes typingPop{0%,80%,100%{transform:scale(0.6);opacity:0.3}40%{transform:scale(1.1);opacity:1}}';
        document.head.appendChild(s);
    }
}

// ── Now-playing widget updater ────────────────────────────────
function _updateNowPlayingWidget() {
    const widget = document.getElementById('ai-now-playing');
    const titleEl = document.getElementById('ai-np-title');
    const headerStatus = document.getElementById('musik-header-status');
    const chipsWrap = document.getElementById('ai-chips-wrap');
    if (!widget || !titleEl) return;
    const pl = (typeof currentlyPlayingId !== 'undefined' && currentlyPlayingId)
        ? (lessonsData.find(l => l.id === currentlyPlayingId)
           || (typeof AM_LESSONS !== 'undefined' ? AM_LESSONS.find(l => l.id === currentlyPlayingId) : null))
        : null;
    if (pl) {
        titleEl.textContent = '🎵 ' + pl.title;
        widget.style.display = 'block';
        if (headerStatus) headerStatus.innerHTML = `<span style="width:5px;height:5px;border-radius:50%;background:#a855f7;display:inline-block;animation:pulseOnline 2.5s ease infinite;"></span> 🎧 MUSIK écoute : ${pl.title}`;
        if (chipsWrap) chipsWrap.style.display = 'block';
        _saveLastTrack(pl.title); // Mémoire dernier cours
    } else {
        widget.style.display = 'none';
        if (headerStatus) headerStatus.innerHTML = `<span style="width:5px;height:5px;border-radius:50%;background:#22c55e;display:inline-block;animation:pulseOnline 2.5s ease infinite;"></span> 🤫 MUSIK t'écoute...`;
        if (chipsWrap) chipsWrap.style.display = 'none';
    }
}

// ── Badge état : génération en cours ─────────────────────────
function _musikBadgeGenerating(on) {
    const headerStatus = document.getElementById('musik-header-status');
    if (!headerStatus) return;
    if (on) {
        headerStatus.innerHTML = `<span style="width:5px;height:5px;border-radius:50%;background:#f59e0b;display:inline-block;animation:pulseOnline 0.6s ease infinite;"></span> <span style="color:#f59e0b;">✍️ En train d'écrire...</span>`;
    } else {
        _updateNowPlayingWidget();
    }
}

// ── Envoi message avec streaming ───────────────────────────────
async function sendAIMessage() {
    const input = document.getElementById('ai-input');
    const sendBtn = document.getElementById('ai-send-btn');
    if (!input || !aiChatContext) return;
    const text = input.value.trim();
    if (!text) return;

    if (!navigator.onLine) {
        appendAIMessage('user', text);
        appendAIMessage('assistant', '📡 T\'es hors ligne ! Reconnecte-toi à internet pour utiliser l\'IA. Je serai là dès que tu reviens. 🤙');
        input.value = '';
        return;
    }

    input.value = '';
    input.style.height = 'auto';
    const charCount = document.getElementById('ai-char-count');
    if (charCount) charCount.textContent = '';
    if (sendBtn) { sendBtn.style.opacity = '0.4'; sendBtn.onclick = null; }

    // Supprimer les quick replies précédents
    document.querySelectorAll('.ai-qr-wrap').forEach(el => el.remove());

    // Mise à jour widget now-playing
    _updateNowPlayingWidget();

    appendAIMessage('user', text);

    // ── Injection TRACK_ACTUELLE + USER_ROLE ─────────────────────
    const _currentTrack = (typeof currentlyPlayingId !== 'undefined' && currentlyPlayingId)
        ? (lessonsData.find(l => l.id === currentlyPlayingId) || (typeof AM_LESSONS !== 'undefined' ? AM_LESSONS.find(l => l.id === currentlyPlayingId) : null))
        : null;
    const _trackTag = _currentTrack
        ? `[TRACK_ACTUELLE : ${_currentTrack.title}]`
        : `[TRACK_ACTUELLE : AUCUNE]`;
    const _roleTag = _isBoss() ? '[USER_ROLE: BOSS]' : '[USER_ROLE: ELEVE]';
    const _textWithTrack = _trackTag + '\n' + _roleTag + '\n' + text;

    aiChatHistory.push({ role: 'user', content: _textWithTrack });
    appendAITyping();
    _musikBadgeGenerating(true);

    try {
        const messages = [
            { role: 'system', content: aiChatContext.system },
            ...aiChatHistory.map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content }))
        ];

        const response = await fetch(GROQ_PROXY_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                model: 'openai/gpt-oss-120b',
                max_tokens: 1024,
                temperature: 0.85,
                stream: true,
                messages: messages
            })
        });

        document.getElementById('ai-typing')?.remove();

        if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            appendAIMessage('assistant', '⚠️ ' + (errData.error?.message || 'Erreur réseau. Réessaie dans 1 minute.'));
            if (sendBtn) { sendBtn.style.opacity = '1'; sendBtn.onclick = sendAIMessage; }
            return;
        }

        appendAIStreamDiv();
        _aiUserScrolled = false;
        _aiIsStreaming = true;
        // Montrer le bouton ↓ pour indiquer qu'il y a du nouveau contenu en bas
        const fabEl = document.getElementById('ai-scroll-fab');
        if (fabEl) { 
            fabEl.style.display = 'flex'; 
            fabEl.textContent = '↓ Nouveau message';
            fabEl.onclick = () => { _aiForceScroll(); };
        }
        // Désactiver complètement le listener scroll pendant le stream
        const msgsContainer = document.getElementById('ai-messages');
        if (msgsContainer?._aiScrollHandler) {
            msgsContainer.removeEventListener('scroll', msgsContainer._aiScrollHandler);
        }

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let fullText = '';
        let buffer = '';

        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() || '';
            for (const line of lines) {
                if (!line.startsWith('data: ')) continue;
                const data = line.slice(6).trim();
                if (data === '[DONE]') break;
                try {
                    const parsed = JSON.parse(data);
                    const token = parsed.choices?.[0]?.delta?.content || '';
                    if (token) { fullText += token; updateAIStreamContent(fullText); }
                } catch(e) {}
            }
        }

        _aiIsStreaming = false;
        finalizeAIStreamDiv(fullText);
        _musikBadgeGenerating(false);
        // Pas de force scroll — position conservée
        // Réactiver le listener scroll
        setTimeout(_setupAIScrollListener, 100);
        aiChatHistory.push({ role: 'assistant', content: fullText });
        saveAIChatHistory(aiChatHistory);
        // — Titre auto : créer/mettre à jour la session en cours après le 1er échange
        if (aiChatContext && aiChatContext.type === 'general') {
            if (!_aiSessionId) {
                // Première réponse reçue : créer la session ET générer le titre
                const newId = await _saveCurrentSession(aiChatHistory);
                if (newId) {
                    _aiSessionId = newId;
                    _generateSessionTitle(newId, aiChatHistory); // async, pas besoin d'await
                }
            } else {
                // Mise à jour de l'historique dans la session existante
                _saveCurrentSession(aiChatHistory, _aiSessionId);
            }
        }

    } catch (err) {
        document.getElementById('ai-typing')?.remove();
        document.getElementById('ai-stream-msg')?.remove();
        _musikBadgeGenerating(false);
        // Logger l'erreur réelle pour debug
        console.error('[MUSIK] Erreur sendAIMessage:', err?.message || err);
        const isOffline = !navigator.onLine;
        const isAbort = err?.name === 'AbortError';
        const msg = isOffline
            ? '📡 T\'es hors ligne ! Reconnecte-toi et réessaie.'
            : isAbort
            ? '⏹️ Requête annulée.'
            : '⚠️ Erreur : ' + (err?.message || 'inconnue') + ' — Réessaie !';
        appendAIMessage('assistant', msg);
    }

    if (sendBtn) { sendBtn.style.opacity = '1'; sendBtn.onclick = sendAIMessage; }
}


// ═══════════════════════════════════════════════════════════════
// ✅ PWA — Manifest dynamique + Service Worker (intégré dans JS)
// ═══════════════════════════════════════════════════════════════

(function initPWA() {
    // ── PWA : manifest.json est déjà déclaré statiquement dans index.html ──
    // (plus besoin de le réinjecter en JS avec des icônes en base64 —
    // ça faisait doublon avec le <link rel="manifest"> de index.html et
    // gonflait ce fichier de ~220 Ko pour rien. Les icônes réelles sont
    // maintenant des fichiers icon-192.png / icon-512.png à la racine.)

    function setMetaTags() {
        try {
            // Theme color
            let meta = document.querySelector('meta[name="theme-color"]');
            if (!meta) {
                meta = document.createElement('meta');
                meta.name = 'theme-color';
                document.head.appendChild(meta);
            }
            meta.content = '#8a2be2';

            // Apple touch icon (fichier réel, plus de base64 inline)
            if (!document.querySelector('link[rel="apple-touch-icon"]')) {
                const apple = document.createElement('link');
                apple.rel = 'apple-touch-icon';
                apple.href = './icon-192.png';
                document.head.appendChild(apple);
            }
        } catch(e) {}
    }

    // ── Enregistrement Service Worker ──
    function registerSW() {
        if (!('serviceWorker' in navigator)) return;
        navigator.serviceWorker.getRegistrations().then(regs => {
            // Déjà enregistré (ex: par index.html)
            if (regs.length > 0) return;
            navigator.serviceWorker.register('./sw.js', { scope: './' })
                .then(() => {})
                .catch(() => {}); // Silencieux si sw.js absent
        });
    }

    // 🆕 INSTALLATION FACILE — jusqu'ici, rien ne guidait l'utilisateur
    // pour installer l'app sur son téléphone : sur Android/Chrome, le
    // popup natif apparaît de façon imprévisible (parfois jamais) ; sur
    // iOS, aucun bouton natif n'existe du tout — il faut passer par
    // Partager → "Sur l'écran d'accueil", un geste que personne ne
    // devine seul. On capture le prompt Android pour le déclencher nous-
    // mêmes au bon moment, et on affiche des instructions claires sur
    // iOS, via une petite bannière discrète, non-intrusive, affichée une
    // seule fois par appareil.
    let _deferredInstallPrompt = null;

    window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault();
        _deferredInstallPrompt = e;
        _maybeShowInstallBanner('android');
    });

    window.addEventListener('appinstalled', () => {
        _deferredInstallPrompt = null;
        localStorage.setItem('ms_install_dismissed', 'true');
        const banner = document.getElementById('ms-install-banner');
        if (banner) banner.remove();
    });

    function _isRunningStandalone() {
        return window.matchMedia('(display-mode: standalone)').matches
            || window.navigator.standalone === true; // iOS Safari
    }

    function _isIOS() {
        return /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    }

    function _maybeShowInstallBanner(platform) {
        if (_isRunningStandalone()) return; // déjà installée
        if (localStorage.getItem('ms_install_dismissed') === 'true') return;
        if (document.getElementById('ms-install-banner')) return; // déjà affichée

        const banner = document.createElement('div');
        banner.id = 'ms-install-banner';
        banner.style.cssText = `
            position:fixed; left:12px; right:12px; bottom:12px; z-index:9998;
            background:#111; border:1px solid #8a2be255; border-radius:16px;
            padding:14px 16px; display:flex; align-items:center; gap:12px;
            box-shadow:0 8px 24px rgba(0,0,0,0.4);
            font-family:inherit;
        `;

        const text = platform === 'ios'
            ? `<div style="font-size:0.8rem;color:#fff;font-weight:700;">📲 Installe MusicSchool</div>
               <div style="font-size:0.72rem;color:#999;margin-top:2px;">Appuie sur <b>Partager</b> puis <b>"Sur l'écran d'accueil"</b></div>`
            : `<div style="font-size:0.8rem;color:#fff;font-weight:700;">📲 Installe MusicSchool</div>
               <div style="font-size:0.72rem;color:#999;margin-top:2px;">Accès rapide, même hors connexion</div>`;

        banner.innerHTML = `
            <div style="flex:1;">${text}</div>
            ${platform === 'android' ? `<button id="ms-install-btn" style="background:#8a2be2;border:none;color:#fff;padding:8px 14px;border-radius:10px;font-size:0.75rem;font-weight:800;cursor:pointer;white-space:nowrap;">Installer</button>` : ''}
            <button id="ms-install-dismiss" style="background:none;border:none;color:#666;font-size:1.1rem;cursor:pointer;padding:4px 8px;">✕</button>
        `;
        document.body.appendChild(banner);

        const dismissBtn = document.getElementById('ms-install-dismiss');
        if (dismissBtn) {
            dismissBtn.onclick = () => {
                localStorage.setItem('ms_install_dismissed', 'true');
                banner.remove();
            };
        }

        const installBtn = document.getElementById('ms-install-btn');
        if (installBtn) {
            installBtn.onclick = async () => {
                if (!_deferredInstallPrompt) return;
                _deferredInstallPrompt.prompt();
                const { outcome } = await _deferredInstallPrompt.userChoice;
                if (typeof window._msTrack === 'function') {
                    window._msTrack('pwa_install_prompt_result', { outcome });
                }
                _deferredInstallPrompt = null;
                banner.remove();
            };
        }
    }

    // Sur iOS, il n'y a pas d'événement "beforeinstallprompt" — on
    // affiche directement les instructions manuelles après un court
    // délai, pour ne pas gêner le tout premier instant de découverte.
    if (_isIOS() && !_isRunningStandalone()) {
        setTimeout(() => _maybeShowInstallBanner('ios'), 8000);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => { setMetaTags(); registerSW(); });
    } else {
        setMetaTags();
        registerSW();
    }
})();

// ═══════════════════════════════════════════════════════════════
// ✅ BACKUP / RESTORE — Export & Import JSON complet
// ═══════════════════════════════════════════════════════════════

const _MS_BACKUP_KEYS = [
    'xpData', 'ms_coins', 'completedLessons', 'likedLessons',
    'ms_owned_items', 'ms_active_theme', 'ms_active_title',
    'ms_active_badge', 'ms_active_frame', 'ms_wrong_answers',
    'ms_boosts', 'ms_xp_history', 'ms_am_streak', 'ms_am_votes',
    'ms_dico_favs', 'ms_bac_dates', 'ms_game_session',
    'ms_listen_history', 'ms_night_mode', 'ms_notifs',
    'ms_objectif_date', 'ms_objectif_done', 'wheelSpinData',
    'xpMilestone50Ids', 'userAccount', 'profilePhoto',
    'am_citation_day', 'am_citation_idx', 'ms_login_count',
    'ms_onboarding_done', 'ms_founder_bonus', 'ms_quote_date',
    'ms_defi_date', 'ms_defi_dismissed', 'ms_audio_gain'
];

function exportUserData() {
    try {
        const backup = { _version: 1, _date: new Date().toISOString(), data: {} };
        _MS_BACKUP_KEYS.forEach(k => {
            const v = localStorage.getItem(k);
            if (v !== null) backup.data[k] = v;
        });
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (k && (k.startsWith('ms_progress_') || k.startsWith('ms_boost_'))) {
                backup.data[k] = localStorage.getItem(k);
            }
        }
        const json = JSON.stringify(backup, null, 2);
        const blob = new Blob([json], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const dateStr = new Date().toLocaleDateString('fr-FR').replace(/\//g, '-');
        a.download = 'MusicSchool_Backup_' + dateStr + '.json';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        showToast('✅ Backup téléchargé !');
    } catch(e) {
        showToast('❌ Erreur export : ' + (e.message || 'inconnue'));
    }
}

function importUserData() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json,application/json';
    input.onchange = function(e) {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = function(ev) {
            try {
                const backup = JSON.parse(ev.target.result);
                if (!backup.data || backup._version !== 1) {
                    showToast('❌ Fichier invalide !'); return;
                }
                const count = Object.keys(backup.data).length;
                if (!confirm('⚠️ Restaurer ' + count + ' données ? Tes données actuelles seront remplacées.')) return;
                Object.entries(backup.data).forEach(([k, v]) => {
                    if (v !== null && v !== undefined) localStorage.setItem(k, v);
                });
                showToast('✅ Restauré ! Rechargement…');
                setTimeout(() => location.reload(), 1500);
            } catch(err) {
                showToast('❌ Erreur import : ' + (err.message || 'fichier corrompu'));
            }
        };
        reader.readAsText(file);
    };
    document.body.appendChild(input);
    input.click();
    document.body.removeChild(input);
}

// ═══════════════════════════════════════════════════════════════
// ✅ TESTS AUTO — Validation intégrité app
// ═══════════════════════════════════════════════════════════════

function runTests() {
    const results = [];
    let pass = 0, fail = 0;
    function assert(label, condition) {
        if (condition) { results.push('✅ ' + label); pass++; }
        else { results.push('❌ FAIL: ' + label); fail++; }
    }
    assert('lessonsData existe', typeof lessonsData !== 'undefined' && Array.isArray(lessonsData));
    assert('lessonsData non vide', typeof lessonsData !== 'undefined' && lessonsData.length > 0);
    assert('ORACLE_DATA existe', typeof ORACLE_DATA !== 'undefined' && Array.isArray(ORACLE_DATA));
    assert('DICO_DATA existe', typeof DICO_DATA !== 'undefined' && Array.isArray(DICO_DATA));
    assert('DICO_LITTERAIRE existe', typeof DICO_LITTERAIRE !== 'undefined' && Array.isArray(DICO_LITTERAIRE));
    assert('showToast défini', typeof showToast === 'function');
    assert('getXPData défini', typeof getXPData === 'function');
    assert('getCoins défini', typeof getCoins === 'function');
    assert('exportUserData défini', typeof exportUserData === 'function');
    assert('importUserData défini', typeof importUserData === 'function');
    try {
        const xp = getXPData();
        assert('getXPData retourne objet valide', xp && typeof xp.xp === 'number');
    } catch(e) { assert('getXPData sans erreur', false); }
    assert('localStorage accessible', (function() {
        try { localStorage.setItem('_ms_test','1'); localStorage.removeItem('_ms_test'); return true; }
        catch(e) { return false; }
    })());
    if (typeof lessonsData !== 'undefined') {
        const t = lessonsData[0];
        assert('Leçon a id', t && typeof t.id === 'number');
        assert('Leçon a title', t && typeof t.title === 'string');
    }
    const summary = '\n══ TESTS MUSICSCHOOL ══\n' + results.join('\n') + '\n\n' + pass + ' passés / ' + (pass+fail) + ' total' + (fail > 0 ? '\n⚠️ ' + fail + ' test(s) échoué(s) !' : '\n🎉 Tout est OK !');
    console.log(summary);
    alert(summary);
    return { pass, fail };
}

// ═══════════════════════════════════════════════════════════════
// ✅ TRANSITIONS ÉCRANS — Fade-in fluide
// ═══════════════════════════════════════════════════════════════

(function initScreenTransitions() {
    const style = document.createElement('style');
    style.textContent = `
        @keyframes ms-fadein {
            from { opacity: 0; transform: translateY(8px); }
            to   { opacity: 1; transform: translateY(0); }
        }
        .ms-screen-enter {
            animation: ms-fadein 0.22s cubic-bezier(.4,0,.2,1) both;
        }
    `;
    document.head.appendChild(style);

    function observeGrid() {
        const grid = document.getElementById('main-grid');
        if (!grid) { setTimeout(observeGrid, 300); return; }
        const observer = new MutationObserver(function(mutations) {
            if (!mutations.some(m => m.addedNodes.length > 0)) return;
            grid.classList.remove('ms-screen-enter');
            void grid.offsetWidth;
            grid.classList.add('ms-screen-enter');
        });
        observer.observe(grid, { childList: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', observeGrid);
    } else {
        observeGrid();
    }
})();

// ═══════════════════════════════════════════════════════════════
// 📊 RÉCAP DE SESSION
// ═══════════════════════════════════════════════════════════════
var _sessionData = { xp: 0, coins: 0, lessons: 0, startTime: Date.now() };

function _sessionInit() {
    _sessionData = { xp: 0, coins: 0, lessons: 0, startTime: Date.now() };
}

function _sessionTrackXP(amount) { _sessionData.xp += amount; }
function _sessionTrackCoins(amount) { _sessionData.coins += amount; }
function _sessionTrackLesson() { _sessionData.lessons += 1; }

function showSessionRecap() {
    const elapsed = Math.floor((Date.now() - _sessionData.startTime) / 60000);
    const h = Math.floor(elapsed / 60);
    const m = elapsed % 60;
    const durStr = h > 0 ? h + 'h ' + m + 'min' : m + 'min';

    const ex = document.getElementById('session-recap-modal');
    if (ex) ex.remove();

    const modal = document.createElement('div');
    modal.id = 'session-recap-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:#000c;z-index:10001;display:flex;align-items:flex-end;justify-content:center;';
    modal.innerHTML = `
        <div style="width:92%;max-width:400px;background:linear-gradient(180deg,#0d0d1a,#0a0a12);border:1.5px solid #8a2be244;border-radius:22px 22px 0 0;padding:24px 20px 36px;">
            <div style="text-align:center;margin-bottom:20px;">
                <div style="font-size:2rem;margin-bottom:6px;">🏁</div>
                <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#8a2be2;">RÉCAP DE SESSION</div>
                <div style="font-size:0.72rem;color:#555;margin-top:4px;">${durStr} de révision</div>
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:20px;">
                <div style="background:#0d0d0d;border:1px solid #f1c40f33;border-radius:14px;padding:14px 8px;text-align:center;">
                    <div style="font-size:1.4rem;">⚡</div>
                    <div style="font-size:1.1rem;font-weight:900;color:#f1c40f;margin:4px 0;">+${_sessionData.xp}</div>
                    <div style="font-size:0.6rem;color:#555;">XP</div>
                </div>
                <div style="background:#0d0d0d;border:1px solid #f59e0b33;border-radius:14px;padding:14px 8px;text-align:center;">
                    <div style="font-size:1.4rem;">🪙</div>
                    <div style="font-size:1.1rem;font-weight:900;color:#f59e0b;margin:4px 0;">+${_sessionData.coins}</div>
                    <div style="font-size:0.6rem;color:#555;">Pièces</div>
                </div>
                <div style="background:#0d0d0d;border:1px solid #4ade8033;border-radius:14px;padding:14px 8px;text-align:center;">
                    <div style="font-size:1.4rem;">🎵</div>
                    <div style="font-size:1.1rem;font-weight:900;color:#4ade80;margin:4px 0;">${_sessionData.lessons}</div>
                    <div style="font-size:0.6rem;color:#555;">Leçons</div>
                </div>
            </div>
            <button onclick="document.getElementById('session-recap-modal').remove()" style="width:100%;padding:14px;background:linear-gradient(135deg,#8a2be2,#a855f7);border:none;border-radius:14px;color:#fff;font-size:0.88rem;font-weight:900;cursor:pointer;">Continuer 💪</button>
        </div>
    `;
    document.body.appendChild(modal);
    modal.addEventListener('click', function(e) { if (e.target === modal) modal.remove(); });
}

// ═══════════════════════════════════════════════════════════════
// 🃏 FLASHCARDS CITATIONS (swipe)
// ═══════════════════════════════════════════════════════════════
function showFlashcardsCitations() {
    // Collecte toutes les citations de ORACLE_DATA
    var allCards = [];
    if (typeof ORACLE_DATA !== 'undefined') {
        ORACLE_DATA.forEach(function(philo) {
            (philo.notions || []).forEach(function(notion) {
                (notion.citations || []).forEach(function(c) {
                    allCards.push({
                        front: c.citation,
                        back: c.explication || '',
                        auteur: philo.nom,
                        notion: notion.nom,
                        oeuvre: c.oeuvre || '',
                        bac: c.bac || ''
                    });
                });
            });
        });
    }
    // Shuffle
    for (var i = allCards.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = allCards[i]; allCards[i] = allCards[j]; allCards[j] = tmp;
    }
    allCards = allCards.slice(0, 40); // max 40 cartes par session

    var idx = 0;
    var revealed = false;
    var known = 0;
    var unknown = 0;

    var ex = document.getElementById('flashcards-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'flashcards-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#060608;display:flex;flex-direction:column;align-items:center;padding:16px 16px 32px;overflow:hidden;';

    function renderCard() {
        if (idx >= allCards.length) {
            modal.innerHTML = `
                <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;text-align:center;gap:16px;">
                    <div style="font-size:2.5rem;">🎉</div>
                    <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#8a2be2;">SESSION TERMINÉE</div>
                    <div style="font-size:0.85rem;color:#fff;font-weight:800;">${known} connues · ${unknown} à revoir</div>
                    <div style="display:flex;gap:8px;margin-top:8px;">
                        <button onclick="showFlashcardsCitations()" style="padding:12px 20px;background:#8a2be2;border:none;border-radius:14px;color:#fff;font-size:0.82rem;font-weight:800;cursor:pointer;">🔄 Rejouer</button>
                        <button onclick="document.getElementById('flashcards-modal').remove()" style="padding:12px 20px;background:#1a1a1a;border:1px solid #333;border-radius:14px;color:#888;font-size:0.82rem;cursor:pointer;">Fermer</button>
                    </div>
                </div>`;
            return;
        }
        var card = allCards[idx];
        revealed = false;

        modal.innerHTML = `
            <div style="width:100%;max-width:420px;display:flex;flex-direction:column;height:100%;">
                <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
                    <button onclick="document.getElementById('flashcards-modal').remove()" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
                    <div style="font-size:0.65rem;color:#555;">${idx + 1} / ${allCards.length}</div>
                    <div style="font-size:0.65rem;color:#4ade80;">✓ ${known} &nbsp; <span style="color:#ef4444;">✗ ${unknown}</span></div>
                </div>
                <div style="width:100%;height:4px;background:#1a1a1a;border-radius:2px;margin-bottom:20px;">
                    <div style="height:4px;background:#8a2be2;border-radius:2px;width:${(idx/allCards.length*100).toFixed(0)}%;transition:width 0.3s;"></div>
                </div>
                <div id="fc-card" style="flex:1;background:#0d0d1a;border:1.5px solid #8a2be244;border-radius:22px;padding:24px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;cursor:pointer;position:relative;touch-action:pan-y;" onclick="_fcReveal()">
                    <div style="font-size:0.58rem;font-weight:900;letter-spacing:1.5px;color:#8a2be2;margin-bottom:12px;">${card.auteur.toUpperCase()} · ${card.notion.toUpperCase()}</div>
                    <div style="font-size:0.95rem;font-style:italic;color:#fff;line-height:1.6;margin-bottom:12px;">"${card.front}"</div>
                    ${card.oeuvre ? `<div style="font-size:0.65rem;color:#555;">${card.oeuvre}</div>` : ''}
                    <div id="fc-back" style="display:none;margin-top:16px;border-top:1px solid #1a1a2e;padding-top:16px;width:100%;">
                        <div style="font-size:0.72rem;color:#ccc;line-height:1.7;">${card.back}</div>
                        ${card.bac ? `<div style="font-size:0.65rem;color:#8a2be2;margin-top:10px;font-style:italic;">${card.bac}</div>` : ''}
                    </div>
                    <div id="fc-tap-hint" style="font-size:0.62rem;color:#333;margin-top:16px;">Tape pour voir l'explication</div>
                </div>
                <div id="fc-btns" style="display:none;gap:12px;margin-top:16px;width:100%;">
                    <div style="display:flex;gap:10px;">
                        <button onclick="_fcAnswer(false)" style="flex:1;padding:14px;background:#1a0505;border:1.5px solid #ef4444;border-radius:14px;color:#ef4444;font-size:0.85rem;font-weight:900;cursor:pointer;">✗ À revoir</button>
                        <button onclick="_fcAnswer(true)" style="flex:1;padding:14px;background:#051a05;border:1.5px solid #4ade80;border-radius:14px;color:#4ade80;font-size:0.85rem;font-weight:900;cursor:pointer;">✓ Je sais</button>
                    </div>
                    <div style="font-size:0.62rem;color:#333;text-align:center;margin-top:4px;">← Glisse pour répondre</div>
                </div>
            </div>`;

        // Swipe support
        var startX = 0;
        var cardEl = document.getElementById('fc-card');
        if (cardEl) {
            cardEl.addEventListener('touchstart', function(e) { startX = e.touches[0].clientX; }, { passive: true });
            cardEl.addEventListener('touchend', function(e) {
                if (!revealed) { _fcReveal(); return; }
                var dx = e.changedTouches[0].clientX - startX;
                if (dx > 70) _fcAnswer(true);
                else if (dx < -70) _fcAnswer(false);
            }, { passive: true });
        }
    }

    window._fcReveal = function() {
        revealed = true;
        var back = document.getElementById('fc-back');
        var hint = document.getElementById('fc-tap-hint');
        var btns = document.getElementById('fc-btns');
        if (back) back.style.display = 'block';
        if (hint) hint.style.display = 'none';
        if (btns) btns.style.display = 'flex';
    };

    window._fcAnswer = function(ok) {
        if (ok) known++; else unknown++;
        idx++;
        renderCard();
    };

    document.body.appendChild(modal);
    renderCard();
}

// ═══════════════════════════════════════════════════════════════
// 🔗 LIENS ENTRE NOTIONS (auteurs communs)
// ═══════════════════════════════════════════════════════════════
function showLiensNotions() {
    // Construit la carte auteur → notions/matières
    var auteurMap = {};

    // Depuis lessonsData
    if (typeof lessonsData !== 'undefined') {
        lessonsData.forEach(function(l) {
            if (!l.author) return;
            var key = l.author.toLowerCase().trim();
            if (!auteurMap[key]) auteurMap[key] = { nom: l.author, matieres: {}, notions: new Set() };
            auteurMap[key].matieres[l.subject || ''] = true;
            if (l.category) auteurMap[key].notions.add(l.category);
        });
    }
    // Depuis ORACLE_DATA (philosophes)
    if (typeof ORACLE_DATA !== 'undefined') {
        ORACLE_DATA.forEach(function(philo) {
            var key = philo.nom.toLowerCase().trim();
            if (!auteurMap[key]) auteurMap[key] = { nom: philo.nom, matieres: {}, notions: new Set() };
            auteurMap[key].matieres['philo'] = true;
            (philo.notions || []).forEach(function(n) { auteurMap[key].notions.add(n.nom); });
        });
    }

    // Garder seulement ceux qui apparaissent dans 2+ matières ou 3+ notions
    var multiAuteurs = Object.values(auteurMap).filter(function(a) {
        return Object.keys(a.matieres).length >= 2 || a.notions.size >= 3;
    }).sort(function(a, b) {
        return (Object.keys(b.matieres).length + b.notions.size) - (Object.keys(a.matieres).length + a.notions.size);
    }).slice(0, 30);

    var subjectColors = { 'philo': '#a78bfa', 'français': '#f87171', 'histoire': '#f97316', 'histoire-geo': '#f97316', 'maths': '#22c55e', 'géographie': '#34d399' };

    var ex = document.getElementById('liens-notions-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'liens-notions-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#060608;display:flex;flex-direction:column;overflow:hidden;';
    modal.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;padding:16px 16px 0;flex-shrink:0;">
            <button onclick="document.getElementById('liens-notions-modal').remove()" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
            <div>
                <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#06b6d4;">🔗 LIENS ENTRE NOTIONS</div>
                <div style="font-size:0.68rem;color:#555;">Auteurs présents dans plusieurs matières</div>
            </div>
        </div>
        <div style="flex:1;overflow-y:auto;padding:16px;">
            ${multiAuteurs.length === 0 ? '<div style="text-align:center;color:#555;padding:40px;">Aucun lien trouvé</div>' :
            multiAuteurs.map(function(a) {
                var matieresBadges = Object.keys(a.matieres).map(function(m) {
                    var col = subjectColors[m] || '#888';
                    return '<span style="font-size:0.58rem;font-weight:800;color:' + col + ';background:' + col + '22;border-radius:6px;padding:2px 7px;">' + (m||'?').toUpperCase() + '</span>';
                }).join(' ');
                var notionsList = Array.from(a.notions).slice(0, 5).join(' · ');
                return '<div style="background:#0d0d0d;border:1px solid #1a1a2e;border-radius:14px;padding:14px;margin-bottom:10px;">' +
                    '<div style="font-size:0.82rem;font-weight:900;color:#fff;margin-bottom:6px;">' + a.nom + '</div>' +
                    '<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:6px;">' + matieresBadges + '</div>' +
                    (notionsList ? '<div style="font-size:0.65rem;color:#555;">' + notionsList + '</div>' : '') +
                    '</div>';
            }).join('')}
        </div>
    `;
    document.body.appendChild(modal);
}

// ═══════════════════════════════════════════════════════════════
// 🏅 BADGES DE MAÎTRISE PAR NOTION
// ═══════════════════════════════════════════════════════════════
function _getBadgeMaitrise(pct) {
    if (pct >= 100) return { label: 'Expert', emoji: '🏆', color: '#f1c40f' };
    if (pct >= 75)  return { label: 'Avancé', emoji: '💎', color: '#06b6d4' };
    if (pct >= 50)  return { label: 'Confirmé', emoji: '⭐', color: '#a855f7' };
    if (pct >= 25)  return { label: 'Débutant', emoji: '📗', color: '#4ade80' };
    return { label: 'Novice', emoji: '🌱', color: '#555' };
}

function showBadgesMaitrise() {
    var completed = JSON.parse(localStorage.getItem('completedLessons') || '[]');
    var account = _safeGet('userAccount', {});
    var classeEleve = (account.classe || 'terminale').toLowerCase();

    // Groupe les leçons par matière/notion
    var subjectMap = {};
    if (typeof lessonsData !== 'undefined') {
        lessonsData.forEach(function(l) {
            var gradeOk = !l.grade || l.grade.toLowerCase() === classeEleve;
            if (!gradeOk) return;
            var key = l.subject || 'autre';
            if (!subjectMap[key]) subjectMap[key] = { total: 0, done: 0, label: key };
            subjectMap[key].total++;
            if (completed.includes(l.id)) subjectMap[key].done++;
        });
    }

    var subjectColors = { 'philo': '#a78bfa', 'français': '#f87171', 'histoire': '#f97316', 'histoire-geo': '#f97316', 'maths': '#22c55e', 'géographie': '#34d399' };
    var subjectLabels = { 'philo': 'Philosophie', 'français': 'Français', 'histoire': 'Histoire', 'histoire-geo': 'Histoire-Géo', 'maths': 'Maths', 'géographie': 'Géographie' };

    var ex = document.getElementById('badges-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'badges-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#060608;display:flex;flex-direction:column;overflow:hidden;';
    modal.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;padding:16px 16px 0;flex-shrink:0;">
            <button onclick="document.getElementById('badges-modal').remove()" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
            <div>
                <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#f1c40f;">🏅 BADGES DE MAÎTRISE</div>
                <div style="font-size:0.68rem;color:#555;">Ta progression par matière</div>
            </div>
        </div>
        <div style="flex:1;overflow-y:auto;padding:16px;">
            ${Object.values(subjectMap).map(function(s) {
                var pct = s.total > 0 ? Math.round(s.done / s.total * 100) : 0;
                var badge = _getBadgeMaitrise(pct);
                var col = subjectColors[s.label] || '#888';
                var label = subjectLabels[s.label] || s.label;
                return '<div style="background:#0d0d0d;border:1px solid ' + col + '33;border-radius:16px;padding:16px;margin-bottom:10px;">' +
                    '<div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;">' +
                        '<div style="font-size:1.6rem;">' + badge.emoji + '</div>' +
                        '<div style="flex:1;">' +
                            '<div style="font-size:0.82rem;font-weight:900;color:#fff;">' + label + '</div>' +
                            '<div style="font-size:0.65rem;font-weight:800;color:' + badge.color + ';">' + badge.label + '</div>' +
                        '</div>' +
                        '<div style="font-size:1.1rem;font-weight:900;color:' + col + ';">' + pct + '%</div>' +
                    '</div>' +
                    '<div style="height:6px;background:#1a1a1a;border-radius:3px;">' +
                        '<div style="height:6px;background:' + col + ';border-radius:3px;width:' + pct + '%;transition:width 0.6s ease;"></div>' +
                    '</div>' +
                    '<div style="font-size:0.6rem;color:#555;margin-top:6px;">' + s.done + ' / ' + s.total + ' leçons</div>' +
                '</div>';
            }).join('')}
        </div>
    `;
    document.body.appendChild(modal);
}


// ═══════════════════════════════════════════════════════════════
// 🍅 POMODORO
// ═══════════════════════════════════════════════════════════════
var _pomodoroInterval = null;
var _pomodoroState = { phase: 'work', remaining: 25*60, session: 0, paused: true };

function showPomodoro() {
    var ex = document.getElementById('pomodoro-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'pomodoro-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9998;background:#060608;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;';

    function render() {
        var s = _pomodoroState;
        var isWork = s.phase === 'work';
        var col = isWork ? '#ef4444' : '#4ade80';
        var total = isWork ? 25*60 : 5*60;
        var pct = (s.remaining / total) * 100;
        var m = Math.floor(s.remaining / 60);
        var sec = s.remaining % 60;
        var timeStr = String(m).padStart(2,'0') + ':' + String(sec).padStart(2,'0');
        var circ = 2 * Math.PI * 88; // 553
        var offset = circ * (1 - pct/100);

        modal.innerHTML = `
            <div style="width:100%;max-width:360px;text-align:center;">
                <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:24px;">
                    <button onclick="document.getElementById('pomodoro-modal').remove();if(_pomodoroInterval){clearInterval(_pomodoroInterval);_pomodoroInterval=null;}" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
                    <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:${col};">🍅 POMODORO</div>
                    <div style="font-size:0.65rem;color:#555;">Session ${s.session}</div>
                </div>

                <div style="font-size:0.72rem;font-weight:800;color:${col};letter-spacing:1px;margin-bottom:16px;">${isWork ? '🔥 TRAVAIL' : '😮‍💨 PAUSE'}</div>

                <div style="position:relative;width:200px;height:200px;margin:0 auto 28px;">
                    <svg width="200" height="200" style="position:absolute;top:0;left:0;transform:rotate(-90deg);">
                        <circle cx="100" cy="100" r="88" fill="none" stroke="#1a1a1a" stroke-width="10"/>
                        <circle cx="100" cy="100" r="88" fill="none" stroke="${col}" stroke-width="10"
                            stroke-dasharray="${circ.toFixed(0)}" stroke-dashoffset="${offset.toFixed(0)}" style="transition:stroke-dashoffset 1s linear;"/>
                    </svg>
                    <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;">
                        <div style="font-size:2.6rem;font-weight:900;color:#fff;font-variant-numeric:tabular-nums;">${timeStr}</div>
                        <div style="font-size:0.62rem;color:#555;margin-top:4px;">${isWork ? '25 min focus' : '5 min repos'}</div>
                    </div>
                </div>

                <div style="display:flex;gap:12px;justify-content:center;margin-bottom:24px;">
                    <button onclick="_pomodoroToggle()" style="padding:14px 32px;background:${col}22;border:1.5px solid ${col};border-radius:16px;color:${col};font-size:0.9rem;font-weight:900;cursor:pointer;">${s.paused ? '▶️ Démarrer' : '⏸️ Pause'}</button>
                    <button onclick="_pomodoroReset()" style="padding:14px 18px;background:#1a1a1a;border:1px solid #333;border-radius:16px;color:#555;font-size:0.9rem;cursor:pointer;">↺</button>
                </div>

                <div style="background:#0d0d0d;border:1px solid #1a1a1a;border-radius:14px;padding:14px;">
                    <div style="font-size:0.58rem;color:#555;font-weight:700;letter-spacing:1px;margin-bottom:8px;">TECHNIQUE POMODORO</div>
                    <div style="font-size:0.7rem;color:#444;line-height:1.8;">
                        🔥 <b style="color:#aaa;">25 min</b> de travail concentré<br>
                        😌 <b style="color:#aaa;">5 min</b> de pause obligatoire<br>
                        🏆 Après 4 sessions → pause 15min
                    </div>
                </div>
            </div>
        `;
    }

    window._pomodoroToggle = function() {
        _pomodoroState.paused = !_pomodoroState.paused;
        if (!_pomodoroState.paused) {
            _pomodoroInterval = setInterval(function() {
                _pomodoroState.remaining--;
                if (_pomodoroState.remaining <= 0) {
                    if (_pomodoroState.phase === 'work') {
                        _pomodoroState.session++;
                        _pomodoroState.phase = 'break';
                        _pomodoroState.remaining = 5*60;
                        showToast('🎉 Session terminée ! Pause 5 min 😌');
                        if (Notification.permission === 'granted') new Notification('MusicSchool 🍅', { body: 'Session terminée ! Pause méritée 😌' });
                        if (typeof awardXP === 'function') awardXP(15, 'Pomodoro complété 🍅');
                    } else {
                        _pomodoroState.phase = 'work';
                        _pomodoroState.remaining = 25*60;
                        showToast('🔥 Pause terminée — On reprend !');
                        if (Notification.permission === 'granted') new Notification('MusicSchool 🍅', { body: 'Pause terminée — Retour au travail ! 🔥' });
                    }
                }
                render();
            }, 1000);
        } else {
            clearInterval(_pomodoroInterval); _pomodoroInterval = null;
        }
        render();
    };

    window._pomodoroReset = function() {
        clearInterval(_pomodoroInterval); _pomodoroInterval = null;
        _pomodoroState = { phase: 'work', remaining: 25*60, session: _pomodoroState.session, paused: true };
        render();
    };

    document.body.appendChild(modal);
    render();
}

// ═══════════════════════════════════════════════════════════════
// 📝 EXAMEN BLANC
// ═══════════════════════════════════════════════════════════════
function showExamenBlanc() {
    // Collecte 20 questions aléatoires de toutes les matières
    var account = _safeGet('userAccount', {});
    var classeEleve = (account.classe || 'terminale').toLowerCase();
    var allQ = [];

    if (typeof lessonsData !== 'undefined') {
        lessonsData.forEach(function(l) {
            var gradeOk = !l.grade || l.grade.toLowerCase() === classeEleve;
            if (!gradeOk || !l.quiz || !l.quiz.length) return;
            l.quiz.forEach(function(q) {
                if (q.q && q.choices && q.choices.length >= 2 && typeof q.answer !== 'undefined') {
                    allQ.push({ q: q.q, choices: q.choices, answer: q.answer, subject: l.subject, lessonTitle: l.title });
                }
            });
        });
    }

    // Shuffle + prendre 20
    for (var i = allQ.length - 1; i > 0; i--) { var j = Math.floor(Math.random()*(i+1)); var t=allQ[i]; allQ[i]=allQ[j]; allQ[j]=t; }
    allQ = allQ.slice(0, 20);

    var idx = 0;
    var score = 0;
    var answers = [];
    var timeLeft = 30; // 30 sec par question
    var qTimer = null;
    var subjectColors = { philo:'#a78bfa', français:'#f87171', histoire:'#f97316', maths:'#22c55e', géographie:'#34d399' };

    var ex = document.getElementById('examen-blanc-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'examen-blanc-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#060608;display:flex;flex-direction:column;overflow:hidden;';

    function startTimer() {
        timeLeft = 30;
        if (qTimer) clearInterval(qTimer);
        qTimer = setInterval(function() {
            timeLeft--;
            var el = document.getElementById('eb-timer');
            var bar = document.getElementById('eb-timer-bar');
            if (el) { el.innerText = timeLeft + 's'; el.style.color = timeLeft <= 10 ? '#ef4444' : '#f59e0b'; }
            if (bar) bar.style.width = (timeLeft/30*100) + '%';
            if (timeLeft <= 0) { clearInterval(qTimer); _ebAnswer(-1); }
        }, 1000);
    }

    function renderQ() {
        if (idx >= allQ.length) { showResults(); return; }
        var q = allQ[idx];
        var col = subjectColors[q.subject] || '#888';
        modal.innerHTML = `
            <div style="display:flex;flex-direction:column;height:100%;padding:16px;">
                <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;flex-shrink:0;">
                    <button onclick="if(qTimer)clearInterval(qTimer);document.getElementById('examen-blanc-modal').remove()" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
                    <div style="font-size:0.65rem;color:#555;">${idx+1} / ${allQ.length}</div>
                    <div id="eb-timer" style="font-size:0.85rem;font-weight:900;color:#f59e0b;">30s</div>
                </div>
                <div style="height:4px;background:#1a1a1a;border-radius:2px;margin-bottom:12px;flex-shrink:0;">
                    <div id="eb-timer-bar" style="height:4px;background:#f59e0b;border-radius:2px;width:100%;transition:width 1s linear;"></div>
                </div>
                <div style="height:3px;background:#1a1a1a;border-radius:2px;margin-bottom:16px;flex-shrink:0;">
                    <div style="height:3px;background:#8a2be2;border-radius:2px;width:${(idx/allQ.length*100).toFixed(0)}%;"></div>
                </div>
                <div style="flex:1;display:flex;flex-direction:column;justify-content:center;">
                    <div style="font-size:0.58rem;font-weight:800;color:${col};letter-spacing:1.5px;margin-bottom:12px;">${(q.subject||'').toUpperCase()}</div>
                    <div style="font-size:0.92rem;font-weight:800;color:#fff;line-height:1.5;margin-bottom:24px;">${q.q}</div>
                    <div style="display:flex;flex-direction:column;gap:10px;">
                        ${q.choices.map((c,ci) => `<button onclick="_ebAnswer(${ci})" style="padding:13px 16px;background:#0d0d0d;border:1.5px solid #1a1a2e;border-radius:14px;color:#ccc;font-size:0.82rem;text-align:left;cursor:pointer;font-family:inherit;">${c}</button>`).join('')}
                    </div>
                </div>
            </div>`;
        startTimer();
    }

    window._ebAnswer = function(chosen) {
        if (qTimer) clearInterval(qTimer);
        var q = allQ[idx];
        var correct = chosen === q.answer;
        if (correct) score++;
        answers.push({ q: q.q, chosen: chosen, correct: correct, correctIdx: q.answer, subject: q.subject });

        // Flash feedback
        var btns = modal.querySelectorAll('button[onclick^="_ebAnswer"]');
        btns.forEach(function(b, i) {
            if (i === q.answer) b.style.background = '#052405', b.style.borderColor = '#4ade80', b.style.color = '#4ade80';
            else if (i === chosen && !correct) b.style.background = '#240505', b.style.borderColor = '#ef4444', b.style.color = '#ef4444';
        });
        setTimeout(function() { idx++; renderQ(); }, 700);
    };

    function showResults() {
        var pct = Math.round(score / allQ.length * 100);
        var mention = pct >= 90 ? { t: 'Excellent !', c: '#f1c40f', e: '🏆' } : pct >= 75 ? { t: 'Bien !', c: '#4ade80', e: '⭐' } : pct >= 60 ? { t: 'Assez bien', c: '#f59e0b', e: '👍' } : pct >= 50 ? { t: 'Passable', c: '#f97316', e: '😅' } : { t: 'À revoir', c: '#ef4444', e: '📚' };
        var xpGained = score * 10;
        if (typeof awardXP === 'function') awardXP(xpGained, 'Examen blanc 📝');
        if (typeof awardCoins === 'function') awardCoins(score * 3, 'Examen blanc');

        modal.innerHTML = `
            <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;padding:24px;text-align:center;gap:12px;">
                <div style="font-size:2.5rem;">${mention.e}</div>
                <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#8a2be2;">RÉSULTATS EXAMEN BLANC</div>
                <div style="font-size:3rem;font-weight:900;color:${mention.c};">${score}<span style="font-size:1.2rem;color:#555;">/${allQ.length}</span></div>
                <div style="font-size:1rem;font-weight:800;color:${mention.c};">${mention.t}</div>
                <div style="font-size:0.75rem;color:#555;">${pct}% de réussite · +${xpGained} XP</div>
                <div style="width:100%;background:#0d0d0d;border:1px solid #1a1a1a;border-radius:14px;padding:12px;max-height:200px;overflow-y:auto;text-align:left;margin-top:8px;">
                    ${answers.map(function(a) {
                        return '<div style="font-size:0.68rem;padding:6px 0;border-bottom:1px solid #111;color:' + (a.correct ? '#4ade80' : '#ef4444') + ';">' + (a.correct ? '✓' : '✗') + ' <span style="color:#888;">' + (a.subject||'') + '</span> — ' + a.q.substring(0,60) + (a.q.length>60?'…':'') + '</div>';
                    }).join('')}
                </div>
                <div style="display:flex;gap:10px;margin-top:8px;">
                    <button onclick="showExamenBlanc()" style="flex:1;padding:13px;background:#8a2be2;border:none;border-radius:14px;color:#fff;font-size:0.82rem;font-weight:900;cursor:pointer;">🔄 Recommencer</button>
                    <button onclick="document.getElementById('examen-blanc-modal').remove()" style="padding:13px 18px;background:#1a1a1a;border:1px solid #333;border-radius:14px;color:#666;font-size:0.82rem;cursor:pointer;">Fermer</button>
                </div>
            </div>`;
    }

    document.body.appendChild(modal);
    renderQ();
}

// ═══════════════════════════════════════════════════════════════
// ❌ HISTORIQUE DES ERREURS
// ═══════════════════════════════════════════════════════════════
function showHistoriqueErreurs() {
    var wrongAnswers = JSON.parse(localStorage.getItem('ms_wrong_answers') || '{}');
    var subjectColors = { philo:'#a78bfa', français:'#f87171', histoire:'#f97316', maths:'#22c55e', géographie:'#34d399' };
    var subjectLabels = { philo:'Philosophie', français:'Français', histoire:'Histoire', maths:'Maths', géographie:'Géographie' };

    var ex = document.getElementById('erreurs-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'erreurs-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#060608;display:flex;flex-direction:column;overflow:hidden;';

    var total = Object.values(wrongAnswers).reduce(function(a,b) { return a + Object.keys(b).length; }, 0);

    var content = '';
    if (total === 0) {
        content = '<div style="text-align:center;padding:60px 20px;"><div style="font-size:2rem;margin-bottom:12px;">🎉</div><div style="font-size:0.85rem;color:#555;">Aucune erreur enregistrée !<br>Fais des quiz pour voir tes points faibles.</div></div>';
    } else {
        content = Object.keys(wrongAnswers).map(function(subj) {
            var questions = wrongAnswers[subj];
            var col = subjectColors[subj] || '#888';
            var label = subjectLabels[subj] || subj;
            var qList = Object.keys(questions).map(function(q) {
                return '<div style="font-size:0.72rem;color:#ccc;padding:8px 0;border-bottom:1px solid #111;display:flex;align-items:flex-start;gap:8px;"><span style="color:#ef4444;flex-shrink:0;">✗</span><div><div>' + q + '</div><div style="font-size:0.62rem;color:#ef4444;margin-top:2px;">' + questions[q] + ' erreur(s)</div></div></div>';
            }).join('');
            return '<div style="background:#0d0d0d;border:1px solid ' + col + '33;border-radius:14px;padding:14px;margin-bottom:10px;">' +
                '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">' +
                '<div style="font-size:0.72rem;font-weight:900;color:' + col + ';">' + label + ' — ' + Object.keys(questions).length + ' erreur(s)</div>' +
                '<button onclick="clearWrongAnswers(\'' + subj + '\');showHistoriqueErreurs();" style="font-size:0.6rem;color:#555;background:transparent;border:1px solid #333;border-radius:8px;padding:3px 8px;cursor:pointer;">Effacer</button>' +
                '</div>' + qList + '</div>';
        }).join('');
    }

    modal.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;padding:16px 16px 0;flex-shrink:0;">
            <button onclick="document.getElementById('erreurs-modal').remove()" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
            <div>
                <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#ef4444;">❌ HISTORIQUE DES ERREURS</div>
                <div style="font-size:0.68rem;color:#555;">${total} question(s) à retravailler</div>
            </div>
        </div>
        <div style="flex:1;overflow-y:auto;padding:16px;">${content}</div>
        ${total > 0 ? '<div style="padding:0 16px 24px;flex-shrink:0;"><button onclick="localStorage.removeItem(\'ms_wrong_answers\');showHistoriqueErreurs();" style="width:100%;padding:12px;background:#1a0505;border:1px solid #ef444444;border-radius:14px;color:#ef4444;font-size:0.82rem;font-weight:800;cursor:pointer;">🗑️ Tout effacer</button></div>' : ''}
    `;
    document.body.appendChild(modal);
}


// ═══════════════════════════════════════════════════════════════
// 🤖 IA — GÉNÉRATION AUTOMATIQUE DES DATES D'EXAMEN PAR PAYS
// ═══════════════════════════════════════════════════════════════

var _AI_DATES_KEY = 'ms_ai_exam_dates_generated';

// Déclenché au login si dates pas encore générées pour ce pays/année
function _checkAndGenerateAIDates() {
    try {
        var account = _safeGet('userAccount', {});
        if (!account || !account.pays || !account.classe) return;

        var year = new Date().getFullYear();
        var stored = JSON.parse(localStorage.getItem(_AI_DATES_KEY) || '{}');

        // Déjà généré pour ce pays cette année
        if (stored.pays === account.pays && stored.year === year) return;

        // Dates perso déjà remplies manuellement → ne pas écraser
        var custom = _getCustomExamDates ? _getCustomExamDates() : [];
        if (custom.length > 0) return;

        // Générer après 4 secondes pour ne pas bloquer le chargement
        setTimeout(function() {
            _generateAIExamDates(account.pays, account.classe, account.serie || '', year);
        }, 4000);

    } catch(e) {}
}

async function _generateAIExamDates(pays, classe, serie, year) {
    try {
        var paysLabels = {
            'cote-divoire': "Côte d'Ivoire", 'senegal': 'Sénégal', 'mali': 'Mali',
            'cameroun': 'Cameroun', 'france': 'France', 'maroc': 'Maroc',
            'algerie': 'Algérie', 'tunisie': 'Tunisie', 'burkina-faso': 'Burkina Faso',
            'guinea': 'Guinée', 'togo': 'Togo', 'benin': 'Bénin', 'niger': 'Niger',
            'gabon': 'Gabon', 'congo': 'Congo', 'madagascar': 'Madagascar',
            'rdc': 'République Démocratique du Congo', 'rwanda': 'Rwanda'
        };
        var paysLabel = paysLabels[pays] || pays;

        var prompt = `Tu es un expert du système éducatif africain et francophone. 
L'élève est en ${classe}${serie ? ' série ' + serie : ''} en ${paysLabel} pour l'année ${year}.

Génère les dates approximatives des épreuves du Baccalauréat ${year} pour ce pays et cette classe.
Base-toi sur les calendriers habituels de ce pays (qui varient peu d'une année à l'autre).

Réponds UNIQUEMENT en JSON valide, sans aucun texte avant ou après, sans backticks :
[
  {"matiere": "Nom de l'épreuve", "emoji": "emoji", "date": "YYYY-MM-DD", "type": "oral|ecrit|pratique"},
  ...
]

Important :
- Mets les 4-6 épreuves principales seulement
- Les dates doivent être dans l'année ${year}
- Si tu n'es pas sûr d'une date précise, donne une date approximative réaliste
- Ajoute une note dans le dernier objet : {"note": "Dates approximatives — vérifiez sur le site officiel du Ministère"}`;

        var response = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: 'claude-sonnet-4-20250514',
                max_tokens: 1000,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        var data = await response.json();
        var text = (data.content || []).map(function(b) { return b.text || ''; }).join('');
        text = text.replace(/```json|```/g, '').trim();
        var parsed = JSON.parse(text);

        // Extraire la note si présente
        var note = '';
        var dates = parsed.filter(function(d) {
            if (d.note) { note = d.note; return false; }
            return d.matiere && d.date;
        });

        if (dates.length === 0) return;

        // Sauvegarder comme dates perso
        if (typeof _saveCustomExamDates === 'function') {
            _saveCustomExamDates(dates.map(function(d) {
                return { matiere: d.matiere, emoji: d.emoji || '📅', date: d.date, color: d.type === 'oral' ? '#a78bfa' : d.type === 'pratique' ? '#4ade80' : '#38bdf8' };
            }));
        }

        // Marquer comme généré
        localStorage.setItem(_AI_DATES_KEY, JSON.stringify({ pays: pays, year: new Date().getFullYear() }));

        // Afficher la bannière de confirmation
        _showAIDatesConfirmation(dates, paysLabel, note);

    } catch(e) {
        console.log('AI dates error:', e);
    }
}

function _showAIDatesConfirmation(dates, paysLabel, note) {
    var ex = document.getElementById('ai-dates-banner');
    if (ex) ex.remove();

    var banner = document.createElement('div');
    banner.id = 'ai-dates-banner';
    banner.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);width:90%;max-width:380px;background:linear-gradient(135deg,#0d1a2e,#0a1020);border:1.5px solid #38bdf244;border-radius:18px;padding:16px 18px;z-index:9999;box-shadow:0 8px 32px #0008;';

    var datesHTML = dates.slice(0, 4).map(function(d) {
        var dateStr = new Date(d.date).toLocaleDateString('fr-FR', { day: 'numeric', month: 'long' });
        return '<div style="display:flex;justify-content:space-between;font-size:0.68rem;padding:4px 0;border-bottom:1px solid #1a1a2e;"><span style="color:#ccc;">' + (d.emoji || '📅') + ' ' + d.matiere + '</span><span style="color:#38bdf8;font-weight:700;">' + dateStr + '</span></div>';
    }).join('');

    banner.innerHTML = `
        <div style="font-size:0.58rem;font-weight:900;letter-spacing:2px;color:#38bdf8;margin-bottom:8px;">🤖 DATES GÉNÉRÉES PAR L'IA</div>
        <div style="font-size:0.72rem;color:#888;margin-bottom:10px;">${paysLabel} · Bac ${new Date().getFullYear()}</div>
        ${datesHTML}
        ${note ? '<div style="font-size:0.6rem;color:#f59e0b;margin-top:8px;font-style:italic;">⚠️ ' + note + '</div>' : ''}
        <div style="display:flex;gap:8px;margin-top:12px;">
            <button onclick="_confirmAIDates()" style="flex:1;padding:10px;background:#38bdf222;border:1.5px solid #38bdf8;border-radius:12px;color:#38bdf8;font-size:0.75rem;font-weight:800;cursor:pointer;">✅ C'est bon</button>
            <button onclick="showExamDatesConfig();document.getElementById('ai-dates-banner').remove()" style="flex:1;padding:10px;background:#111;border:1px solid #333;border-radius:12px;color:#666;font-size:0.75rem;cursor:pointer;">✏️ Modifier</button>
            <button onclick="document.getElementById('ai-dates-banner').remove()" style="padding:10px 12px;background:transparent;border:none;color:#444;font-size:0.75rem;cursor:pointer;">✕</button>
        </div>
    `;
    document.body.appendChild(banner);

    // Auto-fermeture après 20 secondes
    setTimeout(function() {
        var el = document.getElementById('ai-dates-banner');
        if (el) el.remove();
    }, 20000);
}

window._confirmAIDates = function() {
    var el = document.getElementById('ai-dates-banner');
    if (el) el.remove();
    showToast('✅ Dates confirmées ! Compte à rebours mis à jour.');
};


// ═══════════════════════════════════════════════════════════════
// 📥 TÉLÉCHARGEMENT OFFLINE (PWA uniquement)
// ═══════════════════════════════════════════════════════════════
var _OFFLINE_CACHE = 'musicschool-offline-v1';
var _MAX_FREE_DOWNLOADS = 5;

function _isPWA() {
    return window.matchMedia('(display-mode: standalone)').matches
        || window.navigator.standalone === true;
}

function _getOfflineList() {
    try { return JSON.parse(localStorage.getItem('ms_offline_lessons') || '[]'); }
    catch(e) { return []; }
}

function _saveOfflineList(list) {
    localStorage.setItem('ms_offline_lessons', JSON.stringify(list));
}

function isLessonOffline(lessonId) {
    return _getOfflineList().includes(lessonId);
}

async function downloadLesson(lessonId) {
    // Vérif PWA
    if (!_isPWA()) {
        showToast('📱 Installe l\'app pour télécharger les sons offline !');
        return;
    }

    var lesson = lessonsData.find(function(l) { return l.id === lessonId; });
    if (!lesson || !lesson.audio) { showToast('⚠️ Son introuvable'); return; }

    var offlineList = _getOfflineList();

    // Déjà téléchargé
    if (offlineList.includes(lessonId)) {
        _showRemoveOfflineConfirm(lessonId, lesson.title);
        return;
    }

    // Limite gratuite
    var account = _safeGet('userAccount', {});
    var isPremium = account.premium || false;
    if (!isPremium && offlineList.length >= _MAX_FREE_DOWNLOADS) {
        _showOfflineLimitModal();
        return;
    }

    // Télécharger
    try {
        var btn = document.getElementById('dl-btn-' + lessonId);
        if (btn) { btn.innerHTML = '<i class="fas fa-spinner fa-spin" style="color:#a855f7;"></i>'; }

        var cache = await caches.open(_OFFLINE_CACHE);
        await cache.add(lesson.audio);

        offlineList.push(lessonId);
        _saveOfflineList(offlineList);

        if (btn) { btn.innerHTML = '<i class="fas fa-check-circle" style="color:#4ade80;font-size:17px;"></i>'; }
        showToast('✅ "' + lesson.title + '" disponible offline !');

    } catch(e) {
        var btn2 = document.getElementById('dl-btn-' + lessonId);
        if (btn2) { btn2.innerHTML = '<i class="fas fa-download" style="color:#a855f7;font-size:17px;"></i>'; }
        showToast('❌ Erreur de téléchargement. Vérifie ta connexion.');
    }
}

async function removeOfflineLesson(lessonId) {
    var lesson = lessonsData.find(function(l) { return l.id === lessonId; });
    if (!lesson) return;
    try {
        var cache = await caches.open(_OFFLINE_CACHE);
        await cache.delete(lesson.audio);
    } catch(e) {}
    var list = _getOfflineList().filter(function(id) { return id !== lessonId; });
    _saveOfflineList(list);
    showToast('🗑️ Leçon supprimée du stockage offline');
    // Refresh download button
    var btn = document.getElementById('dl-btn-' + lessonId);
    if (btn) btn.innerHTML = '<i class="fas fa-download" style="color:#a855f7;font-size:17px;"></i>';
}

function _showRemoveOfflineConfirm(lessonId, title) {
    var ex = document.getElementById('offline-confirm');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'offline-confirm';
    modal.style.cssText = 'position:fixed;inset:0;background:#000c;z-index:10001;display:flex;align-items:flex-end;justify-content:center;';
    modal.innerHTML = `
        <div style="width:92%;max-width:400px;background:#0d0d0d;border:1.5px solid #333;border-radius:22px 22px 0 0;padding:20px 18px 32px;">
            <div style="font-size:0.82rem;font-weight:800;color:#fff;margin-bottom:6px;">Supprimer du stockage offline ?</div>
            <div style="font-size:0.72rem;color:#555;margin-bottom:16px;">"${title}"</div>
            <div style="display:flex;gap:10px;">
                <button onclick="removeOfflineLesson(${lessonId});document.getElementById('offline-confirm').remove()" style="flex:1;padding:12px;background:#1a0505;border:1.5px solid #ef4444;border-radius:12px;color:#ef4444;font-size:0.8rem;font-weight:800;cursor:pointer;">🗑️ Supprimer</button>
                <button onclick="document.getElementById('offline-confirm').remove()" style="flex:1;padding:12px;background:#111;border:1px solid #333;border-radius:12px;color:#666;font-size:0.8rem;cursor:pointer;">Annuler</button>
            </div>
        </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', function(e) { if (e.target === modal) modal.remove(); });
}

function _showOfflineLimitModal() {
    var ex = document.getElementById('offline-limit-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'offline-limit-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:#000c;z-index:10001;display:flex;align-items:flex-end;justify-content:center;';
    modal.innerHTML = `
        <div style="width:92%;max-width:400px;background:#0d0d0d;border:1.5px solid #a855f744;border-radius:22px 22px 0 0;padding:24px 18px 36px;text-align:center;">
            <div style="font-size:2rem;margin-bottom:10px;">👑</div>
            <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#a855f7;margin-bottom:8px;">LIMITE ATTEINTE</div>
            <div style="font-size:0.85rem;font-weight:800;color:#fff;margin-bottom:6px;">5 téléchargements gratuits utilisés</div>
            <div style="font-size:0.72rem;color:#555;margin-bottom:20px;">Passe en Premium pour télécharger toutes les leçons sans limite</div>
            <button onclick="document.getElementById('offline-limit-modal').remove()" style="width:100%;padding:13px;background:linear-gradient(135deg,#8a2be2,#a855f7);border:none;border-radius:14px;color:#fff;font-size:0.85rem;font-weight:900;cursor:pointer;">OK compris</button>
        </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', function(e) { if (e.target === modal) modal.remove(); });
}

function showOfflineLessons() {
    var offlineList = _getOfflineList();
    var ex = document.getElementById('offline-modal');
    if (ex) ex.remove();
    var modal = document.createElement('div');
    modal.id = 'offline-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#060608;display:flex;flex-direction:column;overflow:hidden;';

    var lessons = offlineList.map(function(id) {
        return lessonsData.find(function(l) { return l.id === id; });
    }).filter(Boolean);

    var content = lessons.length === 0
        ? '<div style="text-align:center;padding:60px 20px;"><div style="font-size:2rem;margin-bottom:12px;">📥</div><div style="font-size:0.82rem;color:#555;">Aucune leçon téléchargée.<br>Appuie sur ⬇️ dans le player pour sauvegarder.</div></div>'
        : lessons.map(function(l) {
            var subjectColors = { philo:'#a78bfa', français:'#f87171', histoire:'#f97316', maths:'#22c55e' };
            var col = subjectColors[l.subject] || '#888';
            return '<div style="display:flex;align-items:center;gap:12px;background:#0d0d0d;border:1px solid #1a1a2e;border-radius:14px;padding:12px;margin-bottom:8px;">' +
                '<img src="' + l.image + '" style="width:44px;height:44px;border-radius:10px;object-fit:cover;" onerror="_lessonImgError(this,\'' + (l.subject||'') + '\')" />' +
                '<div style="flex:1;">' +
                    '<div style="font-size:0.78rem;font-weight:800;color:#fff;">' + l.title + '</div>' +
                    '<div style="font-size:0.62rem;color:' + col + ';margin-top:2px;">' + (l.subject||'') + ' · ✅ Offline</div>' +
                '</div>' +
                '<button onclick="removeOfflineLesson(' + l.id + ');showOfflineLessons();" style="background:transparent;border:none;color:#ef4444;font-size:1rem;cursor:pointer;">🗑️</button>' +
            '</div>';
        }).join('');

    var account = _safeGet('userAccount', {});
    var isPremium = account.premium || false;
    var used = offlineList.length;
    var max = isPremium ? '∞' : _MAX_FREE_DOWNLOADS;

    modal.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;padding:16px 16px 0;flex-shrink:0;">
            <button onclick="document.getElementById('offline-modal').remove()" style="background:transparent;border:none;color:#555;font-size:1.2rem;cursor:pointer;">✕</button>
            <div style="flex:1;">
                <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#a855f7;">📥 LEÇONS OFFLINE</div>
                <div style="font-size:0.68rem;color:#555;">${used} / ${max} téléchargements utilisés</div>
            </div>
        </div>
        <div style="flex:1;overflow-y:auto;padding:16px;">${content}</div>
    `;
    document.body.appendChild(modal);
}


window.addEventListener('DOMContentLoaded', function() {
    mainGrid = document.getElementById('main-grid');
    if (typeof _checkAndGenerateAIDates === 'function') setTimeout(_checkAndGenerateAIDates, 5000);
    sectionTitle = document.getElementById('section-title');
    if (sectionTitle) {
        sectionTitle.style.fontFamily = "'Libre Baskerville', 'Century Schoolbook', 'Century Gothic', Century, Georgia, serif";
        sectionTitle.style.fontSize = "0.65rem";
        sectionTitle.style.fontWeight = "700";
        sectionTitle.style.letterSpacing = "3px";
        sectionTitle.style.textTransform = "uppercase";
        sectionTitle.style.color = "#888";
    }
    // Couleurs par matière/section
    window._TITLE_COLORS = {
        'philo': '#a78bfa', 'philosophie': '#a78bfa',
        'histoire': '#f97316', 'histoire-geo': '#f97316', 'HISTOIRE - GÉO': '#f97316',
        'géographie': '#34d399',
        'français': '#f87171',
        'maths': '#22c55e',
        'svt': '#34d399',
        'physique': '#60a5fa',
        'anglais': '#fbbf24',
        'a-mediter': '#f59e0b', 'À MÉDITER 😑': '#f59e0b',
        'MATIÈRES': '#888', 'default': '#888'
    };
    window._setTitleColor = function(subjectOrText) {
        if (!sectionTitle) return;
        const col = window._TITLE_COLORS[subjectOrText] || window._TITLE_COLORS['default'];
        sectionTitle.style.color = col;
        sectionTitle.style.textShadow = col !== '#888' ? '0 0 10px ' + col + '44' : 'none';
    };
    backBtn = document.getElementById('back-btn');

    applyNightMode();
    applyChatStyle();
    showSplash(() => {
        initAuth();
        // 🔧 FIX : le bouton "MS." est normalement créé dans firebase-config.js
        // juste après connexion réussie, pour ne pas l'afficher sur l'écran
        // de connexion. Filet de sécurité : si un compte est déjà connecté
        // (session existante) mais que ce callback Firebase tarde ou ne se
        // déclenche pas (ex: reprise d'une session déjà active), on le crée
        // quand même après un court délai — initAIButton() est idempotent
        // (il ne recrée rien si le bouton existe déjà).
        // 🔧 FIX (bouton IA visible sur l'écran "Créer un compte") : l'ancien
        // test vérifiait juste si 'userAccount' existait dans le stockage
        // local — or cette clé contient presque toujours un objet (même
        // vide {}), donc ce filet se déclenchait aussi pour les visiteurs
        // non connectés. On utilise maintenant `isAuth`, le vrai statut de
        // connexion tenu à jour par Firebase, seule source fiable.
        setTimeout(() => {
            try {
                if (isAuth === true && typeof initAIButton === 'function') initAIButton();
            } catch(e) {}
        }, 2500);
        updateHeaderAvatar();
        showStartupQuote();
    });
});
