// ⏱️ CHRONO DISSERTATION 4H
// ═══════════════════════════════════════════════════════════════
var _chronoInterval = null;
var _chronoEndTime = 0;
var _chronoAlerts = [10800,7200,3600,1800,600];
var _chronoAlertsDone = [];

function showChronoDissert() {
    currentLevel = 'chrono-dissert';
    updateHeaderBtns();
    sectionTitle.innerText = 'CHRONO DISSERTATION';
    mainGrid.style.gridTemplateColumns = '1fr';
    mainGrid.innerHTML = '';

    const saved = localStorage.getItem('ms_chrono_end');
    const now = Date.now();
    const isRunning = saved && parseInt(saved) > now;
    _chronoEndTime = isRunning ? parseInt(saved) : 0;
    _chronoAlertsDone = JSON.parse(localStorage.getItem('ms_chrono_alerts') || '[]');

    const wrap = document.createElement('div');
    wrap.style.cssText = 'padding:20px 0;text-align:center;';
    wrap.innerHTML = `
        <div style="font-size:0.6rem;font-weight:900;letter-spacing:2px;color:#4ade80;margin-bottom:20px;">⏱️ CHRONO DISSERTATION</div>
        <div id="chrono-ring" style="position:relative;width:200px;height:200px;margin:0 auto 28px;">
            <svg width="200" height="200" style="position:absolute;top:0;left:0;transform:rotate(-90deg);">
                <circle cx="100" cy="100" r="88" fill="none" stroke="#1a2e00" stroke-width="10"/>
                <circle id="chrono-arc" cx="100" cy="100" r="88" fill="none" stroke="#4ade80" stroke-width="10"
                    stroke-dasharray="553" stroke-dashoffset="0" style="transition:stroke-dashoffset 1s linear;"/>
            </svg>
            <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;">
                <div id="chrono-display" style="font-size:2.4rem;font-weight:900;color:#fff;letter-spacing:2px;font-variant-numeric:tabular-nums;">4:00:00</div>
                <div id="chrono-phase" style="font-size:0.65rem;color:#4ade80;font-weight:700;margin-top:4px;letter-spacing:1px;">—</div>
            </div>
        </div>
        <div id="chrono-alerts-list" style="margin:0 auto 24px;max-width:320px;"></div>
        <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap;">
            <button id="chrono-start-btn" onclick="_startChrono()" style="padding:14px 32px;background:linear-gradient(135deg,#166534,#15803d);border:none;border-radius:16px;color:#fff;font-size:0.9rem;font-weight:900;cursor:pointer;">${isRunning ? '⏸️ Pause' : '▶️ Démarrer'}</button>
            <button onclick="_resetChrono()" style="padding:14px 20px;background:#1a1a1a;border:1px solid #333;border-radius:16px;color:#666;font-size:0.9rem;cursor:pointer;">↺ Reset</button>
        </div>
        <div style="margin-top:24px;background:#0a1400;border:1px solid #4ade8022;border-radius:16px;padding:16px;max-width:320px;margin-left:auto;margin-right:auto;">
            <div style="font-size:0.58rem;color:#4ade80;font-weight:900;letter-spacing:1.5px;margin-bottom:10px;">PLAN DE LA SÉANCE</div>
            <div style="font-size:0.72rem;color:#666;line-height:2;">
                <div>📖 <b style="color:#aaa;">0:00 — 0:30</b> — Analyse du sujet + brouillon</div>
                <div>✏️ <b style="color:#aaa;">0:30 — 3:30</b> — Rédaction (Intro + 3 parties)</div>
                <div>🔍 <b style="color:#aaa;">3:30 — 4:00</b> — Relecture et corrections</div>
            </div>
        </div>
    `;
    mainGrid.appendChild(wrap);

    if (isRunning) { _runChrono(); } else { _updateChronoDisplay(4 * 3600); }
}

function _startChrono() {
    const btn = document.getElementById('chrono-start-btn');
    if (_chronoInterval) {
        clearInterval(_chronoInterval); _chronoInterval = null;
        if (btn) btn.innerHTML = '▶️ Reprendre';
    } else {
        if (!_chronoEndTime || _chronoEndTime <= Date.now()) {
            _chronoEndTime = Date.now() + 4 * 3600 * 1000;
            _chronoAlertsDone = [];
            localStorage.setItem('ms_chrono_end', String(_chronoEndTime));
            localStorage.setItem('ms_chrono_alerts', '[]');
        }
        _runChrono();
        if (btn) btn.innerHTML = '⏸️ Pause';
    }
}

function _runChrono() {
    if (_chronoInterval) clearInterval(_chronoInterval);
    _chronoInterval = setInterval(function() {
        const remaining = Math.max(0, Math.floor((_chronoEndTime - Date.now()) / 1000));
        _updateChronoDisplay(remaining);
        _checkChronoAlerts(remaining);
        if (remaining <= 0) {
            clearInterval(_chronoInterval); _chronoInterval = null;
            localStorage.removeItem('ms_chrono_end');
            _showChronoAlert('TEMPS ÉCOULÉ ! Posez vos stylos. ⏰', '#ef4444');
        }
    }, 1000);
}

function _resetChrono() {
    if (_chronoInterval) { clearInterval(_chronoInterval); _chronoInterval = null; }
    _chronoEndTime = 0; _chronoAlertsDone = [];
    localStorage.removeItem('ms_chrono_end');
    localStorage.removeItem('ms_chrono_alerts');
    _updateChronoDisplay(4 * 3600);
    const btn = document.getElementById('chrono-start-btn');
    if (btn) btn.innerHTML = '▶️ Démarrer';
    const phase = document.getElementById('chrono-phase');
    if (phase) phase.innerText = '—';
    const list = document.getElementById('chrono-alerts-list');
    if (list) list.innerHTML = '';
}

function _updateChronoDisplay(remaining) {
    const h = Math.floor(remaining / 3600);
    const m = Math.floor((remaining % 3600) / 60);
    const s = remaining % 60;
    const display = document.getElementById('chrono-display');
    if (display) display.innerText = h + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
    const total = 4 * 3600;
    const ratio = remaining / total;
    const arc = document.getElementById('chrono-arc');
    if (arc) {
        arc.style.strokeDashoffset = String(553 * (1 - ratio));
        arc.style.stroke = remaining < 600 ? '#ef4444' : remaining < 1800 ? '#f59e0b' : '#4ade80';
    }
    const phase = document.getElementById('chrono-phase');
    if (phase) {
        if (remaining > 3 * 3600) phase.innerText = '📖 Analyse du sujet';
        else if (remaining > 1800) phase.innerText = '✏️ Rédaction';
        else if (remaining > 0) phase.innerText = '🔍 Relecture';
        else phase.innerText = '⏰ Terminé !';
    }
}

function _checkChronoAlerts(remaining) {
    const msgs = {
        10800: { text: '3h restantes — Passez à la rédaction !', color: '#4ade80' },
        7200:  { text: '2h restantes — Gardez le rythme 💪', color: '#4ade80' },
        3600:  { text: '1h restante — Accélérez !', color: '#f59e0b' },
        1800:  { text: '30min restantes — Finissez votre dernière partie !', color: '#f59e0b' },
        600:   { text: '10min — RELECTURE MAINTENANT !', color: '#ef4444' }
    };
    for (const sec in msgs) {
        if (remaining <= parseInt(sec) && !_chronoAlertsDone.includes(sec)) {
            _chronoAlertsDone.push(sec);
            localStorage.setItem('ms_chrono_alerts', JSON.stringify(_chronoAlertsDone));
            _showChronoAlert(msgs[sec].text, msgs[sec].color);
            if (Notification.permission === 'granted') {
                new Notification('MusicSchool ⏱️', { body: msgs[sec].text });
            }
        }
    }
}

function _showChronoAlert(text, color) {
    const list = document.getElementById('chrono-alerts-list');
    if (list) {
        const item = document.createElement('div');
        item.style.cssText = 'display:flex;align-items:center;gap:8px;background:#0d0d0d;border:1px solid ' + (color||'#4ade80') + '44;border-radius:10px;padding:8px 12px;margin-bottom:6px;text-align:left;';
        item.innerHTML = '<div style="font-size:0.72rem;color:' + (color||'#4ade80') + ';font-weight:700;">' + text + '</div>';
        list.prepend(item);
    }
    showToast('⏱️ ' + text);
}


