// ── GÉNÉRATION IA — Dissertation complète ───────────────────────
async function showDissertationIA(notionIdx, sujetIdx) {
    const notion = BAC_SUJETS_DATA[notionIdx];
    const sujet = notion.sujets[sujetIdx];

    currentLevel = 'dissertation-ia';
    window._currentBacNotionIdx = notionIdx;
    window._currentBacSujetIdx = sujetIdx;
    updateHeaderBtns();
    sectionTitle.innerText = 'DISSERTATION IA';
    mainGrid.style.gridTemplateColumns = '1fr';

    // Écran de chargement animé
    mainGrid.innerHTML = `
        <div id="dissert-loading" style="grid-column:1/-1;text-align:center;padding:60px 20px;">
            <div style="font-size:2.5rem;margin-bottom:20px;animation:pulse 1.5s infinite;">🤖</div>
            <div style="font-size:0.9rem;font-weight:900;color:#fff;margin-bottom:8px;">L'IA rédige ta dissertation…</div>
            <div style="font-size:0.72rem;color:#555;margin-bottom:24px;">Introduction · 3 parties · Conclusion</div>
            <div style="max-width:260px;margin:0 auto;height:4px;background:#1a1a1a;border-radius:99px;overflow:hidden;">
                <div id="dissert-progress" style="height:100%;width:0%;background:linear-gradient(90deg,#8a2be2,#a855f7);border-radius:99px;transition:width 0.4s ease;"></div>
            </div>
            <div id="dissert-step" style="font-size:0.65rem;color:#555;margin-top:12px;letter-spacing:1px;">ANALYSE DU SUJET…</div>
        </div>
    `;

    // Animation de progression fake pendant la génération
    const steps = ['ANALYSE DU SUJET…','CONSTRUCTION DU PLAN…','RÉDACTION INTRO…','DÉVELOPPEMENT…','CONCLUSION…'];
    let stepIdx = 0;
    const progressEl = document.getElementById('dissert-progress');
    const stepEl = document.getElementById('dissert-step');
    const fakeProgress = setInterval(() => {
        stepIdx = Math.min(stepIdx + 1, steps.length - 1);
        if (progressEl) progressEl.style.width = ((stepIdx / steps.length) * 85) + '%';
        if (stepEl) stepEl.textContent = steps[stepIdx];
    }, 2200);

    // Construire les auteurs pour le prompt
    const auteursPour = sujet.pour.map(a => `${a.auteur} (${a.oeuvre}, ${a.date})`).join(', ');
    const auteursCentre = sujet.contre.map(a => `${a.auteur} (${a.oeuvre}, ${a.date})`).join(', ');
    const problematique = sujet.problematiques && sujet.problematiques[0] ? sujet.problematiques[0] : sujet.titre;

    const prompt = `Tu es un professeur de philosophie préparant un élève de Terminale au BAC français (programme ivoirien/CEDEAO).

Rédige une dissertation philosophique COMPLÈTE et DÉTAILLÉE sur le sujet suivant :

SUJET : "${sujet.titre}"
NOTION : ${notion.notion}
PROBLÉMATIQUE : ${problematique}

AUTEURS À UTILISER :
- Pour (thèse) : ${auteursPour}
- Contre (antithèse) : ${auteursCentre}

CONSIGNES STRICTES :
1. Rédige en français soutenu, niveau Terminale BAC
2. Structure : Introduction (accroche + problématique + annonce du plan) → Partie I → Partie II → Partie III → Conclusion
3. Chaque partie : 1 sous-titre clair + développement de 3-4 paragraphes + exemples concrets + citations courtes des auteurs
4. Introduction : commence par une accroche originale (exemple de la vie courante OU citation frappante)
5. Conclusion : bilan + ouverture sur une autre problématique
6. Longueur : environ 800-1000 mots au total
7. Ne numérote pas avec "I. II. III." — utilise des titres clairs entre [[ ]]

FORMAT DE SORTIE :
[[INTRODUCTION]]
texte...

[[PARTIE I — titre de la partie]]
texte...

[[PARTIE II — titre de la partie]]
texte...

[[PARTIE III — titre de la partie]]
texte...

[[CONCLUSION]]
texte...`;

    try {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: 'claude-sonnet-4-20250514',
                max_tokens: 1000,
                messages: [{ role: 'user', content: prompt }]
            })
        });

        clearInterval(fakeProgress);

        const data = await response.json();
        const texte = data.content && data.content[0] ? data.content[0].text : '';

        if (!texte) throw new Error('Réponse vide');

        _renderDissertation(texte, sujet, notion, notionIdx, sujetIdx);

    } catch (err) {
        clearInterval(fakeProgress);
        mainGrid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;padding:40px 20px;">
                <div style="font-size:2rem;margin-bottom:16px;">⚠️</div>
                <div style="font-size:0.88rem;color:#e74c3c;font-weight:800;margin-bottom:8px;">Erreur de connexion</div>
                <div style="font-size:0.75rem;color:#555;margin-bottom:24px;">Vérifie ta connexion internet et réessaie.</div>
                <div onclick="showDissertationIA(${notionIdx},${sujetIdx})"
                    style="display:inline-block;padding:12px 28px;background:#8a2be2;border-radius:14px;color:#fff;font-weight:800;cursor:pointer;font-size:0.85rem;">
                    🔄 Réessayer
                </div>
            </div>
        `;
    }
}

// ── RENDU DE LA DISSERTATION ────────────────────────────────────
function _renderDissertation(texte, sujet, notion, notionIdx, sujetIdx) {
    // Parser les sections [[TITRE]]
    const sections = [];
    const regex = /\[\[([^\]]+)\]\]\s*([\s\S]*?)(?=\[\[|$)/g;
    let match;
    while ((match = regex.exec(texte)) !== null) {
        sections.push({ titre: match[1].trim(), contenu: match[2].trim() });
    }

    // Si le parsing échoue, afficher tout brut
    if (sections.length === 0) {
        sections.push({ titre: 'DISSERTATION', contenu: texte });
    }

    const sectionColors = {
        'INTRODUCTION': '#8a2be2',
        'CONCLUSION': '#f39c12',
    };
    const partieColor = notion.color;

    let html = `<div style="grid-column:1/-1;">`;

    // En-tête du sujet
    html += `
        <div style="background:linear-gradient(135deg,#141020,${notion.color}18);border:1px solid ${notion.color}33;border-radius:16px;padding:16px 18px;margin-bottom:16px;text-align:center;">
            <div style="font-size:0.62rem;color:${notion.color};letter-spacing:2px;font-weight:700;margin-bottom:6px;">${notion.emoji} ${notion.notion.toUpperCase()} · DISSERTATION IA ✨</div>
            <div style="font-size:0.92rem;font-weight:900;color:#fff;line-height:1.4;">${sujet.titre}</div>
        </div>
    `;

    // Sections
    sections.forEach(function(s) {
        const isIntro = s.titre.toUpperCase().includes('INTRO');
        const isConcl = s.titre.toUpperCase().includes('CONCL');
        const isPart = s.titre.toUpperCase().includes('PARTIE') || s.titre.match(/^(I|II|III|IV)\b/);

        const color = isIntro ? '#8a2be2' : isConcl ? '#f39c12' : partieColor;
        const bg = isIntro ? 'rgba(138,43,226,0.06)' : isConcl ? 'rgba(243,156,18,0.06)' : 'rgba(20,16,32,0.8)';
        const border = isIntro ? '#8a2be233' : isConcl ? '#f39c1233' : notion.color + '33';
        const emoji = isIntro ? '📌' : isConcl ? '🎯' : '📖';

        // Formater le contenu : sauts de ligne → paragraphes
        const paragraphes = s.contenu.split(/\n\n+/).filter(p => p.trim());
        const contenuHtml = paragraphes.map(p =>
            `<p style="font-size:0.82rem;color:#ccc;line-height:1.75;margin:0 0 12px 0;">${p.replace(/\n/g, '<br>')}</p>`
        ).join('');

        html += `
            <div style="background:${bg};border:1px solid ${border};border-radius:16px;padding:18px;margin-bottom:12px;">
                <div style="font-size:0.62rem;color:${color};letter-spacing:2px;font-weight:800;margin-bottom:12px;">${emoji} ${s.titre}</div>
                ${contenuHtml}
            </div>
        `;
    });

    // Bouton copier + rejouer
    html += `
        <div style="display:flex;gap:10px;margin-top:4px;margin-bottom:20px;">
            <div onclick="_copyDissertation()" style="flex:1;padding:13px;background:#111;border:1px solid #222;border-radius:14px;text-align:center;cursor:pointer;font-size:0.78rem;color:#888;font-weight:700;">
                📋 Copier le texte
            </div>
            <div onclick="showDissertationIA(${notionIdx},${sujetIdx})" style="flex:1;padding:13px;background:linear-gradient(135deg,#1a0a2e,#2a0a40);border:1px solid #8a2be244;border-radius:14px;text-align:center;cursor:pointer;font-size:0.78rem;color:#a855f7;font-weight:800;">
                🔄 Nouvelle version
            </div>
        </div>
    `;

    html += `</div>`;
    mainGrid.innerHTML = html;

    // Stocker texte brut pour la copie
    window._lastDissertText = texte;
}

// ── COPIER DISSERTATION ─────────────────────────────────────────
function _copyDissertation() {
    if (!window._lastDissertText) return;
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(window._lastDissertText)
            .then(() => showToast('📋 Dissertation copiée !'))
            .catch(() => _fallbackCopy(window._lastDissertText));
    } else {
        _fallbackCopy(window._lastDissertText);
    }
}

function _fallbackCopy(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;opacity:0;';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast('📋 Dissertation copiée !');
}


