// ─── ANIMATION MONTÉE DE NIVEAU ───────────────────────────────
// Appelée automatiquement après awardXP si le niveau a changé

(function _hookLevelUp() {
    const _origAwardXP = window.awardXP || awardXP;
    function _awardXPWithLevelCheck(amount, reason) {
        const before = getCurrentLevel(getXPData().xp);
        _origAwardXP(amount, reason);
        const after = getCurrentLevel(getXPData().xp);
        if (before.label !== after.label) {
            setTimeout(() => _showLevelUpScreen(after), 600);
        }
    }
    window.awardXP = _awardXPWithLevelCheck;
})();

function _showLevelUpScreen(level) {
    const existing = document.getElementById('ms-levelup-overlay');
    if (existing) existing.remove();

    const overlay = document.createElement('div');
    overlay.id = 'ms-levelup-overlay';
    overlay.style.cssText = `
        position:fixed;inset:0;z-index:99998;
        background:rgba(5,0,15,0.92);backdrop-filter:blur(4px);
        display:flex;flex-direction:column;align-items:center;justify-content:center;
        animation:fadeIn 0.3s ease;
    `;
    overlay.innerHTML = `
        <div id="ms-confetti-container" style="position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:1;"></div>
        <div style="position:relative;z-index:2;text-align:center;padding:32px 24px;max-width:340px;">
            <div style="font-size:3.5rem;margin-bottom:8px;animation:bounceIn 0.5s ease;">⬆️</div>
            <div style="font-size:0.72rem;color:#a855f7;font-weight:900;letter-spacing:3px;margin-bottom:12px;">NIVEAU SUPÉRIEUR !</div>
            <div style="font-size:2rem;font-weight:900;color:#fff;margin-bottom:6px;">${level.label}</div>
            <div style="font-size:0.82rem;color:#888;margin-bottom:32px;line-height:1.5;">Tu progresses vraiment 💪<br>Continue comme ça pour le BAC !</div>
            <button onclick="document.getElementById('ms-levelup-overlay').remove()"
                style="padding:14px 40px;border-radius:16px;background:linear-gradient(135deg,${level.color},${level.color}99);border:none;color:#fff;font-size:0.92rem;font-weight:900;cursor:pointer;font-family:inherit;">
                Let's go ! 🚀
            </button>
        </div>
    `;
    document.body.appendChild(overlay);
    _launchConfetti(level.color);

    // Fermer automatiquement après 5s
    setTimeout(() => {
        const el = document.getElementById('ms-levelup-overlay');
        if (el) { el.style.opacity = '0'; el.style.transition = 'opacity 0.4s'; setTimeout(() => el.remove(), 400); }
    }, 5000);
}

function _launchConfetti(color) {
    const container = document.getElementById('ms-confetti-container');
    if (!container) return;
    const colors = [color, '#ffffff', '#a855f7', '#f59e0b', '#22c55e'];
    for (let i = 0; i < 60; i++) {
        setTimeout(() => {
            const el = document.createElement('div');
            const c = colors[Math.floor(Math.random() * colors.length)];
            const size = 6 + Math.random() * 8;
            const startX = Math.random() * 100;
            const duration = 2 + Math.random() * 2;
            const delay = Math.random() * 1.5;
            el.style.cssText = `
                position:absolute;top:-20px;left:${startX}%;
                width:${size}px;height:${size}px;
                background:${c};border-radius:${Math.random()>0.5?'50%':'2px'};
                animation:confettiFall ${duration}s ${delay}s ease-in forwards;
                opacity:0.9;
            `;
            container.appendChild(el);
        }, i * 30);
    }
    // Ajouter l'animation CSS si pas déjà présente
    if (!document.getElementById('ms-confetti-style')) {
        const style = document.createElement('style');
        style.id = 'ms-confetti-style';
        style.textContent = `
            @keyframes confettiFall {
                0% { transform:translateY(0) rotate(0deg); opacity:0.9; }
                100% { transform:translateY(110vh) rotate(720deg); opacity:0; }
            }
            @keyframes bounceIn {
                0% { transform:scale(0.5); opacity:0; }
                60% { transform:scale(1.2); }
                100% { transform:scale(1); opacity:1; }
            }
        `;
        document.head.appendChild(style);
    }
}

// ─── BONUS XP WEEK-END ────────────────────────────────────────
// Le vendredi soir, samedi et dimanche → XP x2

function _getXPMultiplier() {
    const day = new Date().getDay(); // 0=dim, 5=ven, 6=sam
    const hour = new Date().getHours();
    if (day === 0 || day === 6 || (day === 5 && hour >= 18)) return 2;
    return 1;
}

// On intercepte awardXP pour appliquer le multiplicateur week-end
(function _hookWeekendBonus() {
    const _prev = window.awardXP;
    window.awardXP = function(amount, reason) {
        const mult = _getXPMultiplier();
        const finalAmount = mult > 1 ? amount * mult : amount;
        const finalReason = mult > 1 ? reason + ' 🎉 x' + mult + ' Week-end !' : reason;
        _prev(finalAmount, finalReason);
    };
})();

// Afficher un bandeau "XP x2 ce week-end !" si applicable
(function _showWeekendBanner() {
    if (_getXPMultiplier() < 2) return;
    setTimeout(() => {
        if (document.getElementById('ms-weekend-banner')) return;
        const banner = document.createElement('div');
        banner.id = 'ms-weekend-banner';
        banner.style.cssText = `
            position:fixed;bottom:80px;left:50%;transform:translateX(-50%);
            background:linear-gradient(135deg,#7c3aed,#a855f7);
            color:#fff;font-size:0.78rem;font-weight:900;
            padding:10px 20px;border-radius:30px;
            z-index:9000;box-shadow:0 4px 20px #a855f744;
            white-space:nowrap;cursor:pointer;
            animation:fadeIn 0.4s ease;
        `;
        banner.textContent = '🎉 Week-end : XP x2 jusqu\'à lundi !';
        banner.onclick = () => banner.remove();
        document.body.appendChild(banner);
        setTimeout(() => banner.remove(), 6000);
    }, 3000);
})();

